window.HB_TR["joshua"]["ks"]=["1. وۅنۍ آو خداوند سُند خادم موسیٰ سٕندِ مرنہٕ پتہٕ یہِ سپدُن زِ خداوند کٔر موسیٰ سٕندِس وزیر نُن سٕندِس نیچوِس یشوع سٕندِس سٍتـ̡ وونُن، \n2. موسیٰ میون خادم چُھ موٗدمُت۔ تێلہِ وۆتھ، یێمہِ اردنس اپارِ گژھ تہٕ یِم سارِنٕے لُکھ یێمہِ زمینس کُن یُس بہٕ تِمن دِوان چُھس، {حتیٰ کہ} بنی اسرٲیلِس تہِ۔ \n3.\\tپریتھ جایہ یُس چانہِ کھورِ ہُند تُل پکان آسہِ، یُس میہ ژے دِژمُت چھُ، یِتھہٕ کٔنۍ مے موسیٰ ہس ووٚنمُت۔ \n4.\\tبیابان تہٕ یَتھ لبنان پؠٹھٕ بٔڈِس دٔریاوَس تام، دریائے فرات تام، حِتِین ہٕندِس سارِنٕے سرزمینس تام، تہٕ آفتابہٕ کِس لوسنہٕ کِس بٔڈِس سمندرس تام، آسہِ تُہند ساحل۔ \n5.\\tکانہہ تہِ انسان ہیکہِ نہٕ تۅہہِ برونہہ کُن روزِتھ، یِتھٕ پٲٹھۍ بہٕ موسیٰ سٕندِس سٍتـ̡ اوسس، تہٕ بہٕ روزٕ نہٕ ژے سٍتـ̡ تہٕ نہ ژے تراوُن۔ \n6. مضبوٗط تہٕ حوصلہٕ مند روٗزِو: تِکیازِ یِمن لوٗکَن کٔرِو وَرثہٕ خٲطرٕ زمین بٲگراونہٕ، یُس بہٕ تِہنٛدین مٲلِن دِنُک حلف چھُس دِوان۔ {اَتھ مُطٲبِق...: یا کٔرِو یِمن لوٗکَن ہٕندِس زمینُک وَرث، وغیرہ}\n7.\\tصرف گژھہِ مضبوط تہٕ بہادر روزُن، یُس میانہِ بندہ موسیٰ سُند حکم دِژمُت چھُ، تۅہہِ کٔرِو سارِنٕے قانونس مُطٲبق عمل کرنُک عمل یُس میانہِ بندہ موسیٰ سٕندِ حُکُم دِژمُت چھُ: اَمہ سٍتـ̡ دٔچھِنـ̡ اَتھٕ کُن تہٕ کھوورِ طرفہٕ پھیرِو نہٕ یُتھ تہِ گژھِو تُہۍ کُنہِ تہِ گژھِ۔ {خوشحالی: یا کٔرِو دانشمندی سٍتـ̡\n8.\\tشریعتٕچ یہ کتاب گژھِ نہٕ تۅہہِ ہٕندِس ٲسِس منزٕ نیرٕنۍ۔ مگر توہی روزِو اَتھ مَنٛز دۅہ راتس مراقبہٕ، یُتھ کُنہِ چیزس مُطٲبق یُس اتھ مَنٛز لیکھنہٕ آمُت چھُ، تِکیازِ تیلہِ کٔرِو تۅہہ پنٕنۍ وتھ خۄشحال تہٕ تیلہٕ میلہِ جان کامیٲبی۔ {ہاو...: یا کٔرِو دانشمندی سٍتـ̡\n9. کیا مے چُھہ نہٕ ژے حُکُم دِژمُت؟ مضبوٗط تہٕ اصل حوصلہٕ تھاوُن۔ خوفزدہ گژھ نہٕ تہٕ نہ گژھ مایوس گژھُن، کیازِ خداوند چُھہ تُہند خدا چُھہ توے سٍتـ̡ یێتہِ تہِ گژھِ۔ \n10. یشوع ہن دِژ لُکن ہٕندِس افسرن حُکُم دِتھ وونُن، \n11.\\tلشکرس مٔنزۍ نیرُن، تہٕ لوکن کٔرِو حُکُم تہٕ وَنُن زِ تُہٕندِس خدایہِ سٍتـ̡ دِیُو تُہٕندِس زمینس پیٹھ قبضہ کرنہٕ خٲطرٕ۔ \n12.\\tتہٕ روبینن تہٕ گادِس تہٕ منسی قبیلس سٍتـ̡ وونُن یشوع سٍتـ̡ وونُن، \n13.\\tسُہ کلام یاد تھاوُن یُس خداوند سٕندِ بندہ موسیٰ سُند حکم دِیُتمُت چھُ، یُس خداوند تُہٕندِس خداہَن دِیُت تہٕ دِژُن یہِ زمین۔ \n14.\\tتُہٕنزِ زنانہٕ، تُہٕندِس لۅکٹِس تہٕ چاروٲے روزن تتھ زمینس مَنٛز یُس موسىٰ ہن یَتھ طرفہٕ اردن دِژمُت چھُ۔ مگر تُہۍ گژھِو پننین باین برونہہ کُن، سارِنٕے طاقتور بہادر نفرن ہٕندِس برونہہ کُن نیرِو، تہٕ تِمن ہٕنز مدد کٔرِو۔ {ہتھیار بند: ہیب۔ پانژو سٍتـ̡ مارشل}\n15. یوتام نہٕ خداوند تُہٕندٮ۪ن باین آرام دِیُت، یِتھ کٔنۍ تُہہِ دِژمُت چُھ، تہٕ تِمن تہِ آسہِ سُہ زمینہٕ حٲصِل کٔرِتھ یُس خداوند تُہند خدا تِمن دِژمُت چُھ، تێلہِ گژھِو تُہۍ پننہِ ملکیتٕچ زمینس مَنٛز واپس یِتھ تہٕ تُہُند لُطف تُلُن، یُس موسىٰ سٕندِ خادمَن یَتھ طرفہٕ یُس آفتاب کھسنہٕ کُن دِژمُت چھُ۔ \n16. تہٕ تِمو دیُت یشوع ہس جواب دِتھ زِ یُس ژے اسہِ حکم دِوان چُھ، أسۍ کرو تہٕ ییتہِ تہِ ژے اسہِ سوزِو، أسۍ گژھو نیران۔ \n17. یِتھٕ پٲٹھـ̡ أسـ̡ موسىٰ سٕندِ کُنہِ کُنہِ چیزس مَنٛز بوزو، تِتھے پٲٹھـ̡ چُھہ أسـ̡ تُہٕندِس خداہس سٍتـ̡ سٍتـ� \n18.\\tیُس تہِ تہندِس حکمس خلاف بغاوت کرِ، تہٕ تۅہہِ ہٕندِس حُکمس مَنٛز تہٕ تُہٕندِس حُکمس سٍتـ̡ بوزِ نہٕ، سُہ گژھہِ مارنہٕ یُن: صرف گژھہِ مضبوٗط تہٕ جان بہادر روزُن۔","1.\\tتہٕ یشوع سٕندِ نیچوِس سوٗزۍ شیتِم منزٕ زٕ نفر ژوٗرِ پٲٹھۍجاسوسی کرنہٕ خٲطرٕ، وونُن زِ گژھ زمینہٕ وُچھِو، یریحا تہِ۔ تہٕ تِم گٔیہِ أکِس بدکار سٕندِس مکانس منز، یٔمِس راحاب ناو اوس، تہٕ اَتہِ روزُن۔ {سوزمُت: یا، اوس سوزمُت} {رٔٹِمُت: ہیب۔ لے}\n2.\\tتہٕ یریحہ کِس بادشاہس وونُن زِ وُچھِو یِمن ہٕندِس مُلکس ژھانڈنہٕ خٲطرٕ رٲژ رٲژ اِسرٲیلِکۍ نفر آمٕتۍ۔ \n3. تہٕ یریحا کِس بادشاہن سوٗز راحابس نِش یہِ ونان زِ تِم نفر أنِو یِم تۅہہِ نِش آمٕتۍ، یِم تُہٕندِس گرس مَنٛز دٲخل گٔیہِ، تِکیازِ تِم یِن سارِنٕے مُلکس ژھانڈنہٕ خٲطرٕ یِن۔ \n4.\\tتہٕ زنانہِ رٔٹِتھ رٔٹِتھ ژٔلِتھ ژٔلِتھ تہٕ وونُن یِتھٕ پٲٹھۍ، اَمہ نِش آیہ مرد آمٕتۍ، مگر بہٕ چھُس نہٕ پتاہ زِ تِم کتہِ ٲسۍ۔ \n5.\\tتہٕ دروازٕ بند گژھنہٕ وِزِ گۆو یہِ وِزِ ییلہ انہِ گوٚٹ گوٚو، مرد گٔیہِ نٮ۪بر: ییتہِ مرد کوٚت گٔیہ، بہٕ ووت نہٕ: تِمن پَتہٕ۔ تِکیازِ تِمن پَتہٕ پٔکِو۔ \n6.\\tمگر سۅ ٲس تِم مکانہٕ کِس چھتس تام أنِمٕژ، تہٕ یِم چھتس پیٹھ ترتیب دِنہٕ آمٕتۍ ٲسۍ۔ \n7.\\tتہٕ مرد لٔگۍ تِمن پَتہٕ اردن کُن وتہِ پَتہٕ، تہٕ یُتھ تِم یِمن پَتہٕ پَتہٕ لٔگِتھ گٔیہِ، تِمو کٔر دروازٕ بنٛد۔ \n8.\\tتہٕ امہ برونہہ زِ تِم تراونہٕ برونہہ ٲس سۅ تِمن نِش چھتس پیٹھ۔ \n9. تہٕ تٔمۍ ووٚن مردن زِ بہٕ چُھس پتاہ زِ خداوند چُھ ژےٚ زمین دِژمٕژ، تہٕ تُہند دہشت چُھ اسہِ پیٹھ پیومُت، تہٕ یہِ زِ زمینٕکۍ سٲری بسکیٖن دِنہٕ آمٕتۍ چِھہ تۅہہِ سٍتـ̡ بے ہوش گٔمٕتۍ۔ {بیہوش: ہیب۔ پٔلِتھ}\n10.\\tکیازِ اسہِ چُھ بوزمُت زِ کِتھہ پٲٹھـ̡ چُھہ خداوند سٍتـ̡ بحرِ احمرُک آب تہٕ یێلہِ تہٕ یێلہِ تہٕ تُہۍ مصر منزٕ نیرِو۔ تہٕ یێلہِ تہٕ یێلہِ دۆیمہِ طرفہٕ اردن، سِحون تہٕ اوگ، یِم ژے پوٗرٕ پٲٹھـ̡ تباہ کٔرِو۔ \n11. تہٕ یێلہِ أسـ̡ یێلہِ أسـ̡ {یِم کتھ} بوٗزِتھ، سانہِ دِل گٔیہِ، تێلہِ ہٕندِس مۅکھہٕ سٍتـ̡ بێیہِ ہُند ہمت تہٕ بێیہِ ہُند ہمت چُھہ تُہٕندِس خداہس سٍتـ̡ خدا۔ {کیا تتہِ...: ہیب۔ وۆتھ}\n12. تێمہِ کِنۍ چُھس بہٕ ژے دُعا کٔرِتھ، خداوند سٕندِ قسم، یێلہِ بہٕ چُھہ ژے مہربانی ہٲومٕژ، تہٕ دِیُن میانہِ مٲلہِ سٕندِس گرس سٍتـ̡ مہربانی تہٕ دِیُن مےٚ اکھ پٔزۍ نشانہٕ: \n13.\\tتہٕ یُس تہٕ تُہۍ بچٲوِو میون مول تہٕ میانہِ موج تہٕ میانہِ بٲے تہٕ میانہِ بینہِ تہٕ تِمن نِش سارِنٕے سٍتـ̡ زِندٕ بچٲوِتھ تہٕ سانہِ زُو مرنہٕ نِش بچٲوِو۔ \n14.\\tتہٕ مردو دیت أمِس جواب، سون زُو چانہِ خٲطرٕ، اگر نہٕ ژیہ یہ سون کارنامہٕ وَنُن۔ تہٕ یێلہِ یێلہِ خداوند اسہِ زمین دِژ، أسۍ کرو ژے سٍتـ̡ مہربانی تہٕ پٔزۍ پٲٹھۍ۔ {for...: Heb. ژے بجایہ مرُن}\n15.\\tتمہ پتہ ترٲو تم دارِ منزہ رزِ سٍتۍ، تکیازِ تسند مکانہ اوس شہرک دیوارس پیٹھ، تہٕ سۅ ٲس دیوارس پیٹھ روزان۔ \n16.\\tتہٕ تٔمۍ ووٚن تِمَن زِ تُہۍ نِیِو پہاڑس کُن، نتہٕ پیچھا کرن وٲلۍ یِن مِلنہٕ۔ تہٕ تَتہِ روٗزِو تریہ دۅہہٕ ژوٗرِ، یوٚت تام پیچھا کرن وٲلۍ واپس یِن: تہٕ پتہٕ گژھِو تُہۍ پننہِ وتہِ نیرِ۔ \n17.\\tتہٕ مردو ووٚن أمِس زِ أسـ̡ چُھہ تُہٕندِس حلفس سٍتـ̡ بے عیب یُس ژے اسہِ حلف دِژمُت چُھ۔ \n18.\\tوُچھو، {ییلہِ} أسۍ زمینس مَنٛز وٲتِو، تہٕ ژے کٔرِو پنُن مول تہٕ پنٕنۍ موج تہٕ پنٕنۍ بٲے تہٕ پننِس مٲلہِ سٕندِس سارِنٕے گرس پانس نِش اَننہٕ۔ {أنِو: ہیب۔ جمع کٔرِو}\n19. تہٕ یہِ گژھہِ زِ یُس تہِ تُہٕندِ گَرِ ہٕندِ دروازٕ منزٕ سڑکہِ منزٕ نیرِ، تٔمِس سُند خوُن آسہِ تٔمِس کلَس پیٹھ، تہٕ أسۍ گژھہِ بے قصور: تہٕ یُس تہٕ یُس تہٕ یُس تہِ گرس منز آسہِ، تٔمۍ سُند خون آسہِ سٲنِس کلس پیٹھ، اگر کانہہ تہِ اتھہٕ آسہِ۔ \n20. تہٕ اگر ژے یہ سانہِ کاربار کٔرِو، تیلہِ گژھو أسۍ چانہِ قسمہ نِش آزاد یُس ژے اسہِ قسمہ دِژمُت چھُ۔ \n21.\\tتہٕ تٔمۍ ووٚن، چانہِ کلامَس مُطٲبق تہٕ تِمو گٔیہِ دٲرِ منز سرخ لٲگ۔ تہٕ تٔمۍ سوٗزۍ تِم دٲرِ منز سرخ لٲگ۔ \n22.\\tتہٕ تِم گٔیہِ تہٕ پہاڑس پیٹھ وٲتِتھ تہٕ روٗدۍ تریہ دۅہہ، یوٚت تام پیچھا کرن وٲلۍ واپس آو، تہٕ پیچھا کرن والیو ژھانڈ سارِوٕے وتہِ، مگر لٔبِکھ نہٕ۔ \n23.\\tیێمہِ دۅشوے نفر واپس، تہٕ بالہٕ پیٹھٕ ؤسِتھ گٔیہِ نُن سٕندِس نیچوِس یشوع ہس نِش، تہٕ وونُن تِمن سارِنٕے چیزن ہٕندِس سٍتـ̡ ۔ \n24. تہٕ تِمو ووٚن یشوعہس زِ پٔزۍ پٲٹھـ̡ خداوند چُھ سٲنـ̡ سارِنٕے زمینہٕ سٲنـ̡ اَتھن مَنٛز دِژمُت۔ تِکیازِ مُلکٕکۍ سٲری بسکیٖن در تہِ چِھ سانہِ سٍتـ̡ بێہوش گَژھان۔ {بێہوش: Heb. Melt}","1. تہٕ یشوع ووت صبحٲے سُلہٕ۔ تہٕ تِمو ہیوٚت شِتِم پیٹھ، تہٕ یِمو وٲتِتھ اردن کُن، سُہ تہٕ سارِنٕے بنی اِسرٲیلِی، تہٕ یِمن ہٕندِ نیرنہٕ برونہہ گٔیہِ اَتہِ روزنہٕ۔ \n2. تہٕ تریہ دۅہہٕ پَتہٕ سپُد یہ زِ افسر گٔیہِ میزبانس نِش۔ \n3. تہٕ تِمو دِژ لُکن ہُند حُکُم، یێلہِ یێلہِ تُہۍ خداوند پَنٕنِس خدایہِ سٕندِس عہدُک صندوق وُچھِو، تہٕ پادٕرۍ یِم یہِ ہیتھ ٲسِو، تێلہِ گژھِو پننہِ جایہِ پیٹھٕ ہٹِتھ تہٕ اَتھ پَتہٕ نیرُن۔ \n4.\\tتوتہِ آسہِ توے تہٕ اتھ درمیان اکھ فاصلہ، تقریباً زٕ ساس کیوبِٹ: اتھ نزدیک گژھ نہٕ، یُتھ وتہِ گژھہِ پَکُن: تکیازِ توے چُھہ نہٕ از تام وتہِ پٔکِتھ۔ {امہ برونہہ تہِ: ہیب۔ راتھ تہٕ تریمہِ دۅہہ}\n5. تہٕ یشوع ہن ووٚن لُکن زِ پَنُن پان پاک کٔرِو، تِکیازِ پَگہہ خداوند کرِ تُہٕندِس مَنٛز معجزات۔ \n6. تہٕ یشوع ہن ووٚن پادٕرین سٍتـ̡ کتھ زِ عہدُک صندوق تُلِو تہٕ لُکن برونہہ کُن گٔژھِو۔ تہٕ تِمو تُل عہدُک صندوق تہٕ لُکن برونہہ کُن۔ \n7. تہٕ خداوند ووٚن یشوع سٕندِس دۅہٕ بہٕ سارِنٕے اسرٲیلِس سٍتـ̡ تُہٕندِس سٍتـ̡ بٔرِتھ تہٕ یێلہِ بہٕ تہٕ یێلہِ تہٕ بہٕ تہٕ یێلہِ تہٕ یێلہِ تہٕ بہٕ آسہٕ تۅہہِ سٍتـ̡ ۔ \n8.\\tتہٕ توے کٔرِو پادٕرین ہُند حُکُم یِم عہد نامہٕ رٔٹِتھ چھِ، تہٕ وَنُن زِ یێلہِ تُہۍ اردن کِس آبس کِس بٹھس پیٹھ وٲتِو، تێلہِ گژھِو اردنس مَنٛز کھڑا روزُن۔ \n9. تہٕ یشوع ہن ووٚن بنی اسرٲیل، یور یور تہٕ بوزو خداوند پنُن خدا۔ \n10. تہٕ یشوع ہن ووٚن، اَتھ سٍتـ̡ گژھہِ تۅہہِ پتاہ زِ زندٕ خدا چُھہ تۅہہِ منز، تہٕ سُہ کٔرِہ بێیہِ کنعانی، حِتی، حِوی، تہٕ پیرزی، تہٕ گرگاشی، تہٕ امورِی، تہٕ یبوسی ژٔلِتھ۔ \n11.\\tوچھو سارِنٕے زمینہِ ہٕندِس خداوند سٕندِ عہدُک صندوق چُھ توے برونہہ کُن اردنس مَنٛز واتان۔ \n12.\\tتێلہِ کٔرِو تم باہ نفر اسرائیلی قبیلو منز، پریتھ قبیلہ منزہ اکھ انسان۔ \n13.\\tتہٕ یێلہِ سارِنٕے زمینُک رب خداوند سٕندِس صندوقس ہٕندِس پادٕرَن ہٕندِس قدمن ہٕندِس تلوُے یِم سارِنٕے زمینہِ ہٕندِس آبس مَنٛز آرام کٔرِتھ، {یُس} اردنُک آب گژھہِ ژٹنہٕ یُس ہیرِ پیٹھٕ وسان چُھ۔ تہٕ تِم گژھن أکِس ڈھیرس پیٹھ کھڑا ۔ \n14.\\tتہٕ سپُد ییلہ لُکھ پننیو خیمو منزٕ نیرِتھ اردن کُن نیرِتھ تہٕ پادٕرۍ ٲسۍ لوکن برونہہ کنہِ عہد نامہٕ ہُند صندوق ہٮ۪تھ۔ \n15. تہٕ یِتھٕ پٲٹھۍ یِم صندوقہٕ نِش نِنہٕ آمٕتۍ ٲسۍ، تہٕ یِمن پادٕرین ہٕندِس قدمس سٍتـ̡ آبہٕ کِس دٔرِس سٍتـ̡ ڈباونہٕ آمٕتۍ، (تکیازِ اردن چُھ سارِنٕے بٔٹھہِ سٍتـ̡ فصلہٕ وِزِ بٔرِتھ بٔرِتھ،)\n16.\\tیُس آب ہیرِ پیٹھٕ وسان اوس، سُہ اوس آدم شہرس نشہِ واریاہ دور أکِس ڈھیرس پیٹھ کھڑا گومُت، یعنی زرتنس نِش {چُھ} تہٕ یِم میدانی سمندرس کُن وسان ٲسۍ، {تہ} نوٗنہٕ سمندرس کُن تہِ گٔیہِ ناکام، {تہٕ} ژٹنہٕ آمٕتۍ، تہٕ لُکھ گٔیہِ یریحاہس کُن دٔرۍ۔ \n17.\\tتہٕ یِم پادٕرۍ خداوند سٕندِ عہدُک صندوق تُلِتھ رودۍ اردن کِس وسطس مَنٛز خۄشٕک زمینس پیٹھ کھڑا تہٕ سارِنٕے اسرٲیلِیو گٔیہِ خۄشٕک زمینہِ پٲٹھۍ، یوتام سارِنٕے لُکھ اردن کِس مَنٛز پاک گٔیہِ۔","1. تہٕ سپُد یێلہِ سارِوٕے لُکھ یُس اردنس مَنٛز پاک گٔیہِ، خداوند وۆن یشوع سٍتـ̡ وَنُن \n2. تم کٔرِو باہ نفر لُکن منز، پرٮ۪تھ قبیلہٕ منزٕ اکھ نفر، \n3. تہٕ تِمن کٔرِو حُکُم، یێلہِ نِش نِیو اردن منز، تتھ جایہِ نِش یێلہِ پادٕرٮ۪ن ہٕندِس قدمن مضبوط، باہ کٔنہِ، تہٕ تِم پانس سٍتـ̡ نِن، تہٕ تِم ترٲوِو روزنٕچ جایہ، یێتہِ تُہۍ از رٲژ روزِو۔ \n4. یشوع ہن بُلووُن بہن نفر، یُس تٔمۍ بنی اسرٲیلِس منزٕ تیار کورمُت اوس، پرٮ۪تھ قبیلہٕ منزٕ اکھ شخٕص بُلوو: \n5. تہٕ یشوع ووٚن تِمن زِ خداوند پنُن خدا سٕندِس صندوقس برونہہ کُن ژٔلِو اردن کِس باگَس مَنٛز، تہٕ تُلِو پرٮ۪تھ أکِس انسانس تٔمِس پھیکس پیٹھ اکھ کٔن، یُس بنی اسرٲیلِین ہٕندِس قبیلن ہٕندِس تعدادس مُطٲبق تُلُن: \n6.\\tیُتھ زِ یہِ گژھہِ تۅہہِ مَنٛز اکھ نشانہٕ، {یہ} یێلہِ تُہٕندِس مٲلِس یِنہٕ وٲلِس وقتس سٍتـ̡ پرژھہِ، یہِ وَنُن زِ یِمن کٔنـ̡ کیا چُھہ تُہٕندِس مَطلَب سٍتـ̡؟ {وقتس منز...: ہیب۔ پگہہ کُن}\n7. تیلہِ دِیُو تِمن جواب زِ اردنُک آب آو خداوند سٕندِ عہد کِس صندوقس برونہہ کُن ژٹنہٕ۔ یێلہِ سُہ اردنس پٔکِس پٲٹھـ̡ ژٹنہٕ آمُت، تہٕ یِم کٔنہِ روزن بنی اِسرٲیلـ̡ ہٕندِ خٲطرٕ ہمیشہٕ خٲطرٕ یادگار۔ \n8. تہٕ بنی اسرٲیلیو کٔر یشوع سٕندِ حُکمہٕ سٍتـ̡ تہٕ تُلِکھ اردن کِس درمِیان باہ کٔنہِ، یِتھ کٔنۍ خداوند یشوع سٕندِس قبیلن ہٕندِس تعدادس مُطٲبق کٔرِتھ تہٕ تِم پانس سٍتـ̡ تتھ جایہِ نِتھ ییتہِ تِم روزان ٲسۍ۔ \n9. تہٕ یشوع کٔر اردن کِس درمِیان باہ کٔنہِ، تتھ جایہِ یُس پادٕرین ہٕندِس قدمس یِم عہدُک صندوق نِش کھڑا ٲسۍ، تہٕ تِم چھِ از تام موجود۔ \n10. یِمو پادٕرۍ یِم صندوقہٕ نِش رٔٹِتھ ٲسۍ، یوتام سارِوٕے کُنہِ کتھہِ مُکمل سپدِ، یێلہِ زن خداوند یشوع ہس سٍتـ̡ لُکن سٍتـ̡ کتھ کرنُک حُکُم دِیُت، یُس موسىٰ سُند حُکُم اوس دِژمُت، تہٕ لُکھ گٔیہِ جلدی تہٕ گٔیہِ پٔکۍ۔ \n11.\\tتہٕ سپُد یێلہِ سارِوٕے لُکھ صاف گٔیہِ، یێلہِ گٔیہِ خداوند سُند صندوق تہٕ پادٕرۍ لُکن ہٕندِس حٲضِرِس مَنٛز۔ \n12. تہٕ روبن سٕندِ اولاد، گاد سٕندِ اولاد، تہٕ مَنسِہ سٕندِ نصف قبیلہٕ گٔیہِ اسرٲیلِس برونہہ کُن ہتھیار بٔنِتھ، یِتھ کٔنۍ موسىٰ تِمن ووٚنمُت: \n13. جنگہٕ خٲطرٕ تقریباً ژتٲجی ساس گٔیہِ جنگہٕ خٲطرٕ خداوند سٕندِ برونہہ کُن یریحو کِس مٲدانس کُن۔ {تیار: یا، تیار ہتھیار بند}\n14. اَمہِ دۅہہٕ کٔر خداوند یشوع سارِنٕے اسرٲیلِس مَنٛز بڑاو۔ تہٕ تِمو کھوژان أمِس سٍتـ̡ یِتھٕ پٲٹھۍ تِمو موسىٰ سٕندِس سارِنٕے دۅہہٕ کھوژان ٲسۍ۔ \n15. تہٕ خداوند ووٚن یشوع ہس سٍتـ̡ وونُن، \n16.\\tیِمن پادٕرین یِم گوٲہی ہُند صندوق تھاوان چھِ، تِم گژھن اردن پیٹھٕ نیرنُک حُکُم۔ \n17.\\tیشوع ہن دیُت پادٕرین حُکُم تہٕ وونُن زِ یێلہِ ہُند ح \n18.\\tتہٕ سپُد یێلہِ یێلہِ یِم پادٕرۍ یِم خداوند سٕندِ عہدُک صندوق نِش نِش وٲتِتھ، {تہٕ} پادٕرین ہٕندِس کھۅرن ہٕندِس تُلِس خشک زمینس کُن تُلنہٕ آمٕتۍ، یێلہِ اردنُک آب آو پننہِ جایہ واپس، تہٕ ووت تٔمۍ سٕندِس سارِنٕے بٔٹھِس پیٹھ، یِتھٕ پٲٹھـ̡ {تِمو گوڈ} کٔرِتھ۔ {تُلِمُت...: حب۔ تُلُن} {بہاوُن: حب۔ گٔیہِ}\n19.\\tتہٕ لُکھ آو گۄڈنِکہِ رٮ۪تہٕ کِس دٔہمہِ دۅہہٕ اردن منزٕ نیبر تہٕ یریحو کِس مشرقی سرحدس مَنٛز لٔگِتھ گِلگلَس مَنٛز ڈیرٕ ترٲو۔ \n20.\\tتہٕ تِم باہ کٔنہِ، یِم تِمو اردن منزٕ نِنہٕ آمٕتۍ، یشوع کٔر گلگلس مَنٛز۔ \n21.\\tتہٕ تٔمۍ ووٚن بنی اِسرٲیلِس سٍتـ̡ وَنُن زِ یێلہِ تُہٕندِس شُرِ یِنہٕ وٲلِس پَنٕنـ̡ پَنٕنـ̡ پى۪ٹھـ̡ پرژھن، یِمن کٔنـ̡ کیا چُھہ؟ {وقتس منز...: Heb. پَگہہ کُنـ̡\n22. تیلہِ گژھہِ پننین شُرین یہ ؤنِتھ زِ اسرٲیل آو اتھ اردنس پیٹھ خشک زمینہِ پیٹھ۔ \n23. خداوند تُہند خداہٕ چُھہ ژے برونہہ کُن اردنُک آب خشک کٔرِتھ، یوتام نہٕ تۅہہ اپارِ گٔیہِ، یِتھ کٔنۍ تُہند خداہِ سُہ بحر احمرس سٍتـ̡ ہوٚکھمُت، یُس تٔمۍ اسہِ برونہہ کُن ہۄکھمُت اوس، یوتام أسـ̡ أسـ̡ گٔیہِ: \n24.\\tیُتھ زِ زمینہِ ہٕندِس سارِنٕے لُکھ گژھن خداوند سُند اَتھٕ زانن، یُتھ زِ یہِ {چُھ} طاقتور چُھہ، یُتھ تُہۍ ہمیشہٕ خٲطرٕ خداوند پنُن خدایہ سُند خوف تھاوُن۔ {ہمیشہٕ خٲطرٕ: ہیب۔ سارِنٕے دۅہہ}","1.\\tتہٕ سپُد یہِ سپدُن، یێلہِ امورین ہٕندِس سارِنٕے بادشاہن، یِم اردن کِس مغربس کُن ٲسۍ، تہٕ کنعانی ہٕندِس سارِنٕے بادشاہو یِم سمندرٕ کِس بٔٹھِس کُن ٲسۍ، بوز زِ خداوند اوس اردنُک آب یُس بنی اسرٲیلِس برونہہ کُن اوس، یێلہِ تِہُند دِل گۆو تہٕ تِمن مَنٛز اوس نہٕ روح تہِ، یێلہِ أسـ̡ بنی اسرٲیلـ̡ ہٕندِ وجہ سٍتـ̡۔ \n2. اَمہِ وِزِ خداوند ووٚن یشوعہس زِ ژے بناو تیزدار چُرۍ، تہٕ دوٚیمہِ لٹہِ کٔرِو اسرٲیلِکۍ اولاد ختنہٕ۔ {تیز...: یا، چُرِ چُرۍ}\n3. تہٕ یشوع بنوو أمِس تیز چُرۍ، تہٕ کٔرٕن اسرٲیلِکۍ بچہٕ ختنہٕ۔ {تیز...: یا چُرِ چُرۍ} {بال...: یا، گیبیاہ ہارلوتھ}\n4.\\tتہٕ یۅہے وجہ چھہ یشوع ین ختنہ کرنُک وجہ۔ مصرہ منزہ نیبر نیرن وٲلس سٲری لوکھ یم مرد ٲسۍ، {حتیٰ کہ} سٲری جنگی مرد تہِ سپد وتہِ بیابانن منز، مصرہ منزہ نیرنہ پتہٕ۔ \n5.\\tوۅنۍ یِم سارِنٕے لُکھ نیبر نیران ٲسۍ، تِم ٲسۍ ختنہ کٔرِتھ، مگر تِمو سارِنٕے لُکھ یِم مصرہٕ منزٕ نیرِتھ بیابانن مَنٛز زامٕتۍ، تِمو اوس نہٕ ختنہ کٔرِتھ۔ \n6.\\tکیازِ بنی اسرٲیلِس پٔکِتھ بیابانن مَنٛز ژتٲجی ؤری پٔکۍ، یوتام سارِنٕے لُکھ یِم مصرہٕ منزٕ نیران ٲسۍ، تِکیازِ تِمو کٔر نہٕ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری: یٔمِس خداوند سٕندِس سٍتـ̡ قَسم کٔرِتھ زِ سُہ دِیہِ نہٕ تِمن زمینہٕ ہاونہٕ، یُس خداوند تِہندین مٲلن سٍتـ̡ قسم دِیُت زِ سُہ دِیہِ اسہِ دِنہٕ، سُہ زمین یُس دۄد تہٕ ماچھ سٍتـ̡ وسان آسہِ۔ \n7.\\tتہٕ تِہندِ شُرۍ، یِمن ہٕندِ بدلہٕ پرورش کٔرِتھ، یشوع کٔر ختنہٕ، تکیازِ تِم ٲسۍ نہٕ ختنہٕ کٔرِتھ، تِکیازِ تِمو اوس نہٕ وتہِ ختنہٕ کٔرمٕتۍ۔ \n8.\\tتہٕ سپُد ییلہ تِمو سارِنٕے لُکن ختنہ کٔرِتھ، تِم رودۍ خٲمس مَنٛز پنٕنـ̡ جایہ روزُن، یوتام تِم پوٗرٕ گٔیہِ۔ {تِمو ٲس...: حب۔ لُکو اوس ختنہ کرنُک خاتمہ کورمُت}\n9. تہٕ خداوند ووٚن یشوعہس زِ اَمہ دۅہہ چُھس میہ ژے نِش مصرُک ملامت دِنہٕ آمُت۔ اَمہِ مۄکھٕ چُھ از تام اتھ جایہِ ہُند ناو گلگل وننہٕ یوان۔ {گلگل: یہِ چُھ رولنگ}\n10.\\tتہٕ اِسرٲیلِیو کٔر گِلگالَس مَنٛز ڈیرٕ ترٲوِتھ تہٕ ریتھ کِس ژۄدٲہِمہِ دۅہہٕ کٔرِکھ فسح یریحہ کِس مٲدانس مَنٛز تہِ۔ \n11.\\tتہٕ تِمو کھیوٚو پگہہ دۅہہ فسح پَتہٕ زمینہٕ کِس پرانہِ مکایہ، خمیر روٚس کیک تہٕ أتھۍ دۅہس منز خشک کٔرِتھ۔ \n12.\\tتہٕ پَگہہ دۅہہ گٔیہِ مَنَن ہٕندِس پرٲنِس مَژٕ کھٮ۪نہٕ پتہٕ۔ نَہ اوس اِسرٲیلِیَن ہٕندِس مَنَس مَنَس سٍتـ̡ وُنہِ تہِ ۔ مگر تِمو کھیوٚو تَمہِ ؤرۍ یہِ کنعان کِس سرزمینہٕ کِس مٮ۪وٕ سٍتـ̡ ۔ \n13. تہٕ سپُد یِشوع یریحہس نِش یِنہٕ وِزِ تٔمۍ کٔر أچھ تُلِتھ تہٕ وُچھُن أمِس سٍتـ̡ تلوار تُلِتھ کھڑا تہٕ یشوع گوٚو أمِس نِش تہٕ وونُن تٔمِس نِش تہٕ وونُن تُہۍ چھُکھ سانہِ خٲطرٕ یا سانین مُخٲلفن ہٕندِ خٲطرٕ؟ \n14.\\tتہٕ تٔمۍ ووٚن، نہٕ۔ مگر یُس خداوند سٕندِس لشکرُک کپتان چُھس بہٕ وُنہِ آمُت۔ تہٕ یشوع پیوٚو زمینس کُن بُتھِس پیٹھ، تہٕ کٔرٕن عبادت تہٕ وونُن، میون رب کیا چُھ پننِس خادمس ونان ؟ {کپتان: یا، شہزادہ}\n15.\\tتہٕ خداوند سٕندِ لشکرٕکۍ کپتانن ووٚن یشوعس زِ پَنُن کھورِ نِش ترٛاوُن پَنُن جوُر۔ یَتھ جایہِ تہٕ یَتھ جایہِ تُہۍ کھڑا چھِو سُہ چھُ مُقدس۔ تہٕ یشوع ہن کٔر یۅہے کٔرِتھ۔","1.\\tوۅنۍ اوس یریحا بنی اسرائیل کِس مۅکھہ بند کرنہٕ آمُت: کانہہ تہِ دراو نہٕ نیبر، تہٕ نہ آو کانہہ تہِ۔ {اوس...: ہیب۔ بند گوو، تہٕ اوسُکھ بند گومُت}\n2. تہٕ خداوند ووٚن یشوعس زِ وُچھ، مے چُھس یریحو تہٕ تٔمِس بادشاہس تہٕ بہادر نفر تہٕ دِژمُت تُہٕندِس اتھس مَنٛز۔ \n3.\\tتہٕ تُہۍ کٔرِو شہرس اندۍ پکھۍ گٔژِھتھ، سارِنٕے جنگی نفر، {تہٕ} شہرس اندۍ پکھۍ پھیُرُن۔ یِتھٕ پٲٹھۍ کرو تُہۍ شیہ دۅہ۔ \n4. تہٕ سَتھ پادٕرۍ تُلِن صندوقس برونہہ کُن سَتھ بُرٕ، تہٕ سٔتِمہِ دۅہہٕ یِن شہرس سَتھ لٹہِ گھیرٕن، تہٕ پادٕرۍ وَن صوٗرت سٍتـ̡ وَننہٕ۔ \n5.\\tتہٕ یێلہِ یێلہِ تِم رۅندٕ سٕندِ سینگ سٍتـ̡ زیوٹھ پھُٹاونہٕ یِن، {تہٕ} ییلہ تُہۍ بُرٕچ آواز بوٗزِ، سارِنٕے لُکھ کٔرِن بٔڈ کرٛٮ۪کہٕ دِنہٕ۔ تہٕ شہرُک دیوار پیوٚو سیدٕ پٲٹھۍ، تہٕ لُکھ گژھن پرٮ۪تھ أکِس انسانس برونہہ کُن کھسنہٕ۔ {چپٹہٕ: ہیب۔ اتھ تلہ کنہِ}\n6. تہٕ نون سٕندِ نیچو یشوع ہن بُلوو پادٕرین تہٕ تِمن وونُن، عہدُک صندوق تُلِو، تہٕ سَتھ پادٕرۍ رٔنگۍ سٕندِس صندوقس برونہہ کُن رٔٹِتھ رٔٹِتھ ۔ \n7.\\tتہٕ تٔمۍ ووٚن لُکن زِ یُس ہتھیار بند چُھہ یُس خداوند سٕندِس صندوقس برونہہ کُن نیرُن۔ \n8. تہٕ سپُد یێلہِ یشوع ہن لُکن سٍتـ̡ کتھ کٔرِتھ زِ سَتھ پادٕرۍ یِم رٔنگہِ ہٕندِس سٍتـ̡ بٔرِتھ گٔیہِ خداوند سٕندِ سٍتـ̡ پى۪ٹھ۔ \n9.\\tتہٕ ہتھیار بند نفر گٔیہِ پادٕرین برونہہ کُن یِمو بُرٕ وُپھ دِنہٕ آمٕتۍ، تہٕ بدلہٕ آو صندوقس پَتہٕ، {پادٕر} گٔیہِ پٲٹھۍ، تہٕ دِژ بُرٕ دِنہٕ۔ {دُبارٕ: حب۔ جمع کَرُن میزبان}\n10. تہٕ یشوع ہن اوس لُکن ہُند حُکُم دِژمُت زِ یێلہِ نہٕ کرٛٮ۪کہٕ دِنہٕ تہٕ نہ کُنہِ تہِ کُنہِ کُنہِ تہ\n11.\\tیێلہِ گٔیہِ خداوند سٕندِ صندوقہٕ شہرس اندۍ پکھۍ، اکہِ لٹہِ گٔیہِ تہٕ تِم آیہ خٲمس مَنٛز، تہٕ گٔیہِ خٲمس مَنٛز روزنہٕ۔ \n12. تہٕ یشوع ووت صُبحے سُلہِ تہٕ پادریو تُل خداوند سُند صندوق تُل۔ \n13.\\tتہٕ سَتھ پادٕرۍ یِمو خداوند سٕندِ صندوقہٕ برونہہ کُن سَتھ بُرٕے ہٮ۪تھ تہٕ لٔگِکھ بُرٕ دِنہٕ۔ مگر بدلہٕ آو خداوند سٕندِ صندوقس پَتہٕ، {پادٕرۍ} گٔیہِ بُرٕ دِنہٕ۔ \n14. تہٕ دٔیمہِ دۅہہ گٔیہِ تِمو اکہِ لٹہِ شہرس گھیرٕ، تہٕ واپس، یِتھٕ پٲٹھۍ کٔر تِمو شیہ دۄہ۔ \n15.\\tتہٕ سٔتِمہِ دۅہہ سپد تِم سُلہٕ وُتھ، تہٕ سَتھ لٹہِ گٔیہِ شہرس گھیرٕ: صرف تمہِ دۅہہ گٔیہِ تِمو سَتھ لٹہِ شہرس گھیرٕ۔ \n16. تہٕ سٔتِمہِ لٹہِ سپُد یہِ سپُد، یێلہِ پادٕرٮ۪و بُرِ سٍتـ̡ وُن، یشوع ووٚن لُکن کٔرِتھ کرٛٮ۪کھ۔ یێلہِ خداوند چُھہ ژےٚ شہر دِژمُت۔ \n17.\\tتہٕ شہرس گژھہِ لعنت، {حتی} تہِ، تہٕ یُس سارِنٕے {چُھ} چھُ، خداوند سٕندِ خٲطرٕ: صرف راحاب بدکار روزُن، سُہ تہٕ سٲری یُس أمِس سٍتـ̡ گرس مَنٛز روزُن، کیازِ سُہ اوس رسولن ہُند ژوٗرِ تھوومُت یِم أسۍ سوزمٕتۍ ٲسۍ۔ {لعنت: یا، وفادار}\n18.\\tتہٕ تُہۍ چھِو کُنہِ تہِ پٲٹھـ̡ پانس ملعون چیزس نِش بچاوُن، یێلہِ تہٕ یێلہِ تہٕ اسرٲیلُک خٲمہٕ بَناوُن تہٕ تُہٕندِس مُشکِل کٔرِو۔ {لعنت: یا، وفادار} {اکھ لعنت: یا، عقیدت مند}\n19. مگر رۄپہٕ، سۄن، تہٕ پیتل تہٕ ششتٕرٕکۍ بانہٕ چھِ خداوند سٕندِ خٲطرٕ مقدس کرنہٕ آمٕتۍ: تِم گژھن خداوند سٕندِس خزانس مَنٛز یِن۔ {مُقدس: عبری۔ پاکیزگی}\n20.\\tتہ لوکو کٔر کرٛٮ۪کھ ییلہ {پادٕرۍ} بُرِ وُپھ دِژ، تہٕ لوکو کٔر بٔڈ کرٛٮ۪کہٕ دِتھ زِ دیوار پیوٚو سیدِ پٲٹھۍ، تہ لُکھ گٔیہِ شہرس مَنٛز، پرٮ۪تھ کانہہ نفر أمِس برونہہ کُن، تہٕ تِمو رٔٹِتھ شہر۔ {فلیٹ: حب۔ اتھ تلہ کنہِ}\n21.\\tتہٕ تِمو کٔرِکھ شہرس مَنٛز سارِوٕے سُہ {اوس} پوٗرٕ پٲٹھۍ، مرد تہٕ زنانہٕ، جوان تہٕ بُزرگ، تہٕ بیل، تہٕ کۅکر، تلوار ہٕندِ دھار سٍتـ̡ تباہ ۔ \n22.\\tمگر یشوع ہن اوس یمن دۅن نفرن ووٚنمُت یِمو ملکٕچ جاسوٗسی ٲس کٔرمٕژ، گٔژِھتھ گٔژھِو زنانہٕ تہٕ أمِس سٍتـ̡ سُہ تہٕ یُس تٔمِس سٍتـ̡ نِش نِش اوس، یُس تُہۍ أمِس سٍتـ̡ قسم دِوان چھُ۔ \n23.\\tتہٕ یِم جوان جاسوس ٲسۍ، تہٕ أنِکھ راحاب، تہٕ أمۍ سُند مول تہٕ موج، تہٕ تٔمۍ سٕندِس بٲے تہٕ تٔمِس سٍتـ̡ سارِنٕے نِش نیبر۔ تہٕ تِمو أنۍ تٔمۍ سٕندِس سارِنٕے رشتہٕ دار تہٕ تراوُن اسرٲیلِکِس خٲمہٕ ورٲے ۔ {رشتہ دار: عبرانی۔ خاندان}\n24.\\tتہٕ تِمو زٲلِتھ شہر نارٕ سٍتـ̡ تہٕ یێمہِ سٍتـ̡ سُہ سُہ یُس سُہ اوس، صرف رۄپہٕ تہٕ سۄن، تہٕ پیتل تہٕ ششتٕرٕکۍ بانہٕ، یِمو ترٲو خداوند سٕندِس گرٕ کِس خزانس مَنٛز۔ \n25. تہٕ یشوع بچٲو راحاب، تہٕ پننِس مٲلہِ سُند گرٕ تہٕ تٔمِس سارِنٕے سٍتـ̡ یُس أمِس نِش اوس۔ تہٕ سُہ چُھ از تام اسرائیلس مَنٛز روزان۔ تکیازِ تٔمۍ کٔر رسول ژوٗرِ، یِم یشوع ہن یریحو سٕنز جاسوسی کرنہٕ خٲطرٕ سوزمٕتۍ۔ \n26.\\tتہٕ یشوع کٔر اَمہِ وِزِ یِمن ہٕندِس دروازس پیٹھ وونُن، یُس خداوند سٕندِس برونہہ کُن یُس وۅتھان چُھہ، یُس یریحا سٕندِس شہرس تعمیر کرُن، سُہ تراوِ پننِس گۄڈنِکِس زامتس مَنٛز اَمیُک بُنیاد تہٕ پننِس لۅکٹِس نیچوِس مَنٛز بَناوُن اَمیُک دروازٕ۔ \n27. یێلہِ اوس خداوند یشوعس سٍتـ̡ تہٕ تٔمۍ سٕنز شہرت ٲس سٲرۍسٕے مُلکس سٍتـ̡ بٔرِتھ۔","1.\\tمگر بنی اسرٲیلِو کٔر ملعون چیزس مَنٛز گُناہ کٔرِتھ، یُس زَبدی سُند نیچو، زَراح سُند نیچو، یہوداہ قبیلہٕ سُند نیچو آچان ہیوٚت، تہٕ خداوند سُند غصہٕ گۆو بنی اِسرٲیلِس سٍتـ̡ دِنہٕ۔ {عچان: یتھ تہِ ونان چھِ} {زبدی: زِمری تہِ ونان چھِ}\n2. تہٕ یشوع ہن سوٗزۍ یریحو پیٹھٕ نفر آیی کُن، یُس بیت ہاوس نِش بِتھلس نِش چُھ، تہٕ تِمن سٍتـ̡ کتھ کٔرِتھ وونُن زِ ہیوٚر گژھ تہٕ دیُن وُچھُن۔ تہٕ مرد گٔیہِ ہیوٚر تہٕ وُچھُن آی۔ \n3.\\tتہٕ تِم یشوع نِش واپس، تہٕ وونُن تٔمِس زِ سارِنٕے لُکھ گژھن نہٕ ہیوٚر کھسُن۔ مگر دِیُن زٕ تریہ ساس نفر ہیوٚر کھٔسِتھ آیی سٍتـ̡ مارٕنـ̡ {تہٕ} سارِنٕے لُکھ کٔرِن نہٕ اَتہِ محنت کرنہٕ خٲطرٕ۔ تِکیازِ تِم چِھ {مَگَر} کَم ۔ {اَمہِ پٲٹھۍ...: حَب۔ لگ بگ زٕ ساس نفر، یا لگ بھگ ترے ساس نفر}\n4.\\tیِتھٕ پٲٹھـ̡ گٔیہِ لُکن ہٕندِس تقریباً ترے ساس نفر، تہٕ تِم ژٔلِتھ ژٔلِتھ آیی ہٕندِس نفرن برونہہ کُن۔ \n5.\\tتہٕ آیی ہٕندیو نفرو لٔگۍ تِمن لگ بھگ شیترہ نفر، تکیازِ تِمو لٔگۍ تِمن دروازٕ برونہہ کُن شباریم تام تہٕ لٔگِتھ لُکن ہٕندِس دِل گٔیہِ، تہٕ گٔیہِ آبہٕ ہٕندۍ پٲٹھۍ۔ {منز...: یا، مورادس منز}\n6. تہٕ یشوع ژٔٹِتھ پَنُن پلو ژٔٹِتھ تہٕ لوٚگ خداوند سٕندِس صندوقس برونہہ کُن بُتھِس پیٹھ زمینس پیٹھ، سُہ تہٕ اسرٲیلِکۍ بزرگو تہٕ ترووُن تِمن ہٕندِس کلس پیٹھ گرد۔ \n7.\\tتہٕ یشوع ووٚن، اے خدایہ، ژے کیازِ چھُکھ یِم لُکھ اردنس پیٹھ أنِمٕتۍ، تاکہ اسہِ امورین ہٕندِس اتھس مَنٛز دِنہٕ، اسہِ تباہ کرنہٕ مۅکھہٕ۔ کاش أسـ̡ خدایہِ سٍتـ̡ آسـ̡ آسـ̡ تہٕ دوٚیمہِ طرفہٕ اردنس منز روزُن! \n8. اے خداوند، بہٕ کیا وَنُن، یێلہِ اِسرٲیلِس پَنٕنـ̡ دُشمن برونہہ کُن پَنُن پٲٹھـ̡\n9.\\tکنعانی تہٕ زمینہٕ کین سارِنٕے بسکیٖن بٔنِتھ بوزِن تہٕ اسہِ اندۍ پکھۍ رٔلِتھ تہٕ ژٔٹِتھ تہٕ ژے کیا کٔرِکھ پننِس عظیم ناوَس سٍتـ̡ ۔ \n10.\\tتہٕ خداوند ووٚن یشوعس زِ ژے تھوٚد ووٚتھ؛ تہٕ ژے کیازِ چُھکھ پننِس بُتھِس پیٹھ لٔگِتھ؟ {liest: Heb. Fallest}\n11. اسرٲیلَن چُھ گۅناہ کورمُت، تہٕ تِمو تہِ چُھ میانہِ عہدٕچ خلاف ورزی کٔرمٕژ یُس میہ تمن حکم دِتمُت اوس، کیازِ تِمو چُھ ملعون چیز تہِ نِمُت، تہٕ چُھکھ ژوٗرِ نِمُت، تہٕ یِمو چُھ پننین چیزن منز تہِ تھوومُت۔ \n12.\\tتێلہِ ہیوٚک نہٕ بنی اسرائیل پننین دُشمنن برونہہ کُن کھڑا گٔژھِتھ، {مگر} پنہٕ نِس دُشمنن برونہہ کُن پھیُرِتھ، تِکیازِ تِمن ٲس لعنت: بہٕ روزٕ نہٕ وۅنۍ تہٕ تۅہہِ سٍتـ̡ یێلہِ تہٕ \n13.\\tتھوٚد کٔرِو لُکن پاک تہٕ ونُن، پگہہ تام پان پاک کرُن، یِتھٕ پٲٹھـ̡ چُھہ اسرٲیلُک خدا، یێلہِ چُھہ تۅہہِ مَنٛز اکھ لعنتی چیز یێلہِ چُھہ یێلہِ تُہۍ پننین دُشمنن برونہہ کُن کھڑا گژھِتھ، یوتام نہٕ ژے پانس منزٕ ملعون چیز نِش نِنہٕ۔ \n14. تَمہِ مۄکھٕ یِیہِ صُبحَس یُس خداوند نِنہٕ یِیہِ سُہ قبیلہٕ یُس خداوند نِیہِ سُہ یُس خاندانہٕ مُطٲبِق یِیہِ۔ تہٕ یُس عیال خداوند نِیہِ سُہ گژھہِ گرٕ سٍتـ̡ یِنہٕ۔ تہٕ یُس گرٕ خداوند نِیہِ سُہ گژھہِ انسان سٍتـ̡ یِنہٕ۔ \n15.\\tتہٕ یہِ گژھہِ یُس یُس ملعون چیزس سٍتـ̡ نِنہٕ ییہ، سُہ گژھہِ نارٕ سٍتـ̡ زالنہٕ یُن، سُہ تہٕ أمِس سٍتـ̡ سارِنٕے چیزس سٍتـ̡ دزنہٕ یُن: کیازِ تٔمۍ چُھ خداوند سٕندِس معاہدٕچ خلاف ورزی کٔرمٕژ، تہٕ کیازِ تٔمۍ کٔر اسرٲیلِس مَنٛز بیوقوفی کٔرمٕژ۔ {حماقت: یا، بدکاری}\n16. یشوع ووٚتھ صبحٲے سُلہِ تہٕ أنِن اسرٲیلِس تہٕ تِمن ہٕندِس قبیلہٕ سٍتـ̡ اِننہٕ۔ تہٕ یہوداہ قبیلہٕ آو نِنہٕ: \n17.\\tتہٕ سُہ اوٚن یہوداہ سُند عیال۔ تہٕ أمِس نِش زَرِیَن ہُند عیال تہٕ اَنُن زَرِیَن ہُند عیال۔ تہٕ زَبدی آو نِنہٕ: \n18.\\tتہٕ أمِس اوٚن پنُن گرُک آدمی انسانہٕ سٍتـ̡ ۔ تہٕ یہوداہ قبیلہٕ سُند زَبدی سُند نیچو کارمی سُند نیچو آچان آو نِنہٕ۔ \n19. تہٕ یشوع ووٚن اچانس زِ میانہِ نیچو، بہٕ دِژ ژے دُعا کرُن، اسرٲیلِکِس خدایہِ سُند جلال تہٕ أمِس کٔرُن اقرار ۔ تہٕ وَن مے وَن ژے کیا چُھہ کورمُت۔ میہ نِش تہٕ ژوٗرِ نہٕ۔ \n20. تہٕ اچانن دیُت یشوع سُند جواب تہٕ وونُن، پٔزۍ پٲٹھۍ چُھس میہ اسرٲیلِکِس خداوند خداہس خلاف گۅناہ کورمُت، تہٕ یِتھٕ پٲٹھۍ، تہٕ یِتھٕ پٲٹھۍ کورُمُت میہ تہٕ یِتھٕ پٲٹھۍ: \n21.\\tییلہ میہ غنیمتس منز اکھ اصل بابل پوش، تہٕ زٕ ہتھ شیکل رۄپہٕ تہٕ پنژاہ شیکل وزنُک سون اکھ ٹُکرٕ وُچھمُت، تیلہِ کٔر میہ تِمن ہُند لالچ، تہٕ نِیومُت۔ تہٕ وُچھِتھ گٔیہِ تِم میٲنِس خیمہٕ کِس خیمہٕ مَنٛز زمینہِ مَنٛز ژوٗرِتھ، تہٕ اَتھ تلہ کنہِ رۄپہٕ۔ {ویج: ہیب۔ زبان}\n22. یشوع ہن سوٗزۍ قاصد تہٕ تِم ژٔلِتھ خیمس کُن۔ تہٕ وُچھِتھ اوس یہِ پننِس خیمس مَنٛز ژوٗرِ تھوومُت، تہٕ رۄپہٕ تَل کٔرِتھ۔ \n23. تہٕ تِمو کٔرِکھ تِم خیمہ منزٕ نِش تہٕ أنِکھ یشوع تہٕ سارِنٕے بنی اسرٲیلِس نِش، تہٕ کٔرِکھ خداوند سٕندِس برونہہ کُن۔ {لٔگِتھ: عبرانی۔ دِنہٕ}\n24.\\tتہٕ یشوع تہٕ سارِنٕے اسرٲیلِس سٍتـ̡ نِیہِ زَراح سُند نیٚچُو، رۄپہٕ تہٕ پلو تہٕ سۄنہٕ سُند پُل، تہٕ تٔمۍ سٕندِس نیچوِس تہٕ کورِ، تہٕ تٔمۍ سٕندِس گَردٕ تہٕ کۅکرٕ تہٕ تٔمۍ سُند خیمہٕ تہٕ یُس أمِس نِش اوس، تہٕ تِمو أنۍ تِم وادی عخورس مَنٛز۔ \n25. تہٕ یشوع ووٚن، ژے کیازِ چُھکھ اسہِ پریشان کٔرِتھ؟ خداوند کرِ از دۅہہ ژےٚ تُہہِ پریشان۔ تہٕ سارِوٕے اِسرٲیلَن لگٲوۍ أمِس کَنہِ کَنہِ تہٕ نارٕ سٍتـ̡ زٲلِتھ تہٕ کٔرِکھ کَنہِ سٍتـ̡ کَنہِ پٲٹھۍ۔ \n26. تہٕ تِمو تھوٚد از تام أمِس پیٹھ کنن ہُند اکھ بوٚڈ ڈھیر۔ یێلہِ گۆو خداوند پننہِ شَرارتہٕ ہٕندِ شدتہٕ نِش پھیر۔ اَمہِ مۄکھٕ چُھ اَمہ جایہِ ہُند ناو از تام وادی آچور وننہٕ آمُت۔ {اچور: یعنی مصیبت}","1. تہٕ خداوند ووٚن یشوعس زِ خوفزدہ گژھ نہٕ، تہٕ گژھ نہٕ خوفزدٕ: پانس سٍتـ̡ نِیُن سارِنٕے جنگٕکۍ لُکھ تہٕ وُتھِو آیی کُن، وُچھ مے چُھس تۅہہِ ہُند بادشاہ تہٕ تٔمۍ سٕندِس لُکہٕ تہٕ تٔمۍ سٕندِس شہرس تہٕ تٔمۍ سٕنزِ زمینہٕ تہٕ تٔمۍ سٕندِس اتھس منز دِژمُت۔ \n2. تہٕ تُہۍ کٔرِو آیی تہٕ تٔمہِ سٕندِس بادشاہس سٍتـ̡ یِتھے پٲٹھۍ یێرِیحو تہٕ تٔمہِ سٕندِس بادشاہس سٍتـ̡ کٔرِو، صرف اَمہ سٍتـ̡ لوُٹ تہٕ تٔمہِ سٕندِس چاروٲے سٍتـ̡ رٔٹِو۔ \n3. یِتھٕ کٔنۍ ووت یشوع تہٕ سارِنٕے جنگی لُکھ آیی یس خلاف کھسنہٕ خٲطرٕ، تہٕ یشوع کٔر ترٕہ ساس بہادر نفر ژٲرِتھ تہٕ سوٗزِن تِم رٲژ ژٲرِتھ۔ \n4. تہٕ تٔمۍ دِیُت تِمن حُکُم، وَنُن زِ وُچھِو، شہرس پَتہٕ پَتہٕ پٔتِھ، شہرٕ نِش گژھِو نہٕ زیادٕ دوٗر گژھُن، مگر تُہۍ گژھِو سارِوٕے تیار۔ \n5. تہٕ بہٕ تہٕ سٲری لُکھ یِم میہ سٍتـ̡ چِھہ، شہرس کُن گژھن تہٕ یێلہِ یێلہِ تِم اسہِ خٕلاف نیرن، یِتھٕ پٲٹھۍ، أسۍ ژلہِ تِمن برونہہ کُن، \n6. (تِم گژھن اسہِ پَتہٕ نٮ۪بر) یوٚت تام أسۍ تِم شہرٕ نِش نِش نیرِ۔ تِکیازِ تِم وَنَن زِ تِم چھِ اسہِ برونہہ کُن ژلِتھ، یِتھٕ پٲٹھۍ، یِتھٕ پٲٹھۍ، أسۍ ژٔلِو تِمن برونہہ کُن۔ {ڈراوُن: ہیب۔ لٔٹِتھ}\n7. تێمہِ پَتہٕ گژھِو ژٔہلہٕ پٲٹھـ̡ تہٕ شہرس پیٹھ قبضہٕ کٔرِو، یێلہِ خداوند تُہُند خدا دِیہِ یہِ تُہٕندِس اتھس مَنٛز۔ \n8. تہٕ یێلہِ تہ \n9.\\tیشوع سوٗزۍ تِم نیبر، تہٕ تِم گٔیہِ ہملہٕ کٔرِتھ تہٕ آیی کِس مغربس کُن بیتھل تہٕ آیی یس درمِیان روزنہٕ خٲطرٕ، مگر یشوع روٗد تمہِ رٲژ لُکن مَنٛز روزنہٕ۔ \n10. تہٕ یشوع ووت صبحٲے سُلہِ تہٕ لُکن ہُند شُمار تہٕ ووت سُہ تہٕ اسرٲیلٕکۍ بزرگ، لُکن برونہہ کُن آیی کُن۔ \n11.\\tتہٕ سارِوٕے لُکھ {حتیٰ کہ جنگٕکۍ لُکھ تہِ} یِم أمِس سٍتـ̡ ٲسۍ، گٔیہِ ہیوٚر تہٕ نزدیکی تہٕ شہرس برونہہ کُن آیہ، تہٕ آیہ کِس شمالس کُن کھسنہٕ: وۅنۍ ٲس تمن تہٕ آیی یس درمیان اکھ وادی۔ \n12.\\tتہٕ تٔمۍ رٔٹۍ تقریباً پانژھ ساس نفر، تہٕ تِم تھووُن شہر کِس مغربس کُن بیتھل تہٕ آیی یس درمیان حملہٕ کرنہٕ خٲطرٕ۔ {of...: یا، آیی سٕندِ}\n13.\\tتہٕ یێلہِ یێلہِ یِمو لُکہٕ سٲرِسٕے لُکہٕ یُس شہرٕ کِس شمالس کُن اوس، تہٕ تِہٕندِس لُکہٕ سٍتـ̡ شہرٕ کِس مغربس کُن پیارٕ کٔرِتھ، یشوع گۆو تَمہِ رٲژ وادی مَنٛز۔ {لٔرِس...: حب۔ انتظارس منز}\n14.\\tتہٕ سپُد یہِ سپدُن، ییلہ آیی ہٕندِس بادشاہن وُچھ زِ تِم گٔیہِ جلدی تہٕ سُلہٕ ووٚتھ، تہٕ شہرٕکۍ نفر گٔیہِ اسرٲیلِس خلاف جنگہٕ کرنہٕ خٲطرٕ، سُہ تہٕ تٔمۍ سٕندِس سارِنٕے لُکھ أکِس وقتس مُقرر کرنہٕ آمٕتۍ میدانس برونہہ کُن۔ مگر تس اوس نہٕ یہِ خبر زِ شہرس پٔتۍ کُن ٲسۍ أمِس خلاف حملہٕ کٔرِتھ۔ \n15.\\tتہٕ یشوع تہٕ سارِنٕے اِسرٲیلِیو بَنوو یِتھٕ پٲٹھۍ یِمن برونہہ کُن مارنہٕ آمُت، تہٕ ژٔلِتھ بیابان کِس وتہِ کِنـ̡ ۔ \n16.\\tتہٕ یِم سارِنٕے لُکھ آیہ یِمن ہٕندِس پَتہٕ پَتہٕ یِنہٕ خٲطرٕ بُلاونہٕ، تہٕ تِمو گٔیہِ یشوع سٕندِس پَتہٕ پَتہٕ تہٕ گٔیہِ شہرٕ نِش نیرنہٕ۔ \n17.\\tتہٕ آیی تہٕ بیت ایلس مَنٛز اوس نہٕ کانہہ نفر روٗدمُت، یُس نہٕ اسرٲیلِس پَتہٕ نیبر نیرِ، تہٕ تِمو ترٲو شہر یلہٕ تہٕ لٔگۍ اسرٲیلِس پَتہٕ۔ \n18. تہٕ خداوند ووٚن یشوعس زِ نیزٕ یُس پننِس اتھس منز چُھہ آیی کُن پھٔہلٲوِتھ۔ تکیازِ بہٕ دِیہ یہ چانہِ اتھس منز۔ تہٕ یشوع ہن دِژ نیزٕ یُس پننِس اتھس منز اوس، شہرس کُن۔ \n19.\\tتہٕ حملہٕ دراو پننہِ جایہِ نِش جلدی تہٕ تِم ژٔلِتھ ژٔلِتھ یُتھ تٔمۍ پنُن اَتھٕ بڑٲوِتھ، تہٕ تِم ژٔلِتھ شہرس اندر تہٕ رٔٹِتھ تہٕ دِژٕکھ شہرس نار۔ \n20.\\tتہٕ ییلہ آیی ہٕندیو نفرو پتھ کُن نظر دِژ، تمو وُچھ تہٕ وُچھ شہرُک دھواں آسمانس کُن کھسُن، تہٕ تِمن ٲس نہٕ اَتھ کُن ژلنُک کانہہ طاقت، تہٕ یِم لُکھ بیابانن کُن ژلِتھ گٔیہِ تِمن ہُند پٲٹھۍ۔ {طاقت: حب۔ اتھہٕ}\n21.\\tییلہ یشوع تہٕ سارِنٕے اسرٲیلِیو وُچھ زِ حملہٕ چُھ شہرس پیٹھ قبضہ کورمُت، تہٕ شہرُک دھواں کھسُن، تِمو پھیُر دُبارٕ تہٕ مارِکھ آیی ہٕندِس نفر۔ \n22.\\tتہٕ بیٛاکھ درٛاو شہرٕ منزٕ تِمن خٕلاف۔ تہٕ تِم ٲسۍ اِسرٲیلِس منز، کینہہ اَتھ طرفہٕ تہٕ کیٚنٛہہ اَتھ طرفہٕ: تہٕ تِمو دِژ تِمن مَنٛز کانہہ تہِ روزُن تہٕ ژلنہٕ یِنہٕ۔ \n23. تہٕ آیی ہُک بادشاہ یِمو زِندٕ رٔٹِتھ یشوع نِش أنِتھ۔ \n24.\\tتہٕ سپُد یہِ سپدُن، ییلہ اسرٲیلَن آیی ہٕندِس سارِنٕے بسکیٖن دَرس مَنٛز، بیابانَس مَنٛز، یَتھ مَنٛز تِم تِمن ہُند پیچھا کٔرِتھ، تہٕ ییٚلہِ تِم سٲری تلوار ہٕندِس اندس پیٹھ پیوٚو، یوٚت تام تِم ختم گٔیہِ، تہٕ سارِنٕے اِسرٲیلِی گٔیہِ آیی کُن واپس، تہٕ دِتُکھ تلوار ہٕندِ دِلہٕ سٍتـ̡ مارُن۔ \n25.\\tتہٕ {یِتھ} اوس یہِ، {یہ} تمہِ دۅہہ یُس مرد تہٕ زنانہٕ دۅشوے پیوٚو، {ٲس} باہ ساس، {حتیٰ کہ} آیی ہٕکۍ سٲری مرد۔ \n26.\\tیشوع کٔر نہٕ پَنُن اتھہٕ پتھ کُن، ییمہ سٍتـ̡ تٔمۍ نیزٕ پھٔہلٲوِتھ، یوتام تٔمۍ آیی ہٕندِس سارِنٕے بسکینن ہٕندِس بسکیٖن دِنس مُکمل پٲٹھۍ۔ \n27.\\tصرف چاروو تہٕ تمہِ شہرٕچ غنیمت ہیوٚت اسرٲیلَن پانس خٲطرٕ شِکار، یُس یشوع سٕندِ کلامَس مُطٲبق یُس تٔمۍ یشوع سُند حُکُم دِیُت۔ \n28.\\tتہٕ یشوع زٲلۍ آیی تہٕ بنووُن یہ از تام ہمیشہٕ خٲطرٕ اکھ ڈھیر۔ \n29.\\tتہٕ آیی ہُند بادشاہ روٗد شامس تام أکِس کُلِس پیٹھ لٹاونہٕ، تہٕ یُتھُے آفتاب لوسُن، یشوع ہن حکم زِ تِم گژھن تٔمۍ سُند لاش کُلِس پیٹھٕ بۄن تہٕ شہر کِس دروازس منز اژنہٕ وِزِ ترٛاوُن، تہٕ اَتھ پیٹھ تراوُن کٔنٮ۪ن ہُند اکھ بوٚڈ ڈھیر، یُس از تام باقی۔ \n30. پتہٕ بنوو یشوع کِس ایبل پہاڑس مَنٛز اسرٲیلِکِس خدایہِ سٕندِ خٲطرٕ اکھ قربان گاہ، \n31. یِتھ کٔنۍ زَن موسیٰ سٕندِ خادم یِتھ کٔنۍ زَن موسیٰ سٕنزِ شریعت کِس کتابہِ مَنٛز لیکھنہٕ آمُت چھُ، یُس پوٗرٕ کنن ہُند قربان گاہ چُھ، یتھ پیٹھ کٲنسہ تہِ انسان ششتٕر تُلِتھ آسہِ۔ تہٕ تِمو کٔر اَتھ پیٹھ خداوند سٕندِ خٲطرٕ زٲلِتھ نذرانہ پیش تہٕ امن ہٕندِ قربانی دِنہٕ۔ \n32.\\tتہٕ تٔمۍ لیوٗکھ کنن پیٹھ موسیٰ سٕندِ شریعتُک اکھ نسخہٕ، یُس تٔمۍ بنی اسرائیلہٕ ہٕندِس حضورس مَنٛز لیوٗکھمُت۔ \n33.\\tتہٕ سارِوٕے اسرٲیل، تہٕ تِہٕندِس بزرگ، افسر تہٕ تِہٕندِس قاضیَن ہٕندِس اَتھ طرفہٕ تہٕ تِہٕندِس پادٕرَن برونہہ کُن، یُس خداوند سٕندِ عہدُک صندوق تہٕ اجنبی تہِ یُس تِمن مَنٛز زامُت اوس۔ یِمو منزٕ نٮ۪صف کُنہِ گریزِم کِس خٕلافس پیٹھ، تہٕ یِمو منزٕ نٮ۪صف کُنہِ ایبالس خٕلاف۔ یِتھ کٔنۍ زَن موسىٰ سٕندِ خادم اوس امہ برونہہ حُکُم کوٚرمُت زِ تِم گژھن اسرٲیلِکۍ لوکن برکت دِنہٕ۔ \n34.\\tتہٕ پَتہٕ پٔرِتھ شریعت کِس کتابس مَنٛز لیکھنہٕ آمٕتۍ سارِنٕے کُنـ̡ شریعت ہٕندِس سٍتـ̡ شریعت ہٕندِس سٍتـ̡ \n35.\\tیُس موسىٰ سُند حکم اوس دِژمُت، یُس نہٕ یشوع ہن سارِنٕے اسرٲیلِچ جماعت برونہہ کُن، زنانہٕ تہٕ لۄکٹٮ۪ن تہٕ تِمن مَنٛز کتھ باتھ کرن والٮ۪ن ہٕندِس سٍتـ̡ پٔرِتھ پٔرِتھ۔ {ٲسٕن...: حب۔ پٔکِتھ}","1.\\tتہ سپد تمہِ ساعتہ ییلہ سٲری بادشاہ یم اتھ طرفہ اردن، بالن منز، وادین منز، تہ عظیم سمندر کین سارنٕے ساحلن پیٹھ لبنان، حتی، اموری، کنعانی، پیرزی، حوی تہٕ یبوسی کِس تمام ساحلن پیٹھ بوز۔ \n2. یِمو کٔر یشوع سٍتـ̡ تہٕ اِسرٲیلس سٍتـ̡ اَکہٕ سٍتـ̡ لڑنہٕ مۅکھہٕ۔ {معاہدٕ: عبرانی۔ ٲس}\n3. تہٕ ییلہ جبعون کین بسکینو بوز یُس یشوع ہن یریحو تہٕ آیی یس سٍتـ̡ کیا کورمُت، \n4.\\tتِمو کٔر چالاکی سان کٲم تہٕ گٔیہِ تہٕ بٔنِتھ زن تِم سفیر ٲسۍ، تہٕ تُلِکھ پرٲنۍ بۄٹہٕ تہٕ شرابٕچ بوتلہٕ، پرانہِ تہٕ کرایہ تہٕ بٔنِتھ۔ \n5.\\tتہٕ تِمن ہٕندِس کھورِ پٲٹھۍ، تہٕ تِمن ہٕندِس کھورِ پیٹھ پرانہِ پَلَو۔ تہٕ تِمن ہٕندِس رزق ہٕندِس سورے روٹی ٲس خشک تہٕ پھۅپھ گٔژھمٕژ۔ \n6.\\tتہٕ تِم گٔیہِ یشوع نِش گلگل کِس خٲمس مَنٛز، تہٕ وونُکھ أمِس تہٕ اسرٲیلِکۍ لوٗکَن زِ أسۍ چھِ دور دوٗر ملکہٕ پٮ۪ٹھٕ آمٕتۍ، تَمہِ مۄکھٕ کٔرِو اسہِ سٍتـ̡ اتحاد۔ \n7. تہٕ اسرٲیلِیو ووٚن حِویَن زِ تُہۍ چھِو اسہِ مَنٛز روزان۔ تہٕ أسۍ کِتھہٕ کٔنۍ کٔرِو توے سٍتـ̡ اتحاد؟ \n8. تہٕ تِمو ووٚن یشوعہس زِ أسۍ چِھہ تُہند خادم۔ تہٕ یشوع ہن ووٚن تِمن زِ تُہۍ کُس چھِو؟ تہٕ کتہِ پیٹھہٕ آو؟ \n9. تہٕ تِمو ووٚن أمِس زِ تُہٕندِس خدایہِ سٕندِس ناوٕ سٍتـ̡ چُھہ یێمہِ سٕندِ ناوٕ سٍتـ̡ سٍتـ̡ یێلہِ أسـ̡ تٔمۍ سٕنز شہرت بوزمٕژ تہٕ یُس تٔمۍ سُند مصرس مَنٛز کورمُت چُھ، \n10.\\tتہٕ یُس تمٔۍ امورین ہٕندِس دۄن بادشاہن سٍتـ̡ کٔر، یُس اردن اپارِ ٲس، ہیشبون کِس بادشاہس سِحون تہٕ بشان کِس بادشاہس سٍتـ̡ یُس اشتاروتس مَنٛز اوس۔ \n11. اَمہِ مۄکھٕ چُھہ سانہِ زِٹھاہ تہٕ سٲنِس ملکٕکۍ سارِنٕے بسکیٖن دِنہٕ آمٕتۍ زِ سفرس خٲطرٕ نِیُن پانس سٍتـ̡ نِیُن تہٕ تِمن سٍتـ̡ مِلنہٕ خٲطرٕ، تہٕ تِمن وَنُن زِ أسـ̡ چُھہ چُھہ تُہٕندِس خادمَس سٍتـ̡ رٔلِتھ تہٕ وَنُن زِ أسـ̡ چُھہ چُھہ تُہٕندِس خادمَس سٍتـ̡ رٔلِتھ ۔ {ژے سٍتـ̡: حب۔ تُہندس اتھس منز}\n12.\\tیۅہے سانہِ روٹی ٲس تۅہہِ نِش گژھنہٕ مۅکھہ پننیو گرو منزٕ پننہ رزق نِش گرم کٔرِتھ۔ مگر وۅنۍ چھہ یہ خشک تہ پھپھ گومُت۔ \n13.\\tتہٕ یِم شرابٕچ بوتلہٕ، یِم أسۍ بٔرۍمٕتۍ، نٔوۍ ٲسۍ۔ تہٕ وُچھِو یِم کٔرِتھ تہٕ یِم پَلَو تہٕ سانہِ بوُٹھ گٔیہِ واریاہ زیٖٹھہِ سفرٕ کِنۍ پرٛٲنۍ۔ \n14.\\tتہٕ مردو رٔٹِتھ رٔٹِتھ تہٕ پرژھکھ نہٕ خداوند سٕندِس نِشہِ {مشورٕ}۔ {مرد...: یا، تِمو رٔٹِتھ مرد پننہِ مصلحتہٕ کِنۍ}\n15.\\tتہٕ یشوع ہن کٔر تِمن سٍتـ̡ صلح تہٕ تِمن سٍتـ̡ کٔرٕن تِمن سٍتـ̡ زِندٕ روزنہٕ خٲطرٕ، تہٕ جمٲژ ہٕندِس شہزادن کٔر تِمن سٍتـ̡ حلف۔ \n16.\\tتہٕ تریہ دۅہہ سپدِتھ سپد تِمو سٍتـ̡ تِمن سٍتـ̡ ہمسایہ تہٕ تِمن سٍتـ̡ روزان چِھہ تِمن سٍتـ̡ روزان۔ \n17.\\tتہٕ بنی اسرٲیلِیو سفر تہٕ تریمہِ دۅہہ آیہ پننین شہرن منز۔ وۅنۍ ٲسۍ تِہندِ شہر گِبیون، تہٕ چفیرا، تہٕ بیروتھ تہٕ کِرجاتیرِم۔ \n18.\\tتہٕ بنی اسرٲیلِیو دِژ نہٕ تِمن مار، تِکیازِ جمٲژ ہٕندِیو شہزادو اوس تِمن سٍتـ̡ اسرٲیلِکِس خدایہِ سٕندِ سٍتـ̡ قَسم کٔرمُت۔ تہٕ سارِنٕے جمٲژ کٔر شہزادن خلاف گڑبڑ۔ \n19. مگر سارِوٕے شہزادو ووٚن سارِنٕے جمٲژ سٍتـ̡ ، أسـ̡ چُھہ تِمن سٍتـ̡ اسرٲیلِکِس خدایہِ سٕندِ سٍتـ̡ حلف کورمُت، تێلہِ چُھہ نہٕ أسـ̡ تِمن سٍتـ̡ اَتھٕ لاگُن۔ \n20. أسۍ کرو تِمن سٍتـ̡ یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ أسـ̡ تِمن سٍتـ̡ قٕسم۔ أسـ̡ دِو تِمن سٍتـ̡ زِندٕ روزُن، یێلہِ سٍتـ̡ أسـ̡ تِمن سٍتـ̡ قٕسم کٔرِتھ یێ \n21.\\tتہٕ شہزادو ووٚن تِمن زِندٕ روزن۔ مگر تِم گژھن سارِنٕے جمٲژ ہٕندِ خٲطرٕ لٔکرِ تہٕ آب کھیننہٕ وٲلۍ۔ یِتھہٕ کٔنۍ شہزادو تِمن وعدٕ کورمُت۔ \n22. تہٕ یشوع ہن بُلوو تِمن سٍتـ̡ تہٕ وونُن زِ ژے کیازِ چُھہ اسہِ دھوکہٕ دِتھ وَنُن زِ أسـ̡ چُھہ ژے نِش واریاہ دور۔ ییلہ تہٕ یێلہِ تہٕ أسـ̡ اسہِ سٍتـ̡ روزان چھِو؟ \n23.\\tتێلہِ چُھہ تۅہہ لعنت، تہٕ تێلہِ گژھہِ نہٕ کانہہ تہِ غلام بننہٕ نِش آزاد کرنہٕ، تہٕ لٔکرِ کھٔٹِتھ تہٕ میانہِ خدایہ سٕندِ گرٕ خٲطرٕ آب دِنہٕ وٲلۍ۔ {نہٕ...: ہیب۔ ژے نِش گژھ نہٕ ژٹنہٕ}\n24. تہٕ تِمو دِژ یشوع سُند جواب تہٕ وونُن، کیازِ یێلہِ چُھہ یێلہِ تہندٮ۪ن خادمَن وَننہٕ آمُت زِ خداوند چُھہ تُہٕندِس خداہس حُکُم دِژمُت زِ سُہ دِیہِ تۅہہِ سارِنٕے زمینہٕ دِنُک تہٕ سُہ دِیُن سارِنٕے زمینہٕ تہٕ سارِنٕے بسکیٖن دِنہٕ یِنہٕ سٍتـ̡ تہٕ یێلہِ أسـ̡ تۅہہِ سٍتـ̡ پننہِ زُو سٍتـ̡ کھوژان تہٕ یێمہِ سٍتـ̡ چُھہ یہِ کٲم کٔرمٕژ۔ \n25.\\tتہٕ وُچھِو، أسـ̡ چُھہ تُہٕندِس اتھس منز: یێلہِ چُھہ تۅہہِ سٍتـ̡ اسہِ سٍتـ̡ کرُن نیک تہٕ صحیح۔ \n26.\\tتہٕ یِتھٕ پٲٹھۍ کٔرٕن تِمن سٍتـ̡ تہٕ دِژُن تِم بنی اِسرٲیلِس نِش نِش نِش بچاوُن، یُس نہٕ تِم مٲرِتھ ۔ \n27. تہٕ یشوع بنوو تمہِ دۅہہ تِم لٔکرِ تہٕ آبہٕ کڈنہٕ خٲطرٕ، تہٕ خداوند سٕندِ قربان گاہٕ خٲطرٕ، یُس از تام تٔمِس ژٲرِتھ گژھِ۔ {بنووُن: حب۔ دِیُت، یا دِیُتُن دِنہٕ}","1.\\tوۅنۍ سپد ییلہ یروشلمکۍ بادشاہ اڈونیزیڈیکن بوز زِ یشوع ہن اوس آیی نِتھ تہٕ یہ اوس مکمل طور تباہ کورمُت۔ یِتھے پٲٹھۍ اوس تٔمۍ یریحو تہٕ تٔمۍ سٕندِس بادشاہس سٍتـ̡ کورمُت، یِتھے پٲٹھۍ اوس تٔمۍ آیی تہٕ تٔمۍ سٕندِس بادشاہس سٍتـ̡ کورمُت۔ تہٕ کِتھہ پٲٹھـ̡ اوس گِبیونٕکۍ بسکینو اسرٲیلِس سٍتـ̡ صلح کورمُت، تہٕ تِمن منز ٲسٕنـ̡ ۔ \n2. زِ تِم اوس واریاہ خوف، تکیازِ جبیون اوس اکھ بوٚڈ شہر، شٲہی شہرن منز اکھ تہٕ امہ مۅکھہ زِ یہ اوس آیی کھوتہ بوڈ تہٕ اَمہ کِس سارِنٕے انسان ٲسۍ طاقتور۔ {شٲہی ...: عبرانی۔ بادشٲہی ہٕندِس شہر}\n3. چنانچہ یروشلم کِس بادشاہ اڈونیزیڈیکن سوٗز ہیبرون کِس بادشاہ ہوہام، تہٕ جرموتھ کِس بادشاہ پیرامس تہٕ لاچیش کِس بادشاہ یافیہس تہٕ ایگلون کِس بادشاہ دیبیرس نِش وونُن، \n4. میہ نِش آو تہٕ کٔرِو میہ مدد، یُتھ أسۍ گِبیونس سٍتـ̡ مار دِیُن، تکیازِ یێمہِ سٍتـ̡ چُھ یشوع تہٕ بنی اسرٲیلِس سٍتـ̡ صلح کورمُت۔ \n5.\\tامہِ کِنۍ گٔیہِ امورین ہٕندِ پانژھ بادشاہ، یروشلمُک بادشاہ، حبرونُک بادشاہ، جرموتُک بادشاہ، لاخیش ہُند بادشاہ، ایگلونُک بادشاہ جمع تہٕ گٔیہِ تِمو تہٕ تِمن ہٕندِس سارِنٕے لشکرس تہٕ گِبیونَس برونہہ کُن ڈیرٕ ترٲوِتھ کٔرِکھ اتھ خلاف جنگ۔ \n6. تہٕ جِبعون سٕندیو نفرو سوٗز یشوع نِش گلگل کِس خٲمس منز، یہِ وونُن زِ پنہٕ نِس خادمَن نِش گژھ نہٕ پنُن اتھہٕ سوٚت ۔ جلدی آو اسہِ نِش تہٕ اسہِ بچٲوِو تہٕ اسہِ مدد کٔرِو، تکیازِ پہاڑن منز روزن وٲلِس سارِنٕے بادشاہ چھِ اسہِ خلاف جمع گٔمٕتۍ۔ \n7.\\tیِتھ ووت یشوع گلگل، سُہ تہٕ أمِس سٍتـ̡ سارِنٕے جنگٕکۍ لُکھ تہٕ سارِنٕے بہادر نفرن سٍتـ̡ کھسنہٕ۔ \n8. تہٕ خداوند ووٚن یشوعس زِ تِمن ہُند خوف گژھ نہٕ، کیازِ مے چُھ تِم تۅہہِ ہٕندِس اتھس مَنٛز دِژمٕتۍ۔ تِمو منزٕ گژھہِ نہٕ کانہہ تہِ نفر تہِ تۅہہِ برونہہ کُن کھڑا سپدِ۔ \n9.\\tیشوع آو تِمن نِش اچانک، {تہٕ} ووت سارِوٕے رٲژ گلگل پیٹھ۔ \n10.\\tتہٕ خداوند کٔر تِم اسرٲیلِس برونہہ کُن پریشان تہٕ گِبیونَس مَنٛز مارُن تِم بٔڈۍ قتل کٔرِتھ تہٕ یِمن ہُند پیچھا کٔرِتھ یُس بیت حورس تام گژھان چھُ، تہٕ دِژُن تِمن عزیقہ تہٕ مکیدہ کُن۔ \n11.\\tتہٕ سپُد یہِ سپُد، یێلہِ تِم اسرٲیلِس برونہہ کُن ژٔلِتھ، {تہٕ} بِتھورُن کُن گَژھنہٕ وِزِ خداوند دِژ تِمن پیٹھ آسمانہٕ پى۪ٹھٕ بٔڈۍ کٔنہِ کٔنہِ، تہٕ تِم گٔیہِ تِم مٔرۍ: {تِم} زیادٕ یِم ژلہٕ سٍتـ̡ مٔرۍ، یِمن بنی اسرٲیلِیو تلوار سٍتـ̡ مار۔ \n12. یشوع کٔر تمہِ دۅہہٕ یێلہِ خداوند امورِین اسرٲیلِس برونہہ کُن حوالہٕ دِیُت، تہٕ تٔمۍ وۆنُن اسرٲیلِس سٕندِس نظرس مَنٛز، آفتاب، گِبیونَس پٲٹھـ̡ کھڑا روزُن۔ تہٕ ژے، زونہٕ، اجالون کِس وادی مَنٛز۔ {کھڑا...: حب۔ ژھۄپہٕ کٔرِو}\n13.\\tتہٕ آفتاب روٗد رُکُن، تہٕ زوٗن روٗد یوٚت تام لُکھ پننین دُشمنن ہُند انتقام ہیوٚت۔ {کیا یہ} چھُنہٕ یَشر سٕنزِ کتابہِ مَنٛز لیکھنہٕ آمُت؟ تہٕ آفتاب اوس آسمانس مَنٛز رُکُن، تہٕ سارِوٕے دۅہس لوٚگُن نہٕ جلدی کٔرِتھ۔ {یشر: یا سیدِ سید؟}\n14. تہٕ امہِ برونہہ تہٕ امہِ پتہٕ اوس نہٕ یُتھ کانہہ دۅہہ، یُس خداوند أکِس انسانہٕ سٕنز آواز بوزو، کیازِ خداوند اوس اسرٲیلِس خٲطرٕ جنگ کوٚرمُت۔ \n15.\\tتہٕ یشوع آو واپس تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ گِلگل کِس خٲمس مَنٛز۔ \n16.\\tمگر یِم پانژھ بادشاہ ژٔلِتھ ژٔلِتھ گٔیہِ مکیدہ کِس أکِس غارس مَنٛز ژورِ۔ \n17.\\tتہٕ یشوع ہس وونُن زِ پانژھ بادشاہ چھِ مکیدہ کِس أکِس گۅپھِ منز ژوُرِتھ لبنہٕ آمٕتۍ۔ \n18.\\tتہٕ یشوع ووٚن، گۅپھِ ہٕندِس بٔڈِس پٲٹھۍ، تہٕ رژھراونہٕ خٲطرٕ تھووُن انسان۔ \n19.\\tتہٕ رٔٹِو نہٕ پَنٕنـ̡ دُشمن پَتہٕ تہٕ یِمن ہٕندِس پٔتِمِس پَتہٕ مارٕ۔ تِمن دِیُو نہٕ تِمن ہٕندِس شہرس مَنٛز اژُن، تِکیازِ خداوند چُھہ تُہٕندِس اتھس مَنٛز دِژمٕتـ̡ ۔ {مارُن...: حَب۔ لٔٹ ژٔٹِو}\n20. تہٕ سپُد یێلہِ یشوع تہٕ بنی اسرٲیلِیو تِمن سٍتـ̡ سٮ۪ٹھاہ بٔڈۍ قتلہٕ سٍتـ̡ مارُن ختم کٔرِتھ، یوتام تِم ختم گٔیہِ، باقٕے یِمو منزٕ باقٕے یِمو سٍتـ̡ بٔرِتھ شہرن مَنٛز دٲخل گٔیہِ۔ \n21.\\tتہٕ سٲری لُکھ گٔیہِ یشوع کِس خٲمس مَنٛز امن سان واپس، کٲنسہ تہِ ہٲو نہٕ بنی اسرائیل کِس خۅدٕ سٍتـ̡ ۔ \n22. یشوع ووٚن گۅپھِ ہُند بوش کھولُن تہٕ تِم پانژھ بادشاہ کٔرِن میانہِ نِش گۅپھِ منزٕ نیبر۔ \n23.\\tتہٕ تِمو کٔرِکھ یِتھٕ پٲٹھۍ، یِم پانژھ بادشاہ یُس یروشلمُک بادشاہ، حبرونُک بادشاہ، جرموتُک بادشاہ، لاچِشُک بادشاہ، تہٕ ایگلوُنُک بادشاہ۔ \n24. تہٕ سپُد یِمو یشوع نِش تِم بادشاہ نِش نیرِتھ، یشوع ہن بُلوو سارِنٕے اِسرٲیلِکۍ نفر، تہٕ وونُن یِمن سٍتـ̡ یِمن بادشاہن ہٕنزِ گردن پى۪ٹھ۔ تہٕ تِم وٲتِن نزدیک، تہٕ تھووُن تِمن ہٕنزِ گردن پیٹھ۔ \n25. تہٕ یشوع ہن ووٚن تِمن زِ خوفہٕ مہٕ گژھِ، نہ گژھِو خوفزدہ گژھُن، مضبوٗط تہٕ ہمت تھاوُن، یِتھٕ پٲٹھۍ کرِ خداوند تُہندین سارِنٕے دُشمنن سٍتـ̡ یِمن سٍتـ̡ یێلہِ تہٕ یێلہِ تہٕ یێلہِ سٍتـ̡ تُہۍ لڑان چھِو۔ \n26.\\tتہٕ یشوع ہن دِژ تِمن لٔٹِتھ تہٕ مارُن پانژن کُلٮ۪ن پیٹھ، تہٕ تِم رودۍ شامس تام کُلٮ۪ن پیٹھ لٹان۔ \n27.\\tتہٕ آفتاب لوسنہٕ وِزِ سپُد یہِ سپدُن، یشوع ہن دِژ حُکُم، تہٕ تِمو کُلٮ۪و پیٹھٕ بۄن تہٕ ترٛٲوِکھ تِم گۅپھِ مَنٛز یَتھ مَنٛز یِم ژوٗرِ تھاونہٕ آمٕتۍ ٲسۍ، تہٕ تھووُکھ غارہٕ کِس ٲسس مَنٛز بٔڈۍ کٔنہِ، یِم از تام باقٕے چھِ۔ \n28.\\tتہٕ تمہِ دۅہہ یشوع ہن مکیدہ رٔٹِتھ تلوار ہٕندِ دھار سٍتـ̡ لٔگِتھ تہٕ اَمہ کِس بادشاہن کٔرٕن تِم تہٕ سارِنٕے روحن یِم اتھ منز ٲسۍ۔ تٔمۍ دِژ نہٕ کانٛہہ تہِ باقٕے تہٕ تٔمۍ کٔر مکیدہ کِس بادشاہس سٍتـ̡ یِتھے پٲٹھۍ تٔمۍ یریحہ کِس بادشاہس سٍتـ̡ کوٚر۔ \n29.\\tیشوع گۆو مکیدہ تہٕ پانس سٍتـ̡ سارِنٕے اسرٲیلِس لِبنہٕ کُن تہٕ لِبنہٕ سٍتـ̡ لوٚڑُن ۔ \n30. تہٕ خداوند دِژ یہِ تہٕ اَمہِ سُند بادشاہ تہِ اِسرٲیلِس کِس اتھس مَنٛز۔ تہٕ دِژ أمِس تلوار ہٕندِس کنارٕ سٍتـ̡ تہٕ سارِنٕے روحن یِم اتھ منز ٲسۍ۔ تٔمۍ دِژ نہٕ اَتھ مَنٛز کٲنسہ تہِ روزُن۔ مگر یێرِیحو کِس بادشاہس سٍتـ̡ کوٚرُن یِتھٕ پٲٹھۍ۔ \n31.\\tتہٕ یشوع دراو لِبنہٕ تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ لاخیش کُن، تہٕ لوٚگُن اَتھ خٕلاف ڈیرٕ ترٲوِتھ تہٕ لوٚڑُن اَتھ خٕلاف۔ \n32. تہٕ خداوند دِژ لاخیش اسرٲیلِس اتھس مَنٛز، یٔمۍ دٔیمہِ دۅہہ یہ رٔٹِتھ تہٕ لِبناہس سٍتـ̡ یُس تٔمِس سٍتـ̡ لِبناہس سٍتـ̡ کورمُت اوس، تہٕ دِژُن تِمن سارِنٕے روحن سٍتـ̡ یُس تٔمۍ سٍتـ̡ لِبناہس سٍتـ̡ کورمُت اوس۔ \n33.\\tپتہٕ آو گیزرُک بادشاہ ہورام لاچیش سٕندِ مددٕ خٲطرٕ۔ تہٕ یشوع ہن دِژ أمِس تہٕ تٔمۍ سٕندِس لُکہٕ سٍتـ̡ مار، یوتام نہٕ تٔمِس کانہہ تہِ باقٕے رود۔ \n34.\\tتہٕ لاچِش پؠٹھٕ گۆو یشوع ایگلونس تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ ۔ تہٕ تِمو لوٚگ اَتھ خٕلاف ڈیرٕ ترٲوِتھ تہٕ لوٚگ اَتھ خٕلاف: \n35.\\tتہٕ تِمو رٔٹِتھ تِمو اَمہ دۅہہ تہٕ لٔگِتھ تلوار ہٕندِ کُنہِ سٍتـ̡ تہٕ سارِنٕے روحن یُس اَتھ مَنٛز ٲس، یُس تٔمۍ لَچِشس سٍتـ̡ کورمُت اوس۔ \n36.\\tتہٕ یشوع ووت ایگلون پیٹھٕ تہٕ سارِنٕے اسرٲیلِس سٍتـ̡ ہیبرون کُن۔ تہٕ تِمو لوٚگ اتھ خٕلاف: \n37.\\tتہٕ تِمو رٔٹِتھ تہٕ لٔگِتھ تلوار ہٕندِس کنارٕ سٍتـ̡ تہٕ اَمہ کِس بادشاہس تہٕ اَمہ کِس سارِنٕے شہرس تہٕ سارِنٕے روحن یِم اتھ منز ٲسۍ۔ تٔمۍ تروو نہٕ کانہہ تہِ باقی، یُس تٔمۍ ایگلونس سٍتـ̡ کورمُت اوس۔ مگر کورُن سُہ پوٗرٕ پٲٹھـ̡ تباہ تہٕ تِم سٲری روحہٕ یِم اتھ منز ٲسۍ۔ \n38.\\tتہٕ یشوع آو تہٕ سارِنٕے اِسرٲیلِس سٍتـ̡ دبیرس کُن واپس۔ تہٕ لوٚڈ اتھ خٕلاف: \n39.\\tتہٕ تٔمۍ رٔٹِتھ تہٕ اَمہِ کِس بادشاہس تہٕ تِمن ہٕندِس سارِنٕے شہر۔ تہٕ تِمو کٔرِن تِمن تلوار ہٕندِ دھار سٍتـ̡ تہٕ یِمن سارِنٕے روحن ہٕندِس سٍتـ̡ تباہ کٔرِتھ یِم اتھ منز ٲسۍ۔ تٔمۍ تروو نہٕ کانہہ تہِ باقٕے: یِتھہٕ کٔنۍ تٔمۍ حبرونس سٍتـ̡ تہٕ تٔمۍ سٕندِس بادشاہس سٍتـ̡ تہِ کورمُت۔ یِتھے پٲٹھۍ تٔمۍ لِبنس تہٕ تٔمۍ سٕندِس بادشاہس تہِ کورمُت۔ \n40. یشوع ہن دِژ بالہٕ تہٕ جنوبُک تہٕ وادی تہٕ چشمن ہٕندِس سارِنٕے ملکَس تہٕ تِہندِ سارِنٕے بادشاہن ہٕندِس مُلکَس مَنٛز، تٔمۍ تروو نہٕ کانٛہہ تہِ باقٕے باقی، مگر یِتھ کٔنۍ زن اسرٲیلِک خداوند خداہَن حُکُم دِیُت سٲرِسٕے سٲرِسٕے مُلکَس مُطٲبِق۔ \n41.\\tتہٕ یشوع ہن دِژ تِم کادیشبرنیاہس پیٹھٕ غزہ تام تہٕ گوشن کِس سٲرۍسٕے ملکس تام، حتیٰ کہ گِبیونس تام۔ \n42. تہٕ یِمو سارِنٕے بادشاہن تہٕ تِہٕنزِ زمینہٕ کٔر یشوع اَکہِ وِزِ نِنہٕ، تِکیازِ اِسرٲیلُک خدایہِ اوس اِسرٲیلِس خٲطرٕ لوٚڑمُت۔ \n43.\\tتہٕ یشوع آو واپس تہٕ سارِوٕے اسرٲیلِس سٍتـ̡ گِلگلَس کُن خٲمہٕ کُن۔","1.\\tتہٕ سپُد یێلہِ یێلہِ حزور کِس بادشاہ یابِن بوٗز، تٔمۍ سوٗزُن مدون کِس بادشاہ جوبابس تہٕ شِمرون کِس بادشاہس تہٕ اچشاف کِس بادشاہس نِش۔ \n2. تہٕ تمن بادشاہن خٲطرٕ یم پہاڑن ہندس شمالس منٛز، تہٕ چنیروتھ کس جنوبس منٛز مٲدانن منٛز، تہٕ وادی منٛز، تہٕ مغربس منٛز ڈور کس سرحدن منٛز، \n3.\\tمشرقس تہ مغربس منز کنعانی تہ اموری تہ حیتی تہ پیریزیت تہ پہاڑن منز یبوسی تہ ہرمونس تل ہیو تہ مزپہ کِس سرزمینس منز ہیوی کُن۔ \n4.\\tتہٕ تِم گٔیہِ نٮ۪بر، تِم تہٕ تِہٕندِس سارِنٕے لشکر سٍتـ̡ \n5. تہٕ ییلہ یِم سٲری بادشاہ اِکہٕ وٹہٕ سمکھے، تِم آیہِ میرم کِس آبس پیٹھ اِکہٕ وٹہٕ اِسرٲیلس خلاف لڑنہٕ خٲطرٕ۔ {ملاقات...: حب۔ ملاقاتہٕ سٍتـ̡ جمع کرنہٕ}\n6. تہٕ خداوند ووٚن یشوعس زِ یِمو سٍتـ̡ گژھ نہٕ تِمن ہٕندِس مۅکھہٕ خوفہٕ، یِمن ہٕندِس سٍتـ̡ یێلہِ بہٕ یِم سارِنٕے مارنہٕ آمٕتـ̡ اسرٲیلِس برونہہ کنہِ دِنہٕ آمٕتۍ، تہٕ تِہٕندِس گُرِ سٍتـ̡ دِیُن تہٕ تِہٕندِس رتھَن نار سٍتـ̡ زٲلِتھ دِنہٕ۔ \n7.\\tیِتھ آو یشوع تہٕ أمِس سٍتـ̡ سارِنٕے جنگٕکۍ لُکھ یِمن خٕلاف اَچانک میروم کِس آبس سٍتـ̡ ۔ تہٕ تِم گٔیہِ تِمن پیٹھ۔ \n8. تہٕ خداوند دِژ تِم اسرٲیلِس اتھس مَنٛز، یٔمۍ تِمن مارٕ دِیُت، تہٕ تِمن ہُند پیچھا کٔرِتھ بٔڈِس زیدونس تام، تہٕ مِسریفوتھمایمس تام، تہٕ مشرقس کُن وادی مِزپہٕ کِس وادی تام۔ تہٕ تِمو دِژ تِمن مارٕ، یوتام نہٕ تِمو تِمن ہُند کانہہ تہِ باقی۔ {عٔظیٖم زِدون: یا، زِدونراباہ} {مِسریفوتھمیم: یا، نوٗنہٕ گُڈ: حب۔ آبُک دَزُن}\n9. تہٕ یشوع ہن کٔر تِمن سٍتـ̡ یُتھ خداوند أمِس حُکُم دِژمُت، تٔمۍ کٔر تِہٕندِس گُرِ تہٕ تِہٕندِس رتھَس نار سٍتـ̡ زٲلِتھ۔ \n10.\\tتہٕ یشوع آو تمہِ وِزِ واپس تہٕ ہزور رٔٹِتھ تہٕ دِتُن امہِ کِس بادشاہس تلوار سٍتـ̡ مارُن، تکیازِ حزور اوس امہِ برونہہ یِمن سارِنٕے سلطنتن ہُند سربراہ۔ \n11.\\tتہٕ تِمو دِژ تِمن سارِنٕے روحن یُس تلوار ہٕندِ کُنہِ کُنہِ سٍتـ̡ دِنہٕ آمُت اوس، تہٕ تِمو دِژ حزور نارٕ سٍتـ̡ زٲلِتھ۔ {کُنہِ...: حَب۔ کانہہ تہِ شاہ}\n12. تہٕ یِمن بادشاہن ہٕندِس سارِنٕے شہرس تہٕ تِمن ہٕندِس سارِنٕے بادشاہو کٔر یشوع ہٕندِس سٍتـ̡ تلوار سٍتـ̡ لٔگِتھ تہٕ یِمن ہُند حُکُم موسیٰ سُند حُکُم دِنہٕ آمُت۔ \n13.\\tمگر یِمن شہرن ہٕندِس طاقتس منز کھڑا اوس، اسرائیلن زٲلۍ نہٕ تمن منز کانہہ تہِ، صرف حزورس علاوٕ۔ {یہ} زٲلِتھ یشوع زٲل۔ {تِہندِس انبارس منز...: عبرانی۔ تِہندِس ڈھیرس پیٹھ}\n14.\\tتہٕ یِمن شہرن ہٕندِ سارِنٕے لوُٹ، تہٕ چاروایہِ، بنی اسرٲیلِو پانس شِکار۔ مگر پریتھ أکِس انسانس لٔج تلوار سٍتـ̡ ، یوتام تِمو تِم تباہ کٔرۍ، تِمو ترووُن نہٕ کانہہ تہِ شاہ۔ \n15. یِتھٕ کٔنۍ خداوند موسیٰ سٕندِس بندس حُکُم دِیُت، تِتھے کٔنۍ دِژ موسىٰ یشوع سُند حُکُم۔ یُس خداوند موسیٰ سُند حُکُم دِیُت تِمن سارِنٕے سارِنٕے سٍتـ̡ چُھہ نہٕ کُنہِ تہِ کُنہِ تہِ حُکُم کٔرِتھ۔ {کھوورُن...: ہیب۔ کُنہِ تہِ ہٹٲوُن نہٕ}\n16. یشوع ہن نِش سٲرۍسٕے زمین، بالہٕ تہٕ سارِوٕے جنوبُک ملک، تہٕ گوشنٕچ سارِنٕے زمین، وادی، میدان، تہٕ اسرٲیلُک پہاڑ تہٕ امی ہٕنز وادی حٲصِل۔ \n17.\\tحتیٰ کہ پہاڑ ہالک پیٹھ، یُس سیر تام واتان چُھ، حتیٰ کہ لبنان چہ وادی منز بعلگاد تام تہٕ تِہندِ سارِنٕے بادشاہن رٔٹِتھ تہٕ مارُن تِمن ہٕندِس سارِنٕے بادشاہس تہٕ مارُن تِمن ہٕندِس سارِنٕے بادشاہس سٍتـ̡ تہٕ مارُن تِمن ہٕندِس سارِنٕے بادشاہس سٍتـ̡ ۔ {پہاڑ ...: یا، ہموار پہاڑ}\n18. یشوع ہن کٔر واریاہس کالس تِمن سارِنٕے بادشاہن سٍتـ̡ جنگ۔ \n19.\\tکانہہ تہِ شہر اوس نہٕ یُس بنی اسرائیل سٍتـ̡ صلح کٔرِتھ، سوائے حیوی یُس جبیعون کین بسکینن سٍتـ̡ جنگس مَنٛز رٔٹۍ۔ \n20.\\tیِمن ہُند دِل سخٕت کرُن، یُتھ زن تِم اسرٲیلِس خلاف جنگس منز یِن، یُتھ سُہ کرِ تِمن پوٗرٕ پٲٹھـ̡ تباہ کرنہٕ، یُتھ زن خداوند موسیٰ سُند حُکُم دِیُتمُت چھُ۔ \n21. تہٕ تمہِ وِزِ آو یشوع تہٕ کٔرٕن عناقیم پہاڑو پیٹھ، حبرون پیٹھ، دیبیر، عناب پیٹھ، تہٕ یہوداہ کین سارنٕے پہاڑو پیٹھٕ تہٕ اسرٲیلٕکۍ سارِنٕے پہاڑو نِش ژٹِتھ یشوع یِم تِمن ہٕندیو شہرو سٍتـ̡ پوٗرٕ پٲٹھۍ۔ \n22.\\tبنی اسرائیلی ہٕندِس سرزمینس مَنٛز اوس نہٕ کانہہ تہِ عناقیم: صرف غزہ منز، گاتھس مَنٛز تہٕ اشدودس مَنٛز روٗدمُت۔ \n23. یِتھٕ کٔنۍ یشوع ہن سارِوٕے زمینہٕ رٔٹِتھ یُس خداوند موسیٰ سٕندِ وَننہٕ آمُت اوس۔ تہٕ یشوع ہن دِژ یہِ اِسرٲیلِس تہندِ قبیلہٕ ہٕندِ طرفہٕ تقسیم کرنہٕ مُطٲبِق وَرثہٕ خٲطرٕ۔ تہٕ یہِ زمین گٔیہِ جنگہٕ نِش آرام۔","1.\\tوۅنۍ چھہِ یِم زمینہِ ہٕندِس بادشاہس منز، یُس بنی اسرٲیلِیو ژٔٹِتھ تہٕ یِمن ہٕندِس زمینس پیٹھ یُس آفتاب کھسنہٕ کِس طرفہٕ اردن کِس دوٚیمہِ طرفہٕ آفتاب کھسنہٕ کُن، دریائے ارنون پیٹھٕ ہرمون کِس پہاڑس تام، تہٕ مشرقس کُن سارِنٕے میدانس پیٹھ قبضہ کٔرِتھ: \n2.\\tامورین ہُند بادشاہ سِحون، یُس ہیشبونس منز روزان اوس، {تہٕ} اوس آروئر پیٹھہٕ حُکوٗمت کٔرِتھ، یُس دریائے ارنون کِس بٹھس پیٹھ، تہٕ دریاو کِس وسطس پیٹھ، تہٕ نصف جلعاد پیٹھ، یوتام زِ دریائے جابوک تام، {یُس} عمون کین بچن ہُند سرحد چُھ۔ \n3. تہٕ میدانی پیٹھہٕ مشرقس منز چِنروتھ کِس سمندرس تام، تہٕ میدانی سمندرس تام، {حتیٰ کہ} مشرقس کُن نوٗنہٕ سمندر، بیت جیشیموتھ کُن وتھ۔ تہٕ جنوبہٕ پیٹھ، اشدوتھپِسگاہَس تل: {جنوب: یا، تیمان} {اشدوتھپِسگاہ: یا، پِسگاہُک چشمہٕ، یا بالہٕ}\n4. تہٕ بشانُک بادشاہ اوگ سُند ساحل، یُس دیون ہٕندِس باقیاتس منز، یُس اشتروت تہٕ ادری یس مَنٛز روزان اوس، \n5.\\tتہٕ کٔرٕن کوہ ہرمون کِس علاقس مَنٛز، تہٕ سالکاہَس مَنٛز، تہٕ سارنٕے باشانَس مَنٛز، گیشورِیَن تہٕ ماخاتھین ہٕندِس سرحدس تام، تہٕ نصف گلعاد، یُس ہیشبون کِس بادشاہ سِحون سٕندِس سرحدس تام۔ \n6.\\tخداوند سٕندِس خادمَس تہٕ بنی اسرٲیلِس دِژ تِمن ہُند مُقابلہٕ۔ تہٕ خداوند سٕندِس خادمَس موسیٰ دِژ یہِ روبینِس تہٕ گادِس تہٕ منسی ہٕندِس نصف قبیلس مَنٛز دِنہٕ۔ \n7.\\tتہٕ یِم چھہِ تتھ ملکٕکۍ بادشاہ یُس یشوع تہٕ بنی اسرائیل یَتھ طرفہٕ یُس لبنان کِس وادی مَنٛز بعلگاد پیٹھٕ ہالک پہاڑس تام یُس سیر تام واتان چھُ۔ یُس یشوع ہن اسرائیل کین قبیلن دِژ تہندِ تقسیمہٕ مطٲبق اکھ قبضہ۔ \n8.\\tپہاڑن منز، وادین منز، میدانن منز، چشمن منز، بیابانن منز، تہٕ جنوبی ملکس منز۔ حتی، اموری تہٕ کنعانی، پیرزی، حوی تہٕ یبوسی: \n9.\\tیریحُک بادشاہ، اکھ؛ آیی ہُند بادشاہ، یُس {بیتھلس سٍتـ̡ چُھ}، اکھ؛ \n10. یروشلمُک بادشاہ، اکھ؛ حبرونُک بادشاہ، اکھ؛ \n11.\\tجرموتھُک بادشاہ، اکھ؛ لاچِشُک بادشاہ، اکھ؛ \n12.\\tایگلونُک بادشاہ، اکھ؛ گیزرُک بادشاہ، اکھ؛ \n13.\\tدبیرُک بادشاہ، اکھ؛ گیدرُک بادشاہ، اکھ؛ \n14. ہورمہُک بادشاہ، اکھ؛ ارادُک بادشاہ، اکھ؛ \n15.\\tلبناہُک بادشاہ، اکھ؛ عدلامُک بادشاہ، اکھ؛ \n16.\\tمکیدہ ہُند بادشاہ، اکھ؛ بیتھلُک بادشاہ، اکھ؛ \n17. تپواہُک بادشاہ، اکھ؛ ہیفرُک بادشاہ، اکھ؛ \n18.\\tافیکُک بادشاہ، اکھ؛ لشارونُک بادشاہ، اکھ؛ {لشارون: یا، شیرون}\n19. مدونُک بادشاہ، اکھ؛ حزورُک بادشاہ، اکھ؛ \n20.\\tشیمرونُک بادشاہ، اکھ؛ اچشفُک بادشاہ، اکھ؛ \n21. تانچُک بادشاہ، اکھ؛ میگیڈوُک بادشاہ، اکھ؛ \n22. کیدیش ہُند بادشاہ، اکھ؛ کارملُک جوکنیم بادشاہ، اکھ؛ \n23.\\tڈور کِس بٹھِس مَنٛز ڈورُک بادشاہ، اکھ؛ گِلگل قومن ہُند بادشاہ، اکھ؛ \n24.\\tترزاہُک بادشاہ، اکھ: سارِنٕے بادشاہ ترٕہ تہٕ اکھ۔","1. وُنہِ اوس یشوع بُزرگ {تہٕ} ؤری وٲنـ̡ مُتٲثِر گومُت۔ تہٕ خداوند چُھہ أمِس وۆنُن، تہٕ وُنہِ تہِ چُھہ واریاہ زمین باقی۔ {to...: Heb. اتھ پیٹھ قبضہ کرُن}\n2. یہِ چھُ سُہ زمین یُس وُنہِ تہِ باقٕے چھُ: فلسطینن ہٕندِ سارِنٕے سرحد، تہٕ سارِنٕے گیشوری، \n3.\\tسِہوٗر پیٹھ، یُس مصرس برونہہ کُن چُھ، شمالس کُن ایکرون کِس سرحدس تام، {یُس} چھُ کنعانی سٍتـ̡ گنزراونہٕ آمُت: فلسطینین ہٕندِ پانژھ مٲلک۔ غزتھی، تہٕ اشدوتھی، اشکالونی، گیتِس تہٕ ایکرونائٹس۔ تہٕ اویِٹس: \n4. جنوبہٕ پیٹھٕ کنعانین ہٕنز سارِنٕے زمین، تہٕ میرہ یُس سِدونین سٍتـ̡ {چُھ} سٍتـ̡ افیقس تام، امورین ہٕندِس سرحدس تام: {Mearah: یا غار}\n5. تہٕ گبلیٹس تہٕ سارنٕے لبنانٕچ زمین، آفتاب کھسنہٕ کُن، بعلگاد پیٹھٕ ہیرمون پہاڑس تل حمتس تام دٲخل گژھنس تام۔ \n6.\\tلبنان پیٹھٕ مِسریفوتھمیم تام پہاڑی علاقٕکۍ سارِنٕے بسکین، {تہٕ} سارِنٕے سِدونِیَن ہٕندِس سٍتـ̡ کٔرِتھ کٔرِو بہٕ یِمن بنی اسرٲیلِس برونہہ کُن ژٔلِتھ کٔرِتھ، یِتھٕ کٔنۍ مے چُھہ ژے حُکُم دِژمُت۔ \n7. تێمہِ کِنۍ کٔرِو یہِ زمینہٕ نَو قبیلن تہٕ مَنسی ہٕندِس نصف قبیلس وَرثہٕ خٲطرٕ تقسیم۔ \n8. یٔمِس سٍتـ̡ روبینن تہٕ گادیتن پنُن وراثت حٲصل چُھ، یُس موسىٰ ہن تِمن اردن اپارِ مشرقس کُن دِژمُت، یُس موسیٰ سٕندِ خدایہِ سٕندِ خادم دِژمُت اوس۔ \n9.\\tاَرَوَر پؠٹھٕ یُس {چُھ} دٔریاو کِس بٔٹھِس پیٹھ، تہٕ سُہ شہر یُس دٔریاوَس مَنٛز {چُھ}، تہٕ مدیبا کِس سٲرۍسٕے مٲدانَس پؠٹھ دِبون تام۔ \n10.\\tتہٕ امورین ہٕندِس بادشاہ سِحون سٕندِس سارِنٕے شہر، یُس ہیشبونس مَنٛز حکومت کران اوس، عمون سٕندِس بچن ہٕندِس سرحدس تام۔ \n11. تہٕ گلعاد، تہٕ گیشوری تہٕ ماخاتھین ہٕنز سرحد، تہٕ سارِنٕے ہیرمون پہاڑ تہٕ سارِنٕے باشان سٍتـ̡ سلکہٕ تام۔ \n12.\\tاوگ سٕنز سارِنٕے بادشٲہی یُس اشتاروتس تہٕ ادری یس مَنٛز حکومت کٔر، یُس دیوَن ہٕندِس باقیاتس مَنٛز رودمُت، یِمو خٲطرٕ موسیٰ ہن مارٕ تہٕ کٔرِن تِم کٔڑِتھ۔ \n13.\\tبہر حال کٔر نہ بنی اسرائیل گیشوری تہٕ نہ ماخاتھی، بلکہ چھہِ گیشوری تہٕ ماخاتھی از تام اسرٲیلِس منز روزان۔ \n14. صرف لیوی قبیلس دِژ نہٕ تٔمۍ کانہہ وٲرث۔ اسرٲیلِکِس خدایہِ سٕندِ دٔسۍ دِنہٕ آمٕژ قربانی چھِ تِہُند وَرث، یِتھ کٔنۍ تٔمۍ تِمن وَنُن۔ \n15.\\tتہٕ موسىٰ دِژ روبن سٕندِس اولادس قبیلس تہندِس عیالس مطٲبق وراثت۔ \n16.\\tتہٕ تِہُند ساحل اوس آروئر پیٹھ، یعنی دریائے ارنون کِس بٹھس پیٹھ، تہٕ سُہ شہر یُس دریاوس منز {چُھ} تہٕ مدیبہ کِس سٲرۍسٕے میدانس منز۔ \n17.\\tہیشبون، تہٕ تٔمۍ سٕندِس سٲری شہر یِم میدانس مَنٛز چھِ۔ دیبون، تہٕ باموتھبال، تہٕ بیت بالمئون، {باموتھبال...: یا، بعلٕکۍ تھدِ مقامہٕ، تہٕ بعلمیون ہُند گرٕ}\n18.\\tتہٕ جاہزاہ، تہٕ کیدموت، تہٕ میفاتھ، \n19.\\tتہٕ کِرجاتھیم تہٕ سِبمہ تہٕ زرتھ شہر وادی کِس پہاڑس منز، \n20.\\tتہٕ بیتھپیور، تہٕ اشدوتھپِسگاہ، تہٕ بیت جیشیموتھ، {اشدوتھپِسگاہ: یا، پِسگاہُک چشمہٕ، یا، بالہٕ}\n21.\\tتہٕ میدانٕکۍ سٲری شہر، تہٕ امورین ہٕندِس بادشاہ سِحون سٕنزِ سارِنٕے بادشٲہی یُس ہیشبونس مَنٛز راج اوس کٔرِتھ، یِمن موسىٰ ہن مدیان، ایوی تہٕ رکیم، تہٕ زور، تہٕ حُر تہٕ رِبا ہٕندِس شہزادس سٍتـ̡ مارٕ دِژ، یِم ملکس منز روزن وٲلِس سِہونٕکۍ ڈیوک ٲسۍ۔ \n22.\\tبیور سُند نیچو بعلمن تہِ مارُن یُس تِمو دٔسۍ مارنہٕ آو۔ {کُچھر: یا، خدایہِ}\n23.\\tتہٕ روبن سٕندٮ۪ن شُرین ہُند سرحد اوس اردن، تہٕ اَمہ کِس سرحدس سٍتـ̡ ۔ یہِ اوس روبن سٕندٮ۪ن شُرین ہٕندِس خاندانن، شہرن تہٕ گامن ہٕندِس وراثتس منز۔ \n24. تہٕ موسىٰ دِژ گاد کِس قبیلس {وراثت}، {حتیٰ کہ} جاد کِس اولادس تہندِ عیال مطٲبق۔ \n25.\\tتہٕ تِہُند بٔٹھِس اوس یَزر، تہٕ جلعادٕکۍ سارِنٕے شہر تہٕ عمون کِس اولادَن ہُند نصف سرزمین، یُس ربع برونہہ کُن اوس۔ \n26.\\tتہٕ ہیشبون پیٹھٕ رامتھمیزپہ تہٕ بیٹونیم تام۔ تہٕ مہانیم پیٹھٕ دیبیر کِس سرحدس تام۔ \n27.\\tوادی مَنٛز، بیتھارام، تہٕ بیتھنیمرا، تہٕ سوکوتھ، تہٕ زافون، باقی سلطنت سِہون سٕندِس بادشاہس منز، اردن، تہٕ {تٔمِس} سرحد، یێمہِ طرفہٕ اردن کِس سمندرس کِس بٹھس تام۔ \n28. یہِ چُھ گاد سٕندٮ۪ن شُرین ہٕندِس خاندانن، شہرن تہٕ تِہندین گامن ہٕندِ پتہٕ وراثت۔ \n29.\\tتہٕ موسىٰ دِیُت مَنسِہ کِس نصف قبیلس {وراثت} تہٕ {یہ} اوس منسی ہٕندِس اولادَس ہٕندِس نصف قبیلس ہُند قبضہٕ۔ \n30.\\tتہٕ تِہُند بٔٹھِہ اوس مہنایم، سارِنٕے باشان، اوگ بادشاہ سٕنزِ بادشٲہی تہٕ یایرٕکۍ سارِنٕے قصبہٕ، یِم بشنَس مَنٛز تریہ شہر: \n31.\\tنصف گلعاد، تہٕ اشتروت تہٕ ادری یِم بشانس مَنٛز اوگ سٕندِ بادشاہتٕکۍ شہر ٲسۍ، مُنسیٰ سٕندِس نیچوِس مَکیر سٕندِس شُرین سٍتـ̡ تہٕ یێمہِ سٍتـ̡ تِمن ہٕندِس عیالس سٍتـ̡ مَچِر سٕندِس أکِس نصفس سٍتـ̡ مُتعلق۔ \n32. یِم چھِ تِم مُلک} یِم موسیٰ ین موآب کِس مٲدانس مَنٛز یریحو کِس طرفہٕ مشرقس کُن وراثت خٲطرٕ بٲگرٲومٕتۍ۔ \n33.\\tمگر لیوی قبیلس دیت نہ کانہہ وراثت: اسرٲیلُک خداوند اوس تِہُند وراثت، یِتھہٕ کٔنۍ تٔمۍ تِمن ووٚنمُت۔","1. تہٕ یِم مُلک} یِم بنی اسرٲیلِس کنعان کِس سرزمینس مَنٛز وراثتس منز میلہِ، یُس الیعزر پادٕر، تہٕ نون سُند نیچو یشوع تہٕ بنی اسرٲیلِن ہٕندِس قبیلن ہٕندِس مٲلِس ہٕندِس سرس مَنٛز وٲرثہٕ دِنہٕ خٲطرٕ بٲگرٲو۔ \n2.\\tتِہُند وَراثت، یُس خداوند موسىٰ سٕندِ اتھہٕ سٍتـ̡ حُکُم دِیُتمُت اوس، نو قبیلن خٲطرٕ، تہٕ نصف قبیلہٕ خٲطرٕ۔ \n3. تکیازِ موسىٰ اوس اردن کِس دوٚیمہِ طرفہٕ دۄن قبیلن تہٕ نصف قبیلن ہٕنز وراثت دِژمٕژ، مگر لاوِین دِژ نہٕ تِمن مَنٛز کانہہ تہِ وٲرث۔ \n4.\\tیوسف سٕندِس اولادس مَنٛز ٲسۍ زٕ قبیلہٕ، منسیٰ تہٕ افرائیم۔ تێمہِ کِنۍ دِژ تِمو لاوِین زمینس مَنٛز کانہہ حصہٕ، شہرن علاوٕ یِمن ہٕندِس مضافاتس سٍتـ̡ تہٕ تِمن ہٕندِس مالہٕ خٲطرٕ تہٕ تِمن ہٕندِس مالہٕ خٲطرٕ۔ \n5. یِتھٕ کٔنۍ خداوند موسیٰ سُند حُکُم دِیُت، تِتھٕ کٔنۍ کٔر بنی اسرٲیلِو تہٕ تِمو کٔر زمینہٕ تقسیم۔ \n6. پَتہٕ آیہِ یہوداہ سٕندِ بچہٕ گلگلس مَنٛز یشوع نِش تہٕ یِفُنہٕ کِنزِی سٕندِس نیچوِس کالبَن ووٚن تٔمِس زِ ژے چھے پتاہ یُس خداوند موسیٰ سٕندِس مُتعلِق میانہِ تہٕ تۅہہِ مُتعلِق ووٚنمُت۔ \n7.\\tژتٲجی وُہُر اوسُس میہ ییلہ خداوند سٕندِ خادم موسیٰ سٕندِ خادمَس سٍتـ̡ میہ کدیشبرنیاہس پیٹھ زمینہِ ہُند جاسوسی کرنہٕ خٲطرٕ سوزمُت۔ تہٕ بہٕ دِژ أمِس دُبارٕ کلام یُس میٲنِس دِلس مَنٛز اوس۔ \n8. بہر حال میانیو بٲے یُس میہ سٍتـ̡ ہیوٚت، لُکن ہُند دِل پۯاوُن، مگر بہٕ کٔر پورٕ پٲٹھـ̡ خداوند پننِس خدایہِ سٕنز پٲرو۔ \n9. تہٕ موسىٰ چُھ اَمہِ دۅہہٕ قَسم کٔرِتھ ونان زِ یێلہِ تُہٕندِس قدمَس پٔکِتھ آسہِ تُہٕندِس وٲرِثس تہٕ تُہٕندِس شُرِس ہمیشہٕ خٲطرٕ، تِکیازِ ژے چُھہ پوٗرٕ پٲٹھـ̡ خداوند میانہِ خدایہِ سٕنز پیروی کٔرمٕژ۔ \n10. تہٕ وُن، وُچھِو، خداوند چُھس مے زِندٕ تھوومُت، یِتھ کٔنۍ تٔمۍ ووٚنمُت، یێلہِ زن خداوند موسیٰ سٕندِس سٍتـ̡ یہِ کلام وونُن، یێلہِ {اِسرٲیلٕکۍ بُرِہ} بیابانن مَنٛز پھیران ٲسۍ: تہٕ وُن، وُن، بہٕ چُھس از دۅہہٕ ژۄرہٕ تہٕ پانژٕ وُہُر وٲنسہِ۔ {پھیُرُن: عبرانی۔ پَکُن}\n11.\\tبہ چھُس از دۅہہ تیوت مضبوط یُتھ زن موسیٰ ین میہ سوزمُت اوس، یتھہ پاٹھۍ میون طاقت {اوس} تیلہِ، تیلہِ تہِ چھہ میٲنۍ طاقت، جنگہ خاطرہ تہِ نیبر نیرُن تہ اژُن۔ \n12. تێلہِ دِیُو مے یہِ پہاڑ، یێمہِ دۅہہٕ خداوند اوس کتھ کٔرمٕژ۔ تِکیازِ ژے بوز تمہِ دۅہہٕ کِتھہ پٲٹھـ̡ اَناکیٖم {ٲس} تتہِ، تہٕ {یہ} شہر {أس} بٔڈ {تہٕ} تارٕ لٔگِتھ: یێلہِ تہٕ خداوند آسہِ میہ سٍتـ̡ ، تیلہِ ہێکہٕ بہٕ ہێکہٕ تِم کٔڑِتھ کٔڈِتھ، یِتھہٕ کٔنۍ خداوند ووٚنمُت چُھ۔ \n13. تہٕ یشوع ہن دِژ أمِس برکت تہٕ دِتُن جیفونہ ہیبرون سُند نیچو کالبس وراثتس خٲطرٕ۔ \n14. اَمہِ کِنۍ بنیوو ہیبرون از تام جیپھونہ کِنزی سٕندِس نیچوِس کالب سٕنز وٲرث، تکیازِ سُہ اوس پوٗرٕ پٲٹھـ̡ اسرٲیلِکِس خدایہِ سٕنز پٲروٲنی کران۔ \n15.\\tتہٕ حبرونُک ناو اوس {اوس} کِرجاتاربا۔ {یُس اربا اوس} اناکیمن مَنٛز اکھ بٔڈ شخٕص۔ تہٕ زمینس اوس جنگہٕ نِش آرام دِوان۔","1. {یہ} اوس تمہ وقتہٕ یہوداہ کین اولادن ہٕندِس قبیلس ہٕندِس عیالس سٍتـ̡ یێلہِ سٍتـ̡ یہوداہ کِس بُلِس سٍتـ̡ \n2. تہٕ تِہُند جنوبی سرحد اوس نوٗنہٕ سمندر کِس بٹھہٕ پیٹھ، تتھ خلیج پیٹھٕ یُس جنوبس کُن نظر چُھ تھاوان: {Bay: Heb. Tongue}\n3.\\tتہٕ یہ دراو جنوبس کُن مالہکربم کُن، تہٕ ووت زِنس کُن تہٕ ووت جنوبس کُن کادیشبرنیاہس کُن، تہٕ ووت حِزرون کُن تہٕ ووت ادرس کُن، تہٕ ووت کرکاہس تام اکھ کمپس: {Maalehacrebbim: یا، اکربیمس تام گژھُن}\n4.\\t{اتہِ پیٹھہ گۆو یہ ازمون کُن تہ دریائے مصر کُن نیران۔ تہٕ اَمہ بٹھہِ منزٕ نیرن وول اوس سمندرس کُن: یۅہے آسہِ تُہند جنوبی بٹھ۔ \n5. تہٕ مشرقی سرحد {اوس} نوٗنہٕ سمندر، {حتیٰ کہ} اردن کس اندس تام۔ تہٕ شمٲلی حصس مَنٛز {تِہُند} سرحد {اوس} اردن کِس اندس پیٹھ سمندر کِس خلیج پیٹھ: \n6.\\tتہٕ سرحد ووت بیت وگلا تام تہٕ بیتھارابہ کِس شمالس کُن پٔکۍ۔ تہٕ سرحد ووت روبن سٕندِس نیچو بوہان سٕندِس کنس تام: \n7.\\tتہ سرحد ووت وادی آکور پیٹھہ دیبیر کُن تہ یتھہ پاٹھۍ شمالس کُن گلگلس کُن وچھان، یعنی ادومیم کُن گژھنہ برونہہ، یُس دریاو کس جنوبس کُن چھہِ: تہ سرحد ٲس انشیمش کِس آبس کُن نیران، تہ اتہِ نیبر نیرن وول اوس اینروگلس پیٹھ۔ \n8.\\tتہٕ سرحد ووت ہینوم سٕندِس نیچو سٕنزِ وادی کِس جنوبس کُن۔ یۅہے {چُھ} یروشلم: تہٕ سرحد ووت پہاڑ کِس تینتٲلس تام یُس مغرب کُن ہینوم وادی برونہہ کُن {lieth} چُھ، یُس {چُھ} شمالس کُن دیوہن ہٕنزِ وادی کِس اندس پیٹھ: \n9.\\tتہٕ سرحد آو بالہٕ پیٹھٕ نیفتواہ کِس آبہٕ کِس چشمس تام کھسنہٕ، تہٕ گٔیہٕ کوہ ایفرون کِس شہرن کُن۔ تہٕ سرحد آو بعلہ کُن کھیننہٕ، یُس {چُھ} کِرجاتجیرِم: \n10.\\tتہٕ سرحد آو بعلہ پیٹھہ مغرب کُن سیر کِس پہاڑس تام، تہٕ گٔیہ کوہ یریم کِس اندس کُن، یُس شمالس کُن چُھس چیسلون چُھ، تہٕ ووت بیت شیمش کُن تہٕ گٔیہ تیمنہ کُن۔ \n11.\\tتہٕ سرحد دراو ایکرون کِس طرفہٕ شمالس کُن: تہٕ سرحد آو شکرون کُن کھسنہٕ، تہٕ بعلہ کِس پہاڑس کُن گٔیہ، تہٕ گٔیہٕ جبنیل کُن۔ تہٕ سرحد نیبر نیرن وٲلس سمندرس کُن۔ \n12.\\tتہٕ مغربی سرحد اوس عظیم سمندرس سٍتـ̡ تہٕ بٔٹھِس سٍتـ̡۔ یہِ چُھہ یہوداہ کین بچن ہُند بٔٹھـ̡ یُس تہندِس عیالس مُطٲبق چُھ۔ \n13. تہٕ یپھونہ سٕندِس نیچوِس کالبس دِژ یہوداہ کِس اولادس مَنٛز اکھ حصہٕ، یُس خداوند سٕندِ حُکمہٕ مُطٲبق یشوع سُند حُکُم چُھ، یُس {شہر} چُھہ حبرون۔ {شہر...: یا، کِرجاتھربا}\n14. تہٕ کالبن کٔر اَتہِ نِش انک سٕندِ تریہ نیچوۍ، شیشایی تہٕ اہیمان، تہٕ انک سٕندِ شُرِ تلمایی ہٕندِس نیچِوۍ۔ \n15.\\tتہٕ سُہ ووت تتہِ دیبیر کین بسکینن نِش: تہٕ دیبیر سُند ناو اوس {اوس} کرجاتسیفر۔ \n16.\\tتہٕ کالبن ووٚن، یُس کِرجاتھسیفرس ماران چُھ، تہٕ نِنہٕ چُھ، بہٕ دِیہ أمِس پنٕنۍ کورِ اچسہٕ زنانہٕ خٲطرٕ۔ \n17.\\tتہٕ کلب سٕندِس بٲے کیناز سٕندِس نیچوِس عثنیلَن رٔٹِتھ تہٕ دِژ أمِس پننہِ کورِ اَخسہٕ زنانہٕ خٲطرٕ۔ \n18.\\tتہٕ سپُد أمِس مٲلِس نِش کھیت پرژھنہٕ خٲطرٕ، تہٕ تٔمۍ کٔر پننِس مٲلِس کھہٕ پرژھنہٕ خٲطرٕ۔ تہٕ کالبن ووٚن أمِس کیا چُھہ؟ \n19.\\tیمۍ دیت جواب، مے دِژ برکت۔ کیازِ ژے دِژ میہ اکھ جنوبٕچ زمین۔ مے دِژ آبٕکۍ چشمہٕ تہِ۔ تہٕ دِژ أمِس پیٹھمہِ چشمہٕ تہٕ بٔنِم چشمہٕ۔ \n20. یہِ چُھ یہوداہ کین اولادن ہٕندِس قبیلہٕ سٕندِ خاندانہٕ مُطٲبق وراثت۔ \n21.\\tتہٕ یہوداہ کین بچن ہٕندِس قبیلہٕ کِس سارِوٕے کھۄتہٕ بٔڈ شہر ٲسۍ کبزیل، تہٕ ایدر تہٕ یگور۔ \n22. تہٕ کِنہ تہٕ دیمونہ تہٕ عدہ، \n23.\\tتہٕ کیدیش تہٕ حزور تہٕ اِتھنان، \n24. زیف، تہٕ ٹیلم، تہٕ بیلوتھ، \n25.\\tحزور، حدتہ تہٕ کریوتھ، {تہ} حزرون، یُس {چھ} حزور، \n26.\\tعمام تہٕ شیما تہٕ مولادہ، \n27.\\tتہٕ ہزرگدہ تہٕ ہیشمون تہٕ بیت پالت، \n28. تہٕ ہزارشوال، تہٕ بیرشیبا تہٕ بزجوتھجاہ، \n29.\\tبعلہ تہٕ عیم تہٕ عظم، \n30. تہٕ ایلٹولاد، تہٕ چیسل، تہٕ ہورمہ، \n31. تہٕ ذکلاگ، تہٕ مدمناہ تہٕ سنسانہ، \n32.\\tتہٕ لباؤتھ، تہٕ شِلہِم، تہٕ عین تہٕ رِمون: سٲری شہر چھِ وُہَن تہٕ کُنوُن، تہٕ تِمن ہٕندِس گامَس سٍتۍ: \n33.\\tوادی اشتول تہٕ زوریہ تہٕ اشناہ مَنٛز، \n34. تہٕ زانوہ، تہٕ اینگنیم، تپواہ تہٕ انم، \n35.\\tجرموتھ تہٕ عدلالم، سوکوہ، تہٕ عزیکہ، \n36.\\tتہٕ شرائم، تہٕ ادیتھیم، تہٕ گیڈیرہ، تہٕ گیڈروتھیم۔ ژۅداہ شہر یمن ہٕندِس گامس سٍتۍ: {تہٕ گیڈروتھیم: یا، یا گیڈروتھیم}\n37.\\tزینان، تہٕ ہداشہ تہٕ مگدلگاد، \n38.\\tتہٕ دِلین، تہٕ مزپیہ، تہٕ جوکتھیل، \n39. لاچیش تہٕ بوزکتھ تہٕ ایگلون، \n40. تہٕ کیبون، تہٕ لحم، تہٕ کتھلش، \n41.\\tتہٕ گیڈروتھ، بیت دگون تہٕ نعمہ تہٕ مکیداہ۔ شُراہ شہر، تہندِس گامس سٍتۍ: \n42. لبناہ، تہٕ ایتھر، تہٕ آشان، \n43.\\tتہٕ جفتہ تہٕ اشنہ تہٕ نزیب، \n44.\\tتہٕ کیلہ تہٕ اچزیب تہٕ مریشاہ۔ نو شہر تہٕ تِمن ہٕندِس گامس سٍتۍ: \n45. ایکرون، پننین قصبن تہٕ گامن سۭتۍ: \n46.\\tایکرون پیٹھہ سمندرس تام تہِ چھہِ سٲری یُس اشدودس نزدیک، پننین گامن سٍتۍ: {نزدیک: ہیب۔ جایہ کِس جایہ}\n47. اَشدود پَنٕنـ̡ قصبہٕ تہٕ گامن سٍتـ̡ ، غزہ سٍتـ̡ پنہٕ نـ̡ قصبہٕ تہٕ گامن سٍتـ̡ ، دریائے مصر تہٕ بٔڈِس سمندرس تام، تہٕ اَمہ کِس سرحدس تام: \n48.\\tتہٕ پہاڑن مَنٛز، شمیر، تہٕ جتیر، تہٕ سوکوہ، \n49.\\tتہٕ دنہ تہٕ کرجاتسانہ، یُس {چھ} دیبیر، \n50.\\tعناب، تہٕ اشتیموح تہٕ انیم، \n51. تہٕ گوشن، تہٕ ہولون، تہٕ گیلوہ؛ کاہ شہر یمن ہٕندِ گامن سٍتۍ: \n52. عرب، تہٕ دومہ تہٕ ایشان، \n53.\\tتہٕ جانم، تہٕ بیتپواہ، تہٕ افیکاہ، {جانم: یا، جانس}\n54. تہٕ ہمتہ تہٕ کِرجاتربہ، یُس {چُھ} ہیبرون تہٕ زیور۔ نو شہر یِمن ہٕندِس گامن سٍتۍ: \n55. ماون، کارمل، تہٕ زیف، تہٕ جوتاہ، \n56. تہٕ یِزریل، تہٕ جوکدیم، تہٕ زانواہ، \n57. قاین، گبیاہ تہٕ تیمنا۔ دَہ شَہَر پَنٕنِس گامَس سٍتۍ: \n58. حلہول، بیت زور تہٕ گیدور، \n59.\\tتہٕ مارتھ، تہٕ بیتھانوتھ، تہٕ ایلٹیکون۔ شےٚ شہر، یِمن ہٕندِس گامَس سٍتۍ: \n60. کِرجاتھبال، یُس {چُھ} کِرجاتجیرِم تہٕ رَبَہ چھُ۔ زٕ شَہَر یِمن ہٕندِس گامَس سٍتۍ: \n61.\\tبیابانن مَنٛز، بیتھارابہ، مدین تہٕ سیکاکاہ، \n62.\\tتہٕ نِبشان، تہٕ نمک تہٕ اینگیدی شہر۔ شیہ شہر تہٕ تِہندین گامن سٍتۍ۔ \n63.\\tیێلہِ یێروشلِمٕکۍ بسکیٖن یبوسی ہیوٚک نہٕ یہوداہ کِس بُلِس کٔڈِتھ کٔرِتھ، مگر یبوسی چھِ از تام یروشلمس مَنٛز یہوداہ کین شُرین سٍتـ̡ روزان۔","1. تہٕ یوسف سٕندِ بچہٕ سُند لُٹ ووت اردن پیٹھٕ یریحو کِس آبس تام، یُس یریحو پیٹھہٕ بیت کِس پہاڑس تام واتان چُھ، {پۯاوُن: ہیب۔ گٔیہِ نیرُن}\n2. تہٕ نیرِ بیت لوز کُن، تہٕ آرچی کِس سرحدس تام واتناوان اتاروتھ تام، \n3.\\tتہٕ مغرب کُن یافلیتی کِس بٹھس کُن، بیت ہرون کِس بٹھس تام، تہٕ گیزرس کُن گژھُن: تہٕ تتہِ نیبر نیرن وٲلس سمندرس کُن۔ \n4.\\tیێمہِ سٍتـ̡ یوسف، منسیٰ تہٕ افرائیم سٕندیو اولاوو رٔٹ پنُن وراثت۔ \n5.\\tتہٕ افرائیم سٕندِ اولاد ہُند سرحد اوس تہندِس عیالس مطٲبق {یِتھٕ پٲٹھۍ}: یێلہِ تہِ اوس مشرقس کُن تہندِ وراثتُک سرحد اتاروتھدار، یُس پیٹھمہِ بیتھورس تام۔ \n6.\\tتہٕ سرحد گٔیہِ شمالس کُن میخمیتھاہ کُن سمندرس کُن۔ تہٕ سرحد گٔیہِ مشرقس کُن تاناتشیلوہس تام، تہٕ مشرقس کُن گٔیہِ جانوہس کُن۔ \n7. تہٕ یہِ ووت جانوحہ پٮ۪ٹھٕ اتاروت تہٕ نارتس تام، تہٕ آو یریحو تہٕ اردن کُن درٛاو۔ \n8.\\tسرحد دراو تپواہ پیٹھہ مغرب کُن دریائے کانہ تام۔ تہٕ اَمہ نیبر نیرُن اوس سمندرس کُن۔ یہ چھہ افرایم سٕندِس قبیلس ہٕندِس خاندانس سٍتـ̡ وراثت۔ \n9. تہٕ افرائیم سٕندِ اولادٕ خٲطرٕ الگ الگ شہر ٲسۍ منسی ہٕندِس اولادَن ہٕندِس وراثتس مَنٛز، سارِنٕے شہرن ہٕندِس گامن سٍتـ̡ ۔ \n10.\\tتہٕ تِمو کٔرِتھ کٔڈِتھ کنعانی یِم گیزرس منز روزان ٲسۍ، مگر کنعانی چھِ از تام افریمیَن مَنٛز روزان تہٕ خراج دِنس سٍتـ̡ خدمت کران۔","1.\\tمنسی قبیلہٕ خٲطرٕ تہِ اوس واریاہ زیادٕ۔ تکیازِ سُہ اوس یوسف سُند گۄڈنیُک زامُت۔ {مَضموٗن}، مَخیٖر سٕندِ خٲطرٕ، یُس گُلعادُک مول اوس، تِکیازِ سُہ اوس جنگُک آدمی، اَمہِ مۄکھٕ اوس أمِس گلعاد تہٕ بشان۔ \n2.\\tمنسی ہٕندٮ۪ن باقٕے شُرین ہٕندِ خٲطرٕ تہِ اوس تِہندِ عیالہٕ سٍتـ̡ {واریاہ زیادٕ}۔ عبیزر سٕندِ شُرین خٲطرٕ، تہٕ ہیلیک سٕندٮ۪ن شُرین خٲطرٕ، تہٕ شیکیم سٕندٮ۪ن شُرین خٲطرٕ، تہٕ ہیفر سٕندٮ۪ن شُرین خٲطرٕ، تہٕ شیمیدہ سٕندٮ۪ن شُرین خٲطرٕ: یِم ٲسۍ یوسف سٕندِس نیٚچوِس مَنسہ سٕندِ نیٚچُوِ ہٕندِ خٲطرٕ۔ {عبیزر: یِمن تہِ وَننہٕ یوان چھُ، جیزر}\n3.\\tمگر زیلوفہد، ہیفر سُند نیچو، گلعاد سُند نیچو، مخرُک نیچو، مناسہ سُند نیچو، تہٕ یِم چھِ تٔمۍ سٕنزِ کورِ مہلہ تہٕ نوح، ہوگلہ، ملکہ تہٕ ترزہ ہٕندۍ ناو۔ \n4. تہٕ تِم وٲتۍ پادٕرۍ الیعزرس برونہہ کُن، تہٕ نون سٕندِس نیچوِس یشوع سٕندِس برونہہ تہٕ شہزادن برونہہ کُن، یہِ وونُن زِ خداوند دِیُت موسیٰ سُند حُکُم زِ سُہ دِیہِ اسہِ بٲے سٕندِس مَنٛز وَرث۔ تێمہِ کِنۍ دِژ خداوند سٕندِ حُکمہٕ مُطٲبق تِمن پننِس مٲلہِ سٕندِس بٲے سٕندِس مَنٛز وٲرث۔ \n5.\\tتہٕ گِلعاد تہٕ باشان کِس سرزمینس سٍتـ̡ گٔیہِ منسیہس سٍتـ̡ داہ حصہٕ، یُس اردن کِس دوٚیمہِ طرفہٕ اوس۔ \n6.\\tتِکیازِ منسی سٕنزِ کورِ ٲس تٔمۍ سٕندِس نیچوِس مَنٛز وراثت: تہٕ منسی سٕندِس باقٕے نیٚچوِس ٲس جلعادٕچ زمین۔ \n7.\\tتہٕ منسیٰ ہُند بوٚٹھ اوس آشر پیٹھہ مِخمیتھا تام، یُس شیکیمس برونہہ اوس۔ تہٕ سرحد اوس دچھنہِ طرفہٕ انتپواہ کین بسکینن تام۔ \n8.\\tمَنَس مَنسِس مَنٛز اوس تپواہُک زٔمیٖن: مَگَر مَنسِہ کِس بَحَدس پؠٹھ اوس تَپواہ اَفرایم سٕندِس بُلِس سٍتـ̡ ۔ \n9.\\tتہٕ بٔٹھۍ ووت دریائے کانہ کِس جنوبس کُن: افرائیم سٕندِ یِم شہر چِھہ مناشہ کِس شہرن مَنٛز: منسیٰ ہُند بٔٹھِس تہِ اوس دریاو کِس شمالس کُن، تہٕ اَمہ کِس نیبر نیرن وٲلِس سمندرس مَنٛز: {دریائے کانہ: یا، سرن ہُند نالہٕ}\n10.\\tجنوبس کُن اوس افرایم سُند، تہٕ شمالس کُن اوس مناسہ سُند، تہٕ سمندرٕ اوس تٔمۍ سُند سرحد۔ تہٕ تِم سمکھے شمالس کُن آشرس مَنٛز تہٕ مشرقس مَنٛز اِساکرَس مَنٛز۔ \n11.\\tتہٕ منسیٰ اوس اِساکرس مَنٛز تہٕ آشر بیت شیان تہٕ تٔمۍ سٕندِس قصبس منز، تہٕ اِبلام تہٕ تٔمۍ سٕندِس قصبس مَنٛز، تہٕ ایندور تہٕ تٔمۍ سٕندِس قصبن ہٕندِس بسکین، تہٕ تَنَخ تہٕ تٔمۍ سٕندِس قصبَن ہٕندِس بسکین، تہٕ میگیڈو تہٕ تٔمۍ سٕندِس قصبن ہٕندِس بسکین، تریہ مُلکس منز۔ \n12.\\tتوتہِ ہیوٚک نہٕ منسی ہٕندِ بچہٕ یِمن شہرن ہٕندِس بسکینس کٔڈِتھ کٔرِتھ۔ مگر کنعانی ٲسۍ اَتھ زمینس مَنٛز روزان۔ \n13. توتہِ سپُد یہِ سپدُن، ییلہ بنی اسرٲیلِس مضبوطہٕ گٔیہ، تِمو کٔر کنعانین خراج دِنہٕ۔ مگر کٔرِکھ نہٕ تِم پوٗرٕ پٲٹھۍ۔ \n14.\\tتہٕ یوسف سٕندٮ۪و اولادَو ووٚن یشوع سٍتـ̡ وَنُن زِ ژے کیازِ دِژ میہ اَکھ لُکھ تہٕ اکھ حصہٕ وٲرثس مَنٛز دِژمُت، یێلہِ بہٕ چُھس اَکھ بٔڈ لُکھ ، یێلہِ زن خداوند چُھس وُنیُک تام میہ برکت دِژمُت؟ \n15.\\tتہٕ یشوع ہن دیُت تِمن جواب، یێلہِ تہٕ یێلہِ ژیہ بٔڈ لُکھ بٔنِتھ تہٕ ژٔٹِو پانس خٲطرٕ پیرِزِین تہٕ دیوَن ہٕندِس سرزمینس مَنٛز، یێلہِ افرایم پہاڑ تۅہہِ خٲطرٕ سٮ۪ٹھاہ تنگ آسہِ۔ {دیو: یا، رفیمس}\n16.\\tتہٕ یوسف سٕندٮ۪و اولادو ووٚن، بالہٕ چُھنہٕ سانہِ خٲطرٕ کٲفی: تہٕ وادی ہٕندِس سرزمینس مَنٛز روزن وٲلِس سارِنٕے کنعانی نِش چھِ شِشتٕرٕکۍ رتھ، یِم بیت شیان تہٕ تٔمۍ سٕندِس شہرٕکۍ چھِ، تہٕ یِم یِم وادی یزریل ہٕندِس رتھٕکۍ چھِ۔ \n17.\\tتہٕ یشوع کٔر یوسف سٕندِس گرس سٍتـ̡ افرائیم تہٕ منسیہس سٍتـ̡ وونُن زِ تہٕ چُھکھ اکھ بۆڈ لُکھ تہٕ چُھس واریاہ طاقت: تێہہ آسہِ نہٕ اَکھ لُکھ {صرف}۔ \n18.\\tمگر پہاڑ گژھہِ تۅہہِ آسہِ۔ تکیازِ یہ چھہ اکھ لٔکر، تہٕ ژیہ ژٔٹِتھ ژٔٹِتھ تہٕ اَمہ ہُند نیبر گژھہِ تۅہہِ آسہِ، تکیازِ تۅہہ کٔرِو کنعانی ژٔلِتھ ژٔلِتھ، یێلہِ تہِ تِمن نِش ششتٕرِ رَتھ آسہِ، {تہٕ} یێلہِ تہِ تِم {مضبوط} آسن۔","1. تہٕ بنی اسرٲیلِچ سورے جماعت گٔیہِ شیلوہس مَنٛز جمع تہٕ کٔرٕکھ اَتہِ جمٲژ ہُند خیمہ قٲیم۔ تہٕ زمین گٔیہِ تِمن برونہہ کنہِ زیر کرنہٕ۔ \n2. تہٕ بنی اسرٲیلِس مَنٛز رودۍ سَتھ قبیلہٕ، یِمن نہٕ وُنیُک تام پنُن وَراثت مِلیوٚومُت اوس۔ \n3. تہٕ یشوع ہن ووٚن بنی اسرٲیلِس زِ تُہۍ کوتاہ کالہٕ چُھہ تتھ زمینس پیٹھ قبضہ کرنہٕ خٲطرٕ سُست روزان، یُس تہندین مٲلن ہٕندِس خداہِ سٕندِ خداہن دِژمُت چُھ؟ \n4. پانس منزٕ دِیو تریہ نفر {پرٮ۪تھ کُنہِ} قبیلہٕ خٲطرٕ: تہٕ بہٕ سوزٕ تِم تہٕ تِم گژھن وۅتھان تہٕ زمینہٕ مٔنزۍ گٔژھِن، تہٕ تِمن ہٕندِ وراثتہٕ مطٲبق بیان کرنہٕ۔ تہٕ تِم یِن میہ نِش یِن۔ \n5. تہٕ تِم کٔرِن اتھ ستن حصن مَنٛز تقسیم: یہوداہ روزِ جنوبس کُن پننِس ساحلس مَنٛز، تہٕ یوسفُن گرٕ روزِ شمالس کُن تہندِس ساحلس مَنٛز۔ \n6. تێمہِ کِنۍ کٔرِو تُہۍ زمینہِ ہٕنز وضاحت کٔرِتھ، تہٕ یێلہِ أنِو میہ نِش، یُتھ بہٕ یێلہِ تہِ کٔرِو تۅہہِ خٲطرٕ سٲنِس خداہس برونہہ کُن قرعہٕ۔ \n7. مگر لاوِین ہُند چُھنہٕ تُہٕندِس مَنٛز کانہہ حصہٕ۔ یێلہِ چُھہ خداوند سٕندِ پادٕرۍ سٕندِ وٲرثہٕ سٍتـ̡ تہٕ گاد، روبن تہٕ نصف قبیلہٕ چُھہ مشرقس کُن اردن نیبر پنُن وراثت حٲصل کورمُت، یُس خداوند سٕندِ خادم موسیٰ سٕندِ دِژمُت چُھ۔ \n8. تہٕ مرد ووٚتھ تہٕ گٔیہِ ژٔلِتھ تہٕ یشوع دِیُت تِمن ہُند حکم یُس زمینہِ ہُند بیان کرنہٕ خٲطرٕ گٔیہِ، تہٕ وونُن زِ گژھ تہٕ زمینس مٔنزۍ پٔکِتھ پٔکِتھ تہٕ بیان کٔرِتھ یُس بہٕ یِمن ہٕندِ خٲطرٕ شیلوہس منز خداوند سٕندِ برونہہ کُن لاٹری تراوُن۔ \n9.\\tتہٕ مرد گٔیہِ زمینہٕ مٔنزۍ تہٕ شہرن ہٕندِ طرفہٕ أکِس کتابہِ منز ستن حصن منز بیان کرنہٕ، تہٕ آو یشوع نِش شیلوہس کِس میزبانس نِش۔ \n10. تہٕ یشوع کٔر خداوند سٕندِ برونہہ کُن شیلوہس مَنٛز تِمن ہٕندِ خٲطرٕ قرعہٕ۔ تہٕ تتہِ کٔر یشوع یِمن ہٕندِس تقسیٖمہٕ مُطٲبِق بنی اِسرٲیلِس مَنٛز زمین۔ \n11.\\tتہٕ بنیامین سٕندٮ۪ن اولادَن ہٕندِس قبیلہٕ سٍتـ̡ ووت تہندِس عیالس مُطٲبق۔ تہٕ یہوداہ سٕندٮ۪ن شُرین تہٕ یوسف سٕندِس شُرین درمِیان درمِیان ووت تِہٕندِس قٕسمُک بٔٹھ۔ \n12.\\tتہٕ شمالس طرفہٕ اوس تِہُند سرحد اردن پیٹھ۔ تہٕ سرحد اوس شمالس کُن یریحو کِس طرفہٕ تہٕ مغرب کُن پہاڑو کِنۍ ہیوٚر۔ تہٕ تتہِ نیبر نیرن وول اوس بیت ہیون کِس بیابانس منز۔ \n13. تہٕ سرحد گٔیہِ تتہِ پیٹھہٕ لوز کُن، یُس {چُھ} بیتھل، جنوبس کُن۔ تہٕ سرحد ووت اتروتھادرس کُن، تتھ بالس نزدیک، یُس نیتھر بیتھورون کِس جنوبس طرفہٕ {lieth} چُھ۔ \n14.\\tتہٕ سرحد آو کھیننہٕ، تہٕ سمندرُک کوُن اوس جنوبس کُن، تتھ بالہٕ پیٹھٕ یُس جنوبس کُن {lieth} اوس۔ تہٕ تتہِ نیبر نیرن وول اوس کرجاتھبالس منز، یُس {چُھ} کرجاتھجاریم چُھ، یہوداہ کین بچن ہُند اکھ شہر: یہِ اوس مغرب کُن۔ \n15.\\tتہٕ جنوبُک ژوٗر اوس کِرجاتجیریم کِس اندس پیٹھ، تہٕ سرحد دراو مغربس کُن، تہٕ نیفتوہ کِس آبس کِس کۅرس تام گٔیہ: \n16.\\tتہٕ سرحد ووت پہاڑ کِس اندس تام یُس {lieth} ہِنوم سٕندِس نیچو سٕنزِ وادی برونہہ کُن، {تہٕ} یُس {چُھ} شمالس کُن دیوَن ہٕنزِ وادی مَنٛز، تہٕ ووت ہینوم کِس وادی کُن، جنوبس کُن جیبوسی کِس طرفہٕ، تہٕ ووت اینروگیلس کُن۔ \n17.\\tتہٕ آو شمالہٕ کِنۍ کھسنہٕ، تہٕ ووت انشیمشس کُن، تہٕ ووت گیلیلوتھس کُن، یُس ادومیمس کھسنہٕ خلاف چُھ، تہٕ ووت روبن سٕندِس نیچو بوہان سٕندِس کنس کُن، \n18.\\tتہٕ ووت عربہ کُن شمالس کُن، تہٕ ووت عربہ کُن: {عربہ: یا، میدان}\n19.\\tتہٕ سرحد ٲس بیت ہوگلہ کِس شمالس کُن پکان: تہٕ سرحدُک نیبر نیرُن اوس اردن کِس جنوبی اندس پیٹھ نمک سمندر کِس شمٲلی خلیج کِس کُن: یہِ اوس جنوبی ساحل۔ {بے: عبری۔ زبان}\n20. تہٕ اردن اوس مشرقس طرفہٕ امچ سرحد۔ یہٕ اوس بنیامین سٕندٮ۪ن شُرین ہُند وراثت، یُس تِہندِ عیال مطٲبق اندۍ پٔکھۍ اندۍ پٔکھۍ بٔٹھۍ۔ \n21. وۅنۍ ٲس بنیامین سٕندِ اولاد ہٕندِ قبیلہٕ ہٕندِس عیالس مطٲبق یریحا تہٕ بیت وگلہ تہٕ وادی کیزیز، \n22.\\tتہٕ بیتھرابہ تہٕ زیماریم تہٕ بیتھل، \n23. تہٕ اویم تہٕ پارہ تہٕ اوفراہ، \n24.\\tتہٕ چیفرہاممونائی تہٕ اوفنی تہٕ گابا۔ باہ شہر تہندٮ۪ن گامَن سٍتۍ: \n25.\\tگِبیون، تہٕ رامہ تہٕ بیروتھ، \n26. تہٕ مزپیہ، تہٕ چفیرہ تہٕ موزہ، \n27. تہٕ رکیم، تہٕ ارپیل، تہٕ ترالہ، \n28.\\tتہٕ زیلاہ، ہوٚس تہٕ یبوسی، یُس {چُھ}یروشلم، گِبیتھ، {تہٕ} کرجاتھ۔ ژۄداہ شہر تہٕ تِہندین گامن سٍتـ̡۔ یہِ چُھ بنیامین سٕندٮ۪ن شُرین ہٕندِ خاندانہٕ مُطٲبق وٲرث۔","1. تہٕ دۆیم لاٹ آو شمعون سٕندِس خاندانس مطٲبق تہٕ تِہُند وراثت اوس یہوداہ کین اولادن ہٕندِس وراثتس منز۔ \n2.\\tتہٕ تِمن ہٕندِس وَرستس مَنٛز ٲس بیرشیبع، یا شیبا تہٕ مولادہ، \n3. تہٕ ہزارشوال، تہٕ بالاہ تہٕ عظم، \n4. تہٕ ایلتولاد، تہٕ بیتول، تہٕ ہورمہ، \n5. تہٕ زِکلاگ، تہٕ بیت مارکابوتھ، تہٕ ہزارسوس، \n6. تہٕ بیت لباؤتھ تہٕ شاروہن۔ ترہ شہر تہٕ تِہند گام: \n7. عین، ریمون تہٕ ایتھر تہٕ آشان۔ ژور شہر تہٕ تِہند گام: \n8.\\tتہٕ تِم سٲری گام یِم یِمن شہرن اندۍ پٔکھۍ ٲسۍ، جنوبُک رامتھ بعلتھ بیرس تام۔ یہ {چُھ} شمعون سٕندِ اولاد ہٕندِس قبیلس ہٕندِ خاندانہٕ مُطٲبق وراثت۔ \n9.\\tیہوداہ کین اولادن ہٕندِس حصس مَنٛز اوس شمعون سٕندِ اولادُک وراثت، تکیازِ یہوداہ سٕندِس اولادس ہُند حِصہٕ اوس تِہندِ خٲطرٕ واریاہ زیادٕ، تِکیازِ سِمعون سٕندِس اولادس اوس تِمن ہٕندِس وَرستس مَنٛز وَرث۔ \n10.\\tتہٕ تریم لاٹ آو زبولون سٕندِ اولاد خٲطرٕ تہندِس عیالس مطٲبق: تہٕ تِہٕندِس وراثتُک سرحد اوس سریدس تام۔ \n11.\\tتہٕ تِہُند سرحد ووت سمندرس کُن، تہٕ مارالہ کُن تہٕ ووت دباشیتھس تام، تہٕ ووت دریاوس تام یُس جوکنیمس برونہہ کُن چھُ۔ \n12.\\tتہٕ ووت سارِد پیٹھہ مشرقس کُن آفتاب کھسنہٕ کُن چِسلوتھبور کِس سرحدس کُن، تہٕ پَتہٕ گٔیہِ دابراتھ کُن تہٕ یافیہ کُن گژھُن، \n13. تہٕ تتہٕ پیٹھہٕ چُھ مشرقس کُن گِتاھہیفر کُن، اِٹاہکازینس کُن نیران، تہٕ ریمونمیتھورس کُن نیاہس کُن نیران۔ {میتھوآر: یا، یُس کھیننہٕ چُھ آمُت}\n14. تہٕ سرحد چِھ اتھ شمالس طرفہٕ ہناتھنس تام گھیرتھ: تہٕ امیک نیرن وول چُھ وادی جفتاہیل منٛز: \n15.\\tتہٕ کتاتھ، تہٕ نہلال، تہٕ شمرون، تہٕ اڈالہ تہٕ بیت اللحم: باہ شہر تہٕ پننین گامن سٍتۍ۔ \n16.\\tیہِ چُھ زبولون کین شُرین ہٕندِ خاندانہٕ مُطٲبق وراثت، یِمن شہرن ہٕندِس گامن سٍتـ̡ ۔ \n17.\\tژوٗرِم لاٹ آو اِساکر سٕندٮ۪ن شُرین ہٕندِ خٲطرٕ تہندِس عیالس مُطٲبِق۔ \n18.\\tتہٕ تِہُند سرحد اوس یزریل، تہٕ چیسولوت تہٕ شونیمس کُن۔ \n19.\\tتہٕ ہفاریم تہٕ شیون تہٕ انہارتھ، \n20. تہٕ خرگوش تہٕ کیشیون تہٕ ابیز، \n21.\\tتہٕ ریمیتھ، تہٕ اینگنیم، تہٕ انہداہ، تہٕ بیت پازیز۔ \n22.\\tتہٕ ساحل چُھ طبور تہٕ شہزیمہ تہٕ بیت شیمشس تام واتان۔ تہٕ تِہٕندِس سرحدس پیٹھ اوس اردنس مَنٛز: شُراہ شہر تہٕ تِہندین گامن سٍتۍ۔ \n23.\\tیہِ چھُ عیساکار سٕندٮ۪ن شُرین ہٕندِس قبیلس ہٕندِس خاندانن، شہرن تہٕ تِہندِ گامن مُطٲبق وراثت۔ \n24.\\tتہٕ پٲنژِم لاٹ دراو آشر سٕندِس قبیلہٕ سٕندِ خٲطرٕ تہندِ عیالہٕ مُطٲبق۔ \n25.\\tتہٕ تِہُند سرحد اوس ہیلکاتھ، تہٕ ہالی، تہٕ بیتن تہٕ اچشاف، \n26.\\tتہٕ عالمیخ، تہٕ عماد، تہٕ مِشِل؛ تہٕ چُھ مغرب کُن کارملس تام تہٕ شہورلبناتھس تام واتان۔ \n27. تہٕ آفتاب کھسنہٕ کُن پھیران بیت دگون کُن، تہٕ زیبولون کُن تہٕ بیتھیمک تہٕ نیل کِس شمالس کُن وادی جفتاہیل کُن واتہٕ، تہٕ کھوورِ طرفہٕ چُھ کابُل کُن نیران۔ \n28.\\tتہٕ حبرون، تہٕ رہوب، تہٕ ہمون تہٕ کانہ، {حتیٰ کہ} عظیم زیدونس تام۔ \n29. تہٕ {پتہٕ} بٔٹھہِ چُھ رامہ کُن پھیران، تہٕ مضبوط شہر صور کُن۔ تہٕ ساحل چُھ ہوشاہس کُن پھیران۔ تہٕ اَمہ سٕندِس سمندرس کُن چُھ بٹھہٕ پیٹھہٕ اچزیب کُن: {Tyre: Heb. Tzor}\n30.\\tاُمہ تہٕ افیک تہٕ ریہوب: وُہ تہٕ زٕ شہر تہٕ پنہٕ نِس گامس سٍتۍ۔ \n31.\\tیہِ چُھ آشر سٕندِس اولادَن ہٕندِس قبیلہٕ سٕندِ خاندانہٕ مُطٲبق وراثت، یِمن شہرن ہٕندِس گامن سٍتـ̡ ۔ \n32.\\tشیم لاٹ آو نفتالی کین شُرین نفتالی کین بچن ہندِ خاطرہ تہندِ عیال مطٲبق۔ \n33.\\tتہٕ تِہُند ساحل اوس حلیفہٕ پیٹھ، علون پیٹھٕ زانانیم تام، تہٕ آدمی، نکیب تہٕ جبنیل تام، لاکوم تام۔ تہٕ تِمن ہُند بٔٹھۍ اوس اردنس مَنٛز: \n34. تہٕ {پتہٕ} چُھ ساحل مغرب کُن ازنوتھبور کُن پھیران تہٕ تتہِ پیٹھہٕ ہکوک کُن گژھان تہٕ جنوبس طرفہٕ چُھ زیبولون تام واتان، تہٕ مغرب طرفہٕ آشر تام تہٕ آفتاب کھسنہٕ کُن اردن پیٹھ یہوداہ تام واتان۔ \n35.\\tتہٕ تار لگاونہٕ آمٕتۍ شہر چھِ زیدیم، زر، تہٕ ہمتھ، راکتھ تہٕ چنیریتھ، \n36. تہٕ آدمہ، تہٕ رامہ تہٕ حزور، \n37.\\tتہٕ کیدیش تہٕ ادری، تہٕ انہزور، \n38. تہٕ ششتٕر، تہٕ مگدالیل، حورم، تہٕ بیتھاناتھ تہٕ بیت شیمش۔ کُنوُہ شہر تہٕ تِمن ہٕندِس گامس سٍتۍ۔ \n39.\\tیہ چھہ نفتالی کین بچن ہٕندِ قبیلہٕ سٕندِ خاندانن، شہرن تہٕ تہندین گامن مطٲبق وراثت۔ \n40. {تہ} سٔتِم لاٹ دراو دان کین بچن ہٕندِس قبیلس خٲطرٕ تہندِ عیال مطٲبق۔ \n41.\\tتہٕ تِہٕندِ وراثتُک بٔٹھۍ اوس زورہ، تہٕ اشتاول تہٕ ارشیمیش، \n42.\\tتہٕ شعلبین، تہٕ اجلون تہٕ جثلہ، \n43.\\tتہٕ ایلون، تہٕ تھیمناتھا، تہٕ ایکرون، \n44.\\tتہٕ ایلٹیکہ، تہٕ گبتھن، تہٕ بعلتھ، \n45. تہٕ یہود تہٕ بینیبیرک تہٕ گتھرمون \n46. تہٕ میجارکون، تہٕ راکون، جافو برونٹھ سرحدس سۭتۍ۔ {برونٛہہ: یا، اوور خلاف} {جافو: یا، جوپا}\n47.\\tتہٕ دان سٕندٮ۪ن شُرین ہُند بٔٹھہِ گۆو تِمن ہٕندِ خٲطرٕ {واریاہ کم}، تێمہِ کِنۍ گٔیہِ دان سٕندِ بچہٕ لِشمس سٍتـ̡ لڑنہٕ خٲطرٕ، تہٕ رٔٹِتھ لٔگِتھ تلوار ہٕندِس کنارس سٍتـ̡ لٔگِتھ تہٕ کوٚرُکھ اَتھ مَنٛز روزُن، تہٕ وونُن لیشیم، دان، یُس تِمن ہٕندِس مٲلِس دان سٕندِس ناوٕ سٍتـ̡ اوس۔ \n48.\\tیہِ چُھ دان سٕندٮ۪ن شُرین ہٕندِس قبیلس ہٕندِس خاندانس مُطٲبق وراثت، یِمن شہرن ہٕندِس گامن سٍتـ̡ ۔ \n49. ییلہ تِمو پننین ساحلن سٍتـ̡ وراثتس مۅکھہ زمینہٕ تقسیم کرُن ختم کٔر، بنی اسرٲیلیو دِژ تمن منز نون سٕندِس نیچوِس یشوع سٕندِس وراثتس منز۔ \n50.\\tخداوند سٕندِ کلامَس مُطٲبق دِژ تمِس سُہ شہر یُس تٔمۍ پرژھمُت اوس، تہٕ تٔمۍ بنوو شہر تہٕ اَتھ مَنٛز روزُن۔ \n51.\\tیِم چھِ تِم وراثت، یِم الیعزر پادٕر، تہٕ یشوع نون سُند نیچو، تہٕ بنی اسرٲیلِن ہٕندِس قبیلن ہٕندِس مٲلِس ہٕندِس مٲلِس سٍتـ̡ وَرثہٕ خٲطرٕ بٲگراونہٕ آمٕتۍ۔ یێمہِ سٍتـ̡ کۆر تِمو ملکُک بٲگراونُک خاتمہٕ۔","1. خداوند تہِ ووٚن یشوع سٍتـ̡ وونُن، \n2.\\tبنی اسرٲیلِس سٍتـ̡ کتھ کٔرِو تہٕ وَنُن زِ تۅہہِ خٲطرٕ کٔرِو پناہ گاہٕچ شہر، یِمن مُتلق مے موسیٰ سٕندِ اتھہٕ سٍتـ̡ کتھ کٔرمٕژ چھےٚ: \n3.\\tیُس قاتل یُس کانہہ تہِ شخص بے خبری منز قتل کرِ، سُہ گژھہِ تتہِ ژلُن: تہٕ سُہ گژھہِ خونُک انتقام نِش تۅہہِ پناہ گاہ۔ \n4.\\tیێلہِ یُس یُس یِمن شہرن منز کُنہِ کُنہِ شہرس کُن ژلِتھ نیرِ، سُہ گژھہِ شہرٕ کِس دروازس منز اژنہٕ وِزِ کھڑا تہٕ تٔمِس شہرٕکۍ بزرگن ہٕندِس کنن منز پنُن اعلان کرِ، تِم نِن أمِس شہرس مَنٛز تہٕ دِژن تِمن مَنٛز روزنہٕ خٲطرٕ۔ \n5. تہٕ اگر خونُک انتقام لینے وول أمِس پَتہٕ یِنہٕ تِم قاتل أمِس اَتھَس مَنٛز واتناوُن۔ تِکیازِ تٔمۍ کٔر پننِس ہمساین ہٕندِس نادانسٲنی سٍتـ̡ مارٕ، تہٕ أمِس سٍتـ̡ اوس نہٕ أمِس سٍتـ̡ نفرت۔ \n6. تہٕ سُہ روزِ اَتھ شہرس مَنٛز، یوتام سُہ جمٲژ برونہہ کُن کھڑا روزِ، یُس تِمن دۅہن بٔڈِس پادٕرۍ سٕندِس مرنہٕ سٍتـ̡ یُس تِمن دۅہن آسہِ۔ \n7.\\tتہٕ تِمو کٔر گلیل کِس کوہ نفتالی مَنٛز کیدیش تہٕ افریم کِس پہاڑس مَنٛز شیکیم تہٕ یہوداہ کِس پہاڑس مَنٛز کِرجاتاربا مقرر کٔرِتھ۔ {مُقرر: حب۔ مُقدس}\n8.\\tتہٕ دوٚیمہِ طرفہٕ یریحو کِس مشرقس کُن یِمو بیزرس بیابانس مَنٛز روبن قبیلہٕ منزٕ مٲدانس مَنٛز، تہٕ گاد قبیلہٕ منزٕ گیلعادس مَنٛز راموتھ تہٕ منسی قبیلہٕ منزٕ بشانس مَنٛز گولان مقرر کٔرِتھ۔ \n9.\\tیِم شہر ٲسۍ یِم سارِنٕے بنی اسرٲیلـ̡ خٲطرٕ مقرر کرنہٕ آمٕتۍ، تہٕ یُس تہِ یِمن مَنٛز روزان چُھ، یُس تہٕ یُس تہِ بے خبری منز کانہہ تہِ شخص قتل کرِ، سُہ گژھہِ تتہِ ژلِتھ تہٕ سُہ گژھہِ نہٕ خونُک انتقام کَرن وٲلِس اتھہٕ سٍتـ̡ مَرُن، یوتام نہٕ سُہ جمٲژ برونہہ کنہِ کھڑا سپدِ۔","1. پَتہٕ آو لاوِین ہٕندِس مٲلن ہٕندِس کلہٕ نزدیک، پادٕرۍ الیعزارس نِش، تہٕ نون سٕندِس نیچوِس یشوعہس نِش، تہٕ بنی اسرٲیلِین ہٕندِس قبیلن ہٕندِس بابن ہٕندِس کلہٕ تام۔ \n2.\\tتہٕ تِمو کٔر کنعان کِس سرزمینس منز شیلوہس مَنٛز تِمن سٍتـ̡ کتھ باتھ تہٕ وونُن زِ خداوند دِیُت موسیٰ سٕندِ اتھہٕ سٍتـ̡ حُکُم زِ سُہ دِیہِ اسہِ بَسنہٕ خٲطرٕ شہر، یێمہِ سٍتـ̡ سانہِ چارواین ہٕندِ خٲطرٕ روزنہٕ خٲطرٕ۔ \n3. تہٕ بنی اسرٲیلیو دِژ خداوند سٕندِس حُکمس سٍتـ̡ یِم شہر تہٕ تِمن ہٕندِس مضافاتس سٍتـ̡ پننہِ وراثتہٕ سٍتـ̡ لاوِین دِنہٕ۔ \n4.\\tتہٕ لوٹ دراو کوہتھین ہٕندِس عیالس خٲطرٕ: تہٕ ہارون پادٕرۍ سٕندِ اولاد، یُس لاوی سٕندِ قبیلہٕ منزٕ تہٕ شمعون قبیلہٕ منزٕ تہٕ بنیامین سٕندِ قبیلہٕ منزٕ گٔیہِ ترہ شہر۔ \n5.\\tتہٕ کُہات کِس باقٕے بُلِس بٔنِتھ افرایم قبیلہٕ کِس خاندانس منز، تہٕ دان قبیلہٕ منزٕ تہٕ مناشہ کِس نصف قبیلہٕ منزٕ دَہ شہر۔ \n6.\\tتہٕ گرشون سٕندِ اولادٕ گٔیہِ اِساکر قبیلہٕ کِس خاندانس منز، تہٕ آشر کِس قبیلہٕ منزٕ تہٕ نفتالی قبیلہٕ منزٕ تہٕ بشانَس مَنٛز مناسشہ کِس نصف قبیلہٕ منزٕ ترٕہ شہرن منز۔ \n7.\\tمیراری ہٕندِس عیالس سٍتـ̡ گٔیہِ روبن سٕندِ قبیلہٕ منزٕ تہٕ گاد قبیلہٕ منزٕ تہٕ زبولون قبیلہٕ منزٕ باہ شہر۔ \n8. تہٕ بنی اِسرٲیلِیو دِژ لاوِین یِم شہر تِمن ہٕندِس مضافاتس سٍتـ̡ قرعہٕ سٍتـ̡ دِنہٕ، یِتھ کٔنۍ خداوند موسىٰ سٕندِ اتھہٕ سٍتـ̡ حُکُم دِیُت۔ \n9.\\tتہٕ یِمو دِژ یہوداہ کِس اولادَن ہٕندِس قبیلہٕ منزٕ تہٕ شمعون سٕندِ اولاد قبیلہٕ منزٕ یِم شہر {یِتھ} ناوٕ سٍتـ̡ دِنہٕ آمٕتۍ، {ذِکر: حب۔ وننہٕ آمُت}\n10.\\tیُس ہارون سٕندِس اولادَس منز، یُس لاوی سٕندٮ۪ن اولادَن ہٕندِس خاندانس منز، یُس لاوی سٕندِس اولادَس مُتلِق اوس، تکیازِ تِمن ہُند اوس گۅڈنِچہِ لٹہِ۔ \n11.\\tتہٕ تِمو دِژ تِمن اربا شہر، یُس یہوداہ کِس بالہٕ {ملک} مَنٛز چُھ، یُس اَتھ اندۍ پٔکھۍ علاقہٕ چُھ۔ {شہر...: یا، کرجاتاربا}\n12.\\tمگر شہرٕکۍ کھہَو تہٕ اَمہِ کِس گامَو دِژ یِم یِم یپھُنہٕ سٕندِس نیچوِس کالبس دِنہٕ۔ \n13. یِتھٕ پٲٹھـ̡ دِژ تِمو ہارون سٕندِس شُرین پادٕرۍ حبرون سٕندِس مضافاتس سٍتـ̡ ، {یُس قاتل سٕندِ خٲطرٕ پناہ گاہُک شہر بنہٕ خٲطرٕ﴾۔ تہٕ لِبنہٕ سٕندِس مضافاتس سٍتـ̡ ، \n14.\\tتہٕ جتیر پننین مضافاتن سٍتۍ، تہٕ اشتیموا پنہٕ نِس مضافاتس سٍتۍ، \n15.\\tتہٕ ہولون پننین مضافاتن سٍتۍ، تہٕ دیبیر پننین مضافاتن سٍتۍ، {ہولون: تہِ ونان ہیلن}\n16. تہٕ عین پننین مضافاتن سٍتۍ، تہٕ جوتہ پنہٕ نِس مضافاتس سٍتۍ، {تہٕ} بیت شیمش پننین مضافاتن سٍتۍ۔ یمن دون قبیلن منز نو شہر۔ {عین: یتھ تہِ ونان چھہِ}\n17.\\tتہٕ بنیامین قبیلہٕ منز، گیبیون پننین مضافاتن سٍتۍ، گیبا پننین مضافاتن سٍتۍ، {گیبا: یتھ گابا تہِ ونان چھِ}\n18. اناتھوتھ پننین مضافاتی علاقن سۭتۍ، تہٕ المون پننس مضافاتی علاقن سۭتۍ۔ ژور شہر۔ {المون: یتھ الیمیث تہٕ ونان چِھ}\n19.\\tہارون سٕندِ اولاد ہٕندِس سارِنٕے شہر، پادٕرۍ ٲسۍ تِمن ہٕندِس مضافاتس سٍتـ̡ ترٕہ شہر۔ \n20.\\tتہٕ کوہات کِس اولادَن ہٕندِس عیالس تہٕ یِم کوہات کِس اولادَس مَنٛز روٗدۍ، تِمن تہِ ٲسۍ افریم سٕندِس قبیلہٕ سٍتـ̡ پنہٕ نِس شہرس منز۔ \n21.\\tتکیازِ تِمو دِژ تِمن کوہ افرائیم کِس مضافاتس سٍتـ̡ شیکیم، یُس قاتل سٕندِ خٲطرٕ پناہ گاہُک شہر بنہٕ خٲطرٕ۔ تہٕ گیزر پننین مضافاتن سٍتـ̡ \n22. تہٕ کبزیم پننین مضافاتن سٔتۍ، تہٕ بیتھورون پننین مضافاتن سۭتۍ۔ ژور شہر۔ \n23.\\tتہٕ ڈین قبیلہٕ منز، ایلٹیکہ پننین مضافاتن سٍتۍ، گبتھن پننین مضافاتن سٍتۍ، \n24. ایجالون پننین مضافاتی علاقن سۭتۍ، گیتھریمن پننین مضافاتن سۭتۍ۔ ژور شہر۔ \n25. تہٕ مناسی ہٕندِس نصف قبیلس منز، تناخ پننین مضافاتن سٍتۍ، تہٕ گتھریمون پننین مضافاتن سٍتۍ۔ زٕ شہر۔ \n26.\\tسارِنٕے شَہرَن ہٕندِس مضافاتی علاقَس سٍتـ̡ یِم کوہاتھ کین شُرین ہٕندِس عیالس سٍتـ̡ باقٕے ٲسۍ۔ \n27.\\tتہٕ گرشون سٕندِس شُرین سٍتـ̡ ، لاوِین ہٕندِس خاندانس منز، یِمو دِژ بشانس مَنٛز گولان سٍتـ̡ تٔمِس مضافاتس سٍتـ̡ ، {یُس قاتل سٕندِ خٲطرٕ پناہ گاہُک شہر بنہٕ خٲطرٕ﴾۔ تہٕ بیشترہ سٕندِس مضافاتس سٍتـ̡ ۔ زٕ شہر۔ \n28.\\tتہٕ اِساکار قبیلہٕ منز، کِشون پنہٕ نِس مضافاتس سٍتۍ، دبارہ پنہٕ نِس مضافاتس سٍتۍ، \n29. جرموتھ پننس مضافاتی علاقن سۭتۍ، اینگنیم پننس مضافاتی علاقن سۭتۍ۔ ژور شہر۔ \n30.\\tتہٕ آشر قبیلہٕ منز، مشعل پننِس مضافاتس سٍتۍ، عبدون پننین مضافاتن سٍتۍ، \n31. ہیلکاتھ پننین مضافاتی علاقن سۭتۍ، تہٕ ریہوب۔ ژور شہر۔ \n32. تہٕ نفتالی قبیلہٕ منزٕ ، گلیل کِس مضافاتس منز کیدیش ، قاتل سٕندِ خٲطرٕ پناہ گاہُک شہر بنہٕ۔ تہٕ ہموتھدور پننین مضافاتن سٍتۍ، تہٕ کارتن پننین مضافاتن سٍتۍ۔ تریہ شہر۔ \n33.\\tگرشونیٹکۍ سٲری شہر ٲسۍ پننین خاندانن ہندِ مطٲبق تُہ شہر تہندِ مضافاتی علاقن سٍتۍ۔ \n34. تہٕ میراری کین بچن ہٕندِس عیالس سٍتـ̡ باقٕے لاوِین ہٕندِس عیالس سٍتـ̡ زبولون قبیلہٕ منز، جوکنیم تہٕ کرتہ ہٕندِس مضافاتس سٍتـ̡ ۔ \n35. دمنہ پننین مضافاتن سۭتۍ، نہلال پننین مضافاتن سۭتۍ۔ ژور شہر۔ \n36.\\tتہٕ روبن قبیلہٕ منز، بیزر پننِس مضافاتس سٍتۍ، تہٕ جاہزاہ پنہٕ نِس مضافاتس سٍتۍ، \n37. کیڈیموتھ پننس مضافاتی علاقن سۭتۍ، تہٕ میفاتھ پننین مضافاتن سۭتۍ۔ ژور شہر۔ \n38.\\tتہٕ گاد قبیلہٕ منز، رموتھ گُلعادس مَنٛز پننِس مضافاتس سٍتۍ، {یُس} قاتلَن ہٕندِ خٲطرٕ پناہ گاہُک شہر بَنُن۔ تہٕ مہانیم پَنٕنِس مضافاتس سٍتۍ، \n39. ہیشبن پننین مضافاتی علاقن سۭتۍ، جازر پننین مضافاتی علاقن سۭتۍ۔ کل ژور شہر۔ \n40.\\tیێمہِ سٍتـ̡ سارِنٕے شہر یِمن ہٕندِس عیالس سٍتـ̡ یِم لاوِین ہٕندِس خاندانس مَنٛز باقٕے ٲسۍ، تِمن ہٕندِس بَہہ شہرس سٍتـ̡ ٲسۍ۔ \n41. لاوِین ہٕندِس سارِنٕے شہرس مَنٛز ٲسۍ تِمن ہٕندِس مضافاتی علاقس سٍتـ̡ ژتٲجی تہٕ ٲٹھ شہر۔ \n42.\\tیم شہر ٲسۍ پریتھ کانہہ یتھ اندۍ پکھۍ پنن مضافاتی علاقہ اوس: یتھے پاٹھۍ ٲسۍ یم سٲری شہر۔ \n43.\\tتہٕ خداوند دِژ سٲرۍسٕے زمینہٕ یُس تِمن ہٕندِس مٲلِس دِنُک حلف اوس دِنہٕ آمُت۔ تہٕ تِمو رٔٹِتھ تہٕ روٗدۍ اَتھ مَنٛز روزان۔ \n44. تہٕ خداوند دِژ تِمن اندۍ پکھۍ آرام دِنہٕ، یُس تٔمۍ پننین مٲلن سٍتـ̡ قسم دِژمُت اوس، تہٕ تِمن برونہہ کُن اوس نہٕ تِہندِ سارِنٕے دُشمن ہُند کانہہ نفر کھڑا ۔ خداوند دِژ تِہٕندِس سارِنٕے دُشمن تِمن ہٕندِس اتھس مَنٛز۔ \n45. یُس خداوند اسرٲیلِس گرس سٍتـ̡ کتھ کٔرمٕژ آسہِ، سُہ چُھہ نہٕ ناکام سپدان۔ سارِوٕے سپُد سپدُن۔","1. یشوع ہن بُلوو روبینس تہٕ گادِس تہٕ منسیہٕکۍ نصف قبیلہٕ، \n2. تہٕ ووٚنُن تِمَن زِ یُس موسیٰ سُند بندہ چُھہ تۅہہِ حُکُم دِژمُت سُہ چُھہ پورٕ کٔرِمُت، تہٕ یُس میہ تۅہہِ حُکُم دِژمُت چُھ، تِمن سٍتـ̡ چُھکھ میانہِ آوازِ ہٕنز اطاعت کٔرمٕژ۔ \n3. توے چُھہ نہٕ از تام پننین بٲے ترٲومٕتۍ، مگر چُھکھ خداوند پنُن خدایہ سُند حُکُم برقرار تھاوان۔ \n4. تہٕ وُنہِ چُھہ خداوند تُہندِ خدایہِ تُہٕندٮ۪ن باین ہُند وعدٕ کوٚرمُت، یُس تِمن ہُند وعدٕ اوس کوٚرمُت، تێلہِ گژھِو تُہۍ واپس تہٕ پَنٕنِس خٲمَس مَنٛز نِش یُس موسیٰ سٕندِس دٔسۍ دِژمُت چھُ۔ \n5. مگر یُس حکم تہٕ شریعت پورٕ کرُن، یُس موسیٰ سٕندِ خدایہِ سٕندِس بندس سٍتـ̡ دِیُتمُت چُھ، خداوند سٕندِس خداہس سٍتـ̡ محبت کرُن، تہٕ تٔمۍ سٕندِس سارِنٕے وتہِ پٲٹھـ̡ پٔکِنـ̡ تہٕ تٔمۍ سٕندِس حُکمن پیٹھ عمل کرُن، تہٕ تٔمِس سٍتـ̡ رٔٹِتھ روزُن، تہٕ پَنٕنہِ دِلہٕ سٍتـ̡ تہٕ سٲرۍسٕے روحہٕ سٍتـ̡ أمِس سٕنز خدمت کرٕنـ̡ ۔ \n6. یشوع ہن کٔر تِمن دُعا دُعا تہٕ سوزُن تِم تہٕ تِم گٔیہِ پننین خیمن منز۔ \n7.\\tیێلہِ اوس یشوع قبیلہٕ کِس أکِس نصفس مَنٛز بشانس مَنٛز قبضہ دِژمُت، مگر یشوع سٕندِس نصفس دِژ یشوع یَتھ طرفہٕ یِمن ہٕندِس بٲے مَنٛز یِمن ہٕندِس مغربس کُن۔ تہٕ یێلہِ یشوع ہن تِم تہندِس خیمن مَنٛز سوزمٕتۍ، تێمہِ کٔر تِمن دُعا دِنہٕ، \n8. تہٕ تٔمۍ ووٚن تِمن سٍتـ̡ کتھ زِ وارِیاہ دولت ہٮ۪تھ پَنٕنـ̡ خٲمَن مَنٛز واپس، تہٕ سٮ۪ٹھاہ چاروٲے سٍتـ̡ تہٕ سۄنہٕ سٍتـ̡ تہٕ پیتل تہٕ ششتٕرٕ سٍتـ̡ تہٕ سٮ۪ٹھاہ پلو ہیتھ واپس۔ \n9.\\tتہٕ روبن سٕندِ اولاد تہٕ جاد سٕندِ اولاد تہٕ منسی ہٕندِ نصف قبیلہٕ گٔیہِ واپس، تہٕ گٔیہِ بنی اسرٲیلِہ نشہِ شیلوہ منز، یُس کنعان کِس سرزمینس مَنٛز چُھ، یُس حضرت موسیٰ سٕندِ کلامَس مُطٲبق تِمن ہٕندِس ملکَس مُطٲبِق گٔیہِ۔ \n10.\\tتہٕ ییلہ تم اردن کِس سرحدس پیٹھ وٲتۍ، یُس کنعان کِس سرزمینس مَنٛز، روبن سٕندِ شُرۍ تہٕ جاد سٕندِ اولاد تہٕ منسیٰ سٕندِ نصف قبیلہٕ کٔر اَتہِ اردنُک اکھ قربان گاہ، یُس وچھنہٕ خٲطرٕ اکھ بٔڈ قربان گاہ اوس۔ \n11. تہٕ بنی اسرٲیلیو بوز زِ وچھ روبن سٕندِ اولاد، جاد سٕندِس اولادو تہٕ مناسشہ سٕندِس نصف قبیلہٕ سٍتـ̡ چُھ اردن کِس سرحدس مَنٛز کنعان کِس سرزمینس پیٹھ اکھ قربان گاہ بنوومُت۔ \n12.\\tتہٕ یێلہِ بنی اسرٲیلِیو یہِ بوٗز، بنی اسرٲیلِچ سورٕے جماعت گٔیہِ شیلوہس مَنٛز جمع یِمن خلاف جنگہٕ کرنہٕ مۅکھہٕ۔ \n13.\\tتہٕ بنی اسرٲیلیو سوز روبن سٕندِس اولادس تہٕ گاد کِس اولادس تہٕ مناشہ کِس نصف قبیلس کُن گلعاد کِس سرزمینس مَنٛز، الیعزر سُند نیچو فینہاس، \n14. تہٕ أمِس سٍتـ̡ دَہ شہزادٕ، پرٮ۪تھ أکِس سردارس سٍتـ̡ سارِنٕے قبیلن مَنٛز اکھ شہزادٕ۔ تہٕ پرٮ۪تھ أکِس اوس ساسہٕ بٔدۍ اسرٲیلـ̡ پى۪ٹھـ̡ پننین بابن ہٕندِس گرُک سربراہ۔ {سردار...: عبرانی۔ باپ سُند گر}\n15.\\tتہٕ تِم آیہِ روبن سٕندِس شُرین نِش، گاد کِس شُرین نِش، تہٕ مَنسہ کِس نصف قبیلس نِش، تہٕ تِمو ووٚن تِمن سٍتـ̡ کتھ باتھ کٔرِتھ، \n16. یِتھٕ پٲٹھۍ چُھ خداوند سٕنزِ سارِنٕے جماعت ونان زِ یہِ کُس جرم چُھ یُس تۅہہ اسرٲیلِکِس خداہس سٍتـ̡ کُس جرم کورمُت چُھ، یُس از دۅہہٕ خداوند سٕنزِ پیروی نِش پتھ کُن پھیُرِو، یێلہِ تہٕ ژے چُھہ اکھ قربان گاہ بنوومُت، یُتھ زن تُہۍ از دۅہہٕ خداوند سٕندِس خلاف بغاوت کٔرِو؟ \n17.\\tکیا پیور سُند بدکار چُھہ سانہِ خٲطرٕ واریاہ کم، یێمہِ نِش أسـ̡ از تام پاک سپدان چُھہ، حالانکہ خداوند سٕنزِ جماعتس مَنٛز اوس وُپھ، \n18.\\tمگر یێمہِ دۅہہ گژھہِ خداوند سٕنزِ پیروی کرنہٕ نِش پتھ کُنـ̡؟ تہٕ یێلہِ چُھہ یێلہِ یێلہِ خداوند سٕندِس سٍتـ̡ بغاوت کٔرِتھ، یێلہِ پۯاوِ سُہ سارِنٕے اسرٲیلِچ جماعت سٍتـ̡ شرارت کٔرِتھ۔ \n19. بہر حال، یێلہِ تُہٕندِس قبضس منز زمین ناپاک آسہِ، تێلہِ گژھِو خداوند سٕنزِ زمینہِ مَنٛز یێلہِ خداوند سُند خیمہ روزان چُھ، تہٕ اسہِ مَنٛز رٔٹِو اسہِ سٍتـ̡ بغاوت تہٕ اسہِ سٍتـ̡ بغاوت کٔرِو۔ \n20.\\tزرہ سٕندِس نیچوِس آچانن کٔر نہٕ ملعون چیزس مَنٛز گُناہ تہٕ سارِنٕے اسرٲیلِچ جماعت ہُند غصہٕ ووت نہٕ؟ تہٕ سُہ انسان سپُد نہٕ پننِس بدکارس مَنٛز کُنی زُن۔ \n21. اَمہِ پَتہٕ دِژ روبن سٕندِ اولاد، گاد سٕندِس اولادٕ تہٕ مَنسِہ ہٕندِس نصف قبیلہٕ سٍتـ̡ دِژ جواب تہٕ وونُن ساسہٕ بٔدۍ اسرٲیلِن ہٕندِس کلہٕ سٍتـ̡ \n22. خداین ہُند خدا، خداین ہُند خدا، سُہ چُھ زانان، تہٕ اسرٲیلِس گژھہِ زان۔ یێلہِ {یہِ} بغاوتس مَنٛز، یا اگر خداوند سٕنز خلاف ورزی آسہِ، (اسہِ بچاوُن نہٕ از دۅہہٕ،)\n23. زِ أسـ̡ چُھہ اَکھ قربان گاہ بنوومُت یُس خداوند سٕنزِ پیروی کرنہٕ نِش پھیرنہٕ خٲطرٕ، یا اگر اَتھ پیٹھ زٲلِتھ نذرانہ یا مازٕچ نذرانہ پیش کرٕن، یا اگر اَتھ پیٹھ امن ہٕنز قربانی پیش کرٕن، تیلہِ گژھہِ خداوند پانہٕ تقاضہٕ کرُن۔ \n24.\\tتہٕ یێلہِ أسـ̡ یہِ {یێمہِ} کہِ خوفہٕ سٍتـ̡ یہِ ونِتھ زِ یێلہِ یِنہٕ وٲلِس سٍتـ̡ چُھہ تُہٕندِس شُرِ سٍتـ̡ سانین شُرین سٍتـ̡ کتھ کٔرِتھ، یہِ ونِتھ زِ تُہٕندِس خدایہِ سٍتـ̡ کیا چُھہ تۅہہِ سٍتـ̡ خدایہِ سٍتـ̡ سٍتـ̡ کتھ کرٕنـ̡ ۔ {وقتس منز...: حب۔ پگہہ کُن}\n25. یێلہِ خداوند چُھہ اردن اسہِ تہٕ تۅہہِ درمِیان سرحد بنوومُت، اے روبن سٕندِ اولاد تہٕ گاد سٕندِ اولاد۔ تۅہہِ چُھہ نہٕ خداوند سٕندِس سٍتـ̡ کانہہ حصہٕ: یێتھے پٲٹھـ̡ گژھن سانین شُرین خداوند سٕندِ خوفہٕ نِش بچاوُن۔ \n26. تێمہِ کِنۍ أسـ̡ وۆن، أسـ̡ اسہِ اکھ قربان گاہ بناونٕچ تیٲری کرٕنۍ، نہ زالنہٕ خٲطرٕ تہٕ نہ قربانی خٲطرٕ: \n27. مگر یہِ گژھہِ اسہِ تہٕ تۅہہِ تہٕ سانین نسلن درمِیان گواہ بٔنِتھ، یُتھ أسۍ پننین زٲلِن نذرانہٕ سٍتـ̡ تہٕ سانین قُربٲنیو سٍتـ̡ تہٕ پننین امن نذرانہٕ سٍتـ̡ خداوند سٕنز خدمت کٔرِتھ۔ یُتھ زِ تُہٕندِ شُرِ گژھن نہٕ یِنہٕ وٲلِس وقتس سٍتـ̡ سانین شُرین ؤنِتھ زِ تۅہہِ چُھہ نہٕ خداوند سٕندِس سٍتـ̡ کانہہ حصہٕ۔ \n28. تێمہِ کِنۍ وۆن أسۍ زِ یہِ گژھہِ یێلہِ تِم اسہِ یا سانین نسلن یِنہٕ وٲلِس زمانس مَنٛز وَنُن، یُس أسـ̡ دُبارٕ وَنُن، یُس سانہِ آباؤ اجداد سٍتـ̡ دزنہٕ خٲطرٕ تہٕ نذرانہ باپَتھ بنوومُت چھُ۔ مگر یہِ چُھہ اسہِ تہٕ تۅہہِ درمِیان گواہ۔ \n29.\\tخدایہ کرِ نہ زِ أسۍ گژھہِ خداوند سٕنزِ پیروی کرنہٕ نِش بغاوت کٔرِتھ، تہٕ یُس خداوند سٕندِس خیمہ برونہہ کُن چُھہ زٲلِتھ نذرانہ کرنہٕ خٲطرٕ، مازٕچ نذرانہ باپتھ، یا قربان کرنہٕ خٲطرٕ اکھ قربان گاہ بناوُن۔ \n30.\\tتہٕ ییلہ فینہاس، پادٕر، تہٕ جمٲژ ہٕندِس شہزادن تہٕ ساسہٕ بٔدۍ اسرٲیلٕکۍ سربراہو یِم أمِس سٍتـ̡ ٲسۍ، تِم کتھ بوز یِم روبن سٕندِ شُرۍ تہٕ گاد سٕندِ شُرۍ تہٕ منشہ سٕندِ شُرۍ کٔرِتھ کٔرِتھ، تِمن گٔیہِ خۅش۔ {خۄش...: حب۔ تہنزِ نظرِ منز اوس اَصٕل\n31. تہٕ الیعزر سٕندِ نیچو فینہاسن ووٚن روبن سٕندِس اولادس تہٕ گاد سٕندِس شُرین تہٕ منسی سٕندِس اولادس وُچھن، از چُھہ أسـ̡ وُچھان زِ خداوند چُھہ اسہِ منز، کیازِکہِ یێلہِ چُھہ نہٕ خداوند سٕندِس سٍتـ̡ یِہ گناہ کورمُت، وۅنۍ چُھہ تۅہہ بنی اسرائیل خداوند سٕندِ اتھہٕ نِش نجات دِژمٕژ۔ {وۆن: عبرانی۔ تێلہِ}\n32.\\tتہٕ فینہاس، پادٕرۍ سُند نیچو تہٕ شہزادہٕ آو روبن سٕندِ اولادٕ تہٕ گاد سٕندِ اولادٕ پیٹھٕ جلعاد کِس سرزمینہٕ پیٹھٕ کنعان کِس سرزمینس تام تہٕ بنی اسرائیلس تام واپس۔ \n33. تہٕ یہِ کتھ گٔیہِ بنی اِسرٲیلِس خۄش۔ تہٕ بنی اسرٲیلِو کٔر خدایہ سٕندِس خٕلافس مَنٛز برکت، تہٕ تِمن ہٕندِس جنگس مَنٛز گژھنُک ارادٕ اوس نہٕ، یَتھ مَنٛز روبن تہٕ گاد سٕندِ بچہٕ روزان ٲسۍ۔ \n34.\\tتہٕ روبن سٕندِ شُرۍ تہٕ گاد سٕندِس اولادَس وُچھِتھ قربان گاہ {Ed}، تکیازِ یہِ آسہِ اسہِ درمِیان گواہ زِ خداوند چُھ خدا۔ {Ed: یعنی اکھ گواہ}","1. تہٕ یہٕ سپُد واریاہ کال پَتہٕ یێمہِ پَتہٕ خداوند یِمن سارِنٕے دُشمنن نِش اِسرٲیلِس آرام دِژمُت، یُس یشوع وٲنسہِ سٍتـ̡ وٲنسہِ سٍتـ̡ بُزرگ گومُت۔ {مُتٲثِر...: ہیب۔ دۅہن مَنٛز آو}\n2. تہٕ یشوع ہن کٔر سارنٕے اسرٲیلِس خٲطرٕ، تہٕ تِہندین بزرگن ہٕندِس کلس خٲطرٕ، تہٕ تِہندین قاضن تہٕ تِہندین افسرن ہٕندِ خٲطرٕ بُلاونہٕ آمُت، تہٕ تِمن وونُن زِ بہٕ چُھس بُزرگ گومُت: \n3. تہٕ تہٕ چُھہ وُچھمُت یُس خداوند تُہند خداہِ چُھہ یِمن سارِنٕے قومن سٍتـ̡ تُہٕندِ مۅکھہٕ سٍتـ̡ کورمُت۔ یُس خداوند تُہُند خدا چُھہ سُہ یُس تُہٕندِ خٲطرٕ جنگ کورمُت چُھ۔ \n4. وُچھِو مے ژے سٍتـ̡ یِم قوُم قرعہٕ سٍتـ̡ تقسیم کٔرۍمٕتۍ، یِم تُہٕندِس قبیلن ہٕندِ خٲطرٕ وَراثت بٔنِتھ، یِم میہ ژٔٹِتھ چھِ، یِم میہ ژٔٹِتھ چھِ۔ {مغربس کُن: ہیب۔ آفتاب لوسنہٕ وِزِ}\n5. تہٕ خداوند تُہند خدا، سُہ کٔرِن تِم تۅہہِ برونہہ کُن کٔڑِتھ تہٕ تُہٕندِس نظرِ نِش ژٔلِتھ کٔرِتھ۔ تہٕ تُہٕندِس خداہِ سٕندِس خداہِ سُند وعدٕ چُھہ تُہٕندِس زمینس پیٹھ قبضہ کٔرِتھ۔ \n6. تێمہِ کِنۍ گژھِو تۅہہ سٮ۪ٹھاہ بہادر یُس موسىٰ سٕنزِ شریعت کِس کتابہِ مَنٛز لیکھنہٕ آمُت چھُ، یُس نہٕ دٔچھُن اتھس یا کھوورِ طرفہٕ پھیرِو۔ \n7. یِمن قومن مَنٛز گژھِو نہٕ یِمن قومن مَنٛز یِم پانس مَنٛز روزان چھِ۔ تِمن ہٕندِس دیوتاہن ہُند ناو کٔرِو نہٕ تہٕ کٔرِو تِمن ہٕندِس سٍتـ̡ نَہ کٔرِو تہٕ تِمن ہٕندِس سٍتـ̡ کٔرِو نمُن: \n8. مگر رٔٹِو خداوند پنُن خدا، یِتھ کٔنۍ ژے از تام چُھکھ کوٚرمُت۔ {مگر ژٔٹِو...: یا، یێلہِ ژٔٹِتھ ژٔٹِو، بیترِ}\n9. کیازِکہِ خداوند چُھ توے برونہہ کُن بٔڈۍ قومن تہٕ مضبوطہٕ ژٔٹِتھ ژٔلِمُت، مگر {یێلہِ} تێلہِ چُھہ نہٕ از تام تہِ کانہہ تہِ انسان ژے برونہہ کُن کھڑا سپدِتھ۔ {خداوند سٕندِ خٲطرٕ...: یا، تیلہِ چُھہ خداوند چلاوُن}\n10. یێلہِ سُہ چُھہ تۅہہِ سٕندِ خٲطرٕ لڑان یُس تۅہہِ سٍتـ̡ وعدٕ کورمُت چُھ۔ \n11. تێمہِ کِنۍ کرو پانس سٍتـ̡ پٲٹھـ̡ ہوشیار یُس خداوند پنُن خدایہ سٍتـ̡ محبت کرُن۔ {تُہٕندِس پانس: ہیب۔ تُہٕندِس روحس سٍتـ̡\n12. نتہٕ یێلہِ تہٕ یێلہِ تہٕ یِمن قومن ہٕندِس باقیاتس سٍتـ̡ ژٔٹِتھ رٔٹِو، تہٕ یِمن سٍتـ̡ یِمن سٍتـ̡ خاندر کٔرِو، تہٕ تِمن نِش گژھِو تہٕ تِم تہٕ تُہٕندِس نِش۔ \n13. پَکہٕ پٲٹھـ̡ زانِو زِ خداوند تُہُند خدا کرِ نہٕ یِمن قومن مَنٛز کانہہ تہِ ژٔلِتھ ژٔلِتھ ژٔلِتھ۔ مگر تِم گژھن تۅہہِ ہٕندِس پھانس تہٕ جال تہٕ تُہٕندِس اندس مَنٛز تہٕ تۅہہِ أچھن مَنٛز کانٹہٕ بٔنِتھ، یوتام نہٕ تُہٕندِس خداہس دِژمٕژ چھِ۔ \n14.\\tتہٕ وُچھِو بہٕ سارِنٕے دِلَس مَنٛز تہٕ سارِنٕے روحن مَنٛز زانان زِ یِمن سارِنٕے نیکی چیزن مَنٛز چُھہ نہٕ اکھ تہِ چیز ناکام گومُت یُس خداوند تُہند خدایہ تُہٕندِس بارس مَنٛز کتھ کٔرمٕژ چھِ۔ سارِنٕے چُھہ تۅہہِ سٍتـ̡ سپُدمُت، {تہٕ} چُھہ نہٕ اکھ تہِ چیز ناکام گومُت۔ \n15. تێمہِ کِنۍ گژھہِ یہِ سپدُن، یێلہِ سٍتـ̡ سارِوٕے نیکی چیز یێلہِ تُہٕندِس خداہِ سٍتـ̡ چُھہ تۅہہِ سٍتـ̡ وعدٕ کورمُت۔ یێلہِ چُھہ خداوند تُہٕندِس خداہس سٍتـ̡ سارِنٕے بُرٕے چیٖز دِنہٕ آمُت، یوتام نہٕ سُہ تُہٕندِس خداہِ سٕندِ دِژمٕژ چُھہ تۅہہِ سٍتـ̡ یێمہِ سٍتـ̡ تُہٕندِس خداہس سٍتـ̡ دِژمُت چُھ۔ \n16. یێلہِ تُہۍ خداوند پنُن خدا سٕندِس معاہدٕچ خلاف ورزی کٔرِو، یُس تٔمۍ تُہُند حُکُم دِیُتمُت چُھ، تہٕ گٔژھِو باقین خداہَن ہٕنز خدمت کٔرِتھ تہٕ تِمن ہٕندِس سٍتـ̡ سجدہ کٔرِو۔ تێلہِ گژھہِ خداوند سُند غصہٕ تہٕ یُس تٔمۍ تۅہہِ دِژمُت چُھ، سُہ گژھِو جلدٕے ختم گٔژھِتھ یُس تٔمۍ دِژمُت چُھ۔","1. تہٕ یشوع کٔر اسرٲیلٕکۍ سارِنٕے قبیلہٕ شیکیمس مَنٛز جمع تہٕ کٔرٕن اسرٲیلٕکۍ بزرگن، تہٕ تِہندین کلہٕ تہٕ تِہندین قاضن تہٕ تِہندین افسرن ہٕندِ خٲطرٕ بُلاونہٕ۔ تہٕ تِمو کٔر خدایہِ سٕندِس برونہہ کُن پیش۔ \n2. تہٕ یشوع ہن سارنٕے لُکن ووٚن، یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند خدا، تُہند باپ اوس پرانہِ زمانس مَنٛز سٔہلاب کِس دوٚیمہِ طرفہٕ روزان، یێلہِ تہِ اوس ابراہیم سُند مول تہٕ ناخورُک مول تہٕ تِمو کٔر باقین دیوتاہن ہٕنز خدمت۔ \n3. تہٕ میہ نیو تُہند مول ابراہیم سٔہلاب کہِ دوٚیمہِ طرفہٕ تہٕ کٔرٕن تٔمِس سٲرۍسٕے کنعان کِس سرزمینس مَنٛز نِتھ تہٕ دیتُن تٔمِس اسحاق ۔ \n4. تہٕ مے دِژ اسحاق یعقوب تہٕ عیسوس تہٕ عیسوس تہٕ دِژمُت عیسوس پہاڑ سیرس تہٕ یِمن ہُند قبضہٕ کرنہٕ خٲطرٕ۔ مگر یعقوب تہٕ تٔمۍ سٕندِ شُرۍ گٔیہِ مصرس مَنٛز۔ \n5. میہ سوز موسیٰ تہٕ ہارون تہِ، تہٕ مے کٔر مصرس مُطٲبق یُس میہ تمن منز کورمُت اوس، تہٕ پتہٕ کٔر بہٕ ژے نیبر۔ \n6. تہٕ مے أنۍ تُہند مول مصرہٕ منزٕ نیبر، تہٕ تم وٲتۍ سمندرس کُن۔ تہٕ مصری لٔگۍ پننین مٲلن پتہٕ رتھن تہٕ گُرۍ سوارن سٍتـ̡ بحر احمرس تام۔ \n7. تہٕ یێلہِ تِمو خداوند سٕندِس دُعا کٔرِتھ، تٔمۍ ترووُن تۅہہِ تہٕ مصرین درمِیان انہِ گوٚٹ تہٕ تِمن سٍتـ̡ سمندرٕ تہٕ کورُن تِمن سٍتـ̡ ؤلِتھ ۔ تہٕ تێہٕنزِ أچھن وُچھمٕژ یُس میہ مصرس مَنٛز کیا کورمُت چُھ، تہٕ تُہۍ رودۍ واریاہس کالس بیابانن مَنٛز روزان۔ \n8. تہٕ بہٕ اوٚن ژے امورین ہٕندِس سرزمینس مَنٛز، یُس اردن کِس دوٚیمہِ طرفہٕ روزان اوس۔ تہٕ تِمو لوٚڑ تہٕ مے دِژ تِم تِمن ہٕندِس اتھس منز، یُس تِہٕندِس زمینس پیٹھ قبضہ کٔرِتھ۔ تہٕ مے کٔر تِم ژے برونہہ کُن تباہ ۔ \n9.\\tموآبُک بادشاہ زیپور سُند نیچو بالک ووٚتھ تہٕ کوٚرُن اسرٲیلِس سٍتـ̡ جنگ، تہٕ سوزُن بیور سُند نیچو بُلام تہٕ بُلوُن تۅہہِ بد دُعا کرنہٕ خٲطرٕ: \n10.\\tمگر بہٕ کٔر نہٕ بلام سُند بوزُن۔ تێمہِ کِنۍ کٔر تۅہہ وُنہِ تہِ دُعا دِنہٕ۔ \n11. تہٕ تم گٔے اردنس پیٹھ، تہٕ یریحو وٲتِتھ یریحا کِس لوکو سٍتـ̡ تہٕ یریحا ہٕندِس لوکو سٍتـ̡ تہٕ کٔرٕکھ تۅہہِ سٍتـ̡ اموریو تہٕ پیرزِیو تہٕ کنعانین تہٕ حِطیوں تہٕ گرگاشین، حِوِین تہٕ یبوسین سٍتـ̡ جنگ۔ تہٕ مے دِژ تِم چانہِ اتھس منز۔ \n12. تہٕ مے سوز ژے برونہہ کُن ہارنٹ، یُس تِم ژے برونہہ کُن ژٔلِتھ کٔرِتھ، حتیٰ کہ امورین ہٕندِس زٕ بادشاہس تہِ۔ {مگر} نہ پننہِ تلوار سٍتۍ، نہ پننہِ کمانہٕ سٍتۍ۔ \n13. تہٕ مے دِژ ژے سُہ زمین یتھ خٲطرٕ نہٕ تۅہہ محنت کٔر، تہٕ شہر یِم نہٕ تۅہہ بنٲومٕتۍ، تہٕ تِمن مَنٛز روزان چھِو۔ تِمن انگورن تہٕ زیتونن ہٕندِس باغس یِم ژے ووپدۍ، تِمن منز چُھہ نہٕ کھٮ۪وان۔ \n14. تێمہِ کِنۍ کرو خداوند سُند خوف تہٕ اخلاص تہٕ سچائی سان أمِس عبادت کٔرِو، تہٕ تِم خدایہ ترٲوِو یِمن ہٕنز خدمت تہٕ سٍتـ̡ خدایہِ سٍتـ̡ خدمت کٔرِو۔ تہٕ کٔرِو خداوند سٕنز خدمت۔ \n15. تہٕ یێلہِ تہٕ یێلہِ تۅہہِ خدایہِ سٕنز عبادت کرٕنـ̡ بد باسان چُھ، تێلہِ کٔرِو ژٲرِو اَمہ دۅہہٕ یێمِس سٍتـ̡ تُہۍ عبادت کٔرِو۔ چاہے تِم دیوتا یِمن سٍتـ̡ تُہٕندِس مٲلِس سٍتـ̡ عبادت کٔرِو یِمن سٍتـ̡ یێلہِ سٍتـ̡ تہٕ یێلہِ سٍتـ̡ أسـ̡ خدایہِ سٕنز خدمت کٔرِو۔ \n16.\\tتہٕ لوکو دیُت جواب تہٕ وونُن، خدایہ کرِ زِ أسۍ پزِ خدایہ ترٲوِتھ باقین دیوتاہن ہٕنز خدمت کرنہٕ خٲطرٕ۔ \n17.\\tخداوند سٕندِ خٲطرٕ، یُس اسہِ تہٕ سانین آباؤ اجداد مصر کہِ سرزمینہٕ منز، غلامی ہٕندِس گرٕ نِش نیبر کٔرِتھ، تہٕ یٔمۍ سانہِ نظرِ برونہہ کُن یِم بٔڈ نشانہٕ کٔرۍ، تہٕ یِمن سارِنٕے لُکن مَنٛز أسۍ گٔژھِتھ تہٕ یِمن سارِنٕے لُکن مَنٛز أسۍ پٔکۍ، یِمن سٍتـ̡ أسـ̡ پٔرِتھ پۯاونہٕ آمٕتۍ۔ \n18. تہٕ خداوند کٔر اسہِ سارِنٕے لُکہٕ نِش نِش یِم زمینس مَنٛز روزان ٲسۍ، حتیٰ کہ امورِین تہِ کٔڈِتھ کٔرِو أسۍ تہِ خداوند سٕنز خدمت۔ تِکیازِ سُہ چُھ سٲنـ̡ خدا۔ \n19. تہٕ یشوع ہن ووٚن لُکن زِ تُہۍ ہیکو نہٕ خداوند سٕنز عبادت کٔرِتھ، کیازِ سُہ چُھ اکھ پاک خدا۔ سُہ چُھ اکھ حسد کرن وول خدا۔ سُہ کرِ نہٕ تُہٕنزِ غلطی تہٕ تُہند گۅناہ معاف۔ {پاک خدا: ہیب۔ پاک خدا}\n20. یێلہِ تُہۍ خداوند ترٲوِو، تہٕ عجیب دیوتاہن ہٕنز عبادت کٔرِو، تێلہِ کرِ سُہ پھیرِتھ تہٕ تۅہہِ دِیہِ تکلیف تہٕ کھٮ۪یہِ تہٕ تمہِ پتہٕ کرِ تۅہہِ نیکی کرنہٕ۔ \n21. تہٕ لوکو ووٚن یشوعس نِش نہ۔ مگر أسۍ کرو خداوند سٕنز خدمت۔ \n22. تہٕ یشوع ہن ووٚن لُکن زِ تم چِھو پانس خلاف گواہ زِ تم چُھہ خداوند چُھہ تٔمِس سٕنزِ خدمت کرنہٕ خٲطرٕ منتخب کورمُت۔ تہٕ تِمو ووٚن، {أسـ̡ گواہ چِھہ}۔ \n23. تێمہِ وۆن، تِم عجیب دیوتا یِم پانس مَنٛز چھِ، تہٕ پَنُن دِل کٔرِو اسرٲیلِکِس خدایہِ سٕندِس خداہس کُن۔ \n24. تہٕ لُکن ووٚن یشوعہس زِ خداوند سُند خدا، أسۍ کرو أسۍ سٕنزِ آوازِ ہٕنز فرمانبردار۔ \n25. یشوع ہن کوٚر تمہِ دۅہہ لُکن سٍتـ̡ اکھ عہد تہٕ تِمن کٔرٕن شیکیمس مَنٛز اکھ قانون تہٕ حکم نامہٕ۔ \n26. تہٕ یشوع ہن لیچھ یِم لفظ خدایہ سٕنزِ شریعت کِس کتابہِ مَنٛز، تہٕ تُلُن اکھ بوٚڈ کٔن، تہٕ تھووُن أکِس بلوطس تَل یُس خداوند سٕندِس مقدس مقامس سٍتـ̡ اوس۔ \n27. تہٕ یشوع ہن سارِنٕے لُکن ووٚن، وُچھِو، یہِ کٔنہِ گژھہِ اسہِ خٲطرٕ گواہ۔ تِکیازِ أمِس چُھ خداوند سٕندِ سٲری کلام بوزمٕتۍ یِم تٔمۍ اسہِ سٍتـ̡ کٔرۍمٕتۍ، تێمہِ مۄکھٕ گژھہِ یہِ تۅہہِ ہٕندِ خٲطرٕ گواہ بنہِ، یێلہِ گژھہِ تُہٕندِس خداہس نِش انکار کرنہٕ۔ \n28. یِتھٕ پٲٹھـ̡ دِژ یشوع لُکھ پَنٕنـ̡ پَنٕنـ̡ وَرثس کُن۔ \n29.\\tتہٕ یِمو چیزو پَتہٕ سپُد یہِ زِ خداوند سُند خادم یُس نون سُند نیچو یشوع گۆو ہتھ تہٕ دَہ وُہُر وٲنسہِ۔ \n30.\\tتہٕ تِمو دفن تِمناثسراہس مَنٛز پننہِ وراثت کِس سرحدس مَنٛز، یُس گاش کِس بالہٕ کِس شمالس کُن افرائیم پہاڑس مَنٛز چھُ۔ \n31. تہٕ اسرٲیلَن کٔر یشوع سٕندِ سارِنٕے دۅہہٕ تہٕ یشوع سٕندِ سارِنٕے دۅہہٕ تہٕ یُس خداوند سٕندِ سارِنٕے کامہِ ہٕنز زان ٲس، یِم تٔمۍ اسرٲیلِس خٲطرٕ کٔرمٕژ ٲسۍ۔ {زیادٕ زندٕ...: عبرانی۔ یشوع سٕندِ پَتہٕ کٔرٕن تِمن ہٕندِس دۅہس زیٹھراوُن}\n32.\\tتہٕ یوسف سٕنزِ أڈجہِ یُس بنی اسرٲیلِو مصرہٕ منزٕ نِش اننہٕ آو، تِم کٔرٕکھ شیخمس مَنٛز دفن، یُس یعقوبن حمور سٕندِس مٲلِس حمورٕ سٕندِس نیچوِس ہتھ رۄپہٕ رۄپہٕ سٍتـ̡ ہیوٚت، تہٕ یہِ بنیوو یوسف سٕندِس اولادَن ہُند وٲرث۔ {ٹُکرٕ...: یا، کٹہٕ بچہٕ}\n33.\\tتہٕ ہارون سُند نیچو الیعزر موٗد۔ تہٕ تمو کٔر سُہ أکِس بالس مَنٛز دفن یُس تٔمِس نیچوِس فینہاس سٕندِس نیچوِس سٍتـ̡ اوس، یُس أمِس افرائیم کِس پہاڑس مَنٛز دِنہٕ اوس آمُت۔"];
